var e=JSON.parse(`[{"id":"qx-b2-001","clusterId":"B","werkstueckRef":"B.17","stufe":1,"question":"Welche Antwort auf diese beiden Aussagen trifft den Kern, ohne das Gespräch ins Gegenteil kippen zu lassen?","options":["Der erste Satz trifft eher zu, denn Menschen als Besitz zu halten ist unabhängig von der Epoche Unrecht, und wer es tat, trägt dafür die Verantwortung.","Beide Sätze sind verkürzt, denn der erste ersetzt das Verstehen der damaligen Menschen durch ein Urteil, der zweite verbietet das Urteilen ganz.","Der zweite Satz trifft eher zu, denn wer über Menschen von vor 250 Jahren urteilt, misst sie an heutigen Maßstäben statt an denen ihrer Zeit.","Beide Sätze sind halb richtig, denn die Sklaverei ist zu verurteilen, die Menschen von damals aber nicht, weil sie nach ihren Maßstäben handelten."],"correctIndex":1,"explanation":"Der erste Satz begeht den Fehler des Präsentismus: Er misst Menschen früherer Zeiten an Normen und Wissen von heute und hält das für das ganze Bild. Damit bleibt unverstanden, in welchem Weltbild, mit welchem Wissen und mit welchen Handlungsmöglichkeiten sie lebten. Die Gegenposition schießt übers Ziel hinaus: Wer Verstehen verlangt, muss deshalb nicht auf Bewertung verzichten. Das zeigt der Fall Thomas Jefferson: Den Kontext zu beachten entschuldigt die Sklaverei nicht, ihn zu ignorieren verhindert aber das Verständnis der Widersprüche, mit denen er rang. Jefferson nannte die Sklaverei in seinen „Notes on the State of Virginia“ selbst einen „unablässigen Despotismus“ und hielt zugleich die Unterlegenheit Schwarzer „nur als Verdacht“ für möglich. Falsch wird es erst, wenn Verurteilung oder Verklärung das Verständnis ersetzen. Gute Prüffrage: Versuche ich gerade, diese Person aus ihrer eigenen Realität heraus zu verstehen, oder benutze ich sie nur als Leinwand für heutige Urteile?","coreRule":"⚡ Verstehen und Urteilen schließen sich nicht aus. Falsch wird es, wenn das Urteil das Verständnis ersetzt.","quote":"Versuche ich gerade, diese Epoche/Person aus ihrer eigenen, komplexen Realität heraus zu verstehen?","quoteLabel":"Prüffrage:","beleg":"Werkstück B.17 (Kernidee; Kipppunkt)","status":"entwurf","scenario":"In einer Diskussion über historische Figuren sagt jemand: „Wer vor 250 Jahren Menschen als Besitz gehalten hat, war eben ein Verbrecher, und alle damaligen Zeitgenossen gleich mit. Da gibt es nichts zu verstehen.“ Eine andere Person entgegnet: „Das ist unfair, man muss jede Zeit an ihren eigenen Maßstäben messen. Urteilen darf man über die Vergangenheit gar nicht.“","kurz":"Der erste Satz ersetzt das Verstehen durch ein fertiges Urteil, der zweite verbietet das Urteilen gleich ganz. Beides verkürzt: Kontext zu beachten entschuldigt nichts, ihn zu ignorieren verbaut aber das Verständnis der Widersprüche damaliger Menschen.","prueffrage":"Gab es vor 250 Jahren schon Menschen, die Sklaverei öffentlich als Unrecht bezeichneten, und wie reagierte ihre Umgebung darauf?","rueckmeldung":[{"option":0,"text":"Dass Sklaverei Unrecht war und Verantwortung bleibt, stimmt. Die Antwort übernimmt aber „Da gibt es nichts zu verstehen“ und lässt es dabei bewenden: Das Urteil ersetzt das Verstehen, und „alle Zeitgenossen“ landen pauschal mit auf der Anklagebank."},{"option":2,"text":"Den Kontext ernst zu nehmen ist richtig, und heutige Maßstäbe unbedacht überzustülpen wäre ein Fehler. Daraus folgt aber kein Urteilsverbot: Verstehen erklärt, warum jemand so handelte, und entschuldigt es nicht. Der Satz verbietet, was sich mit Verstehen gut verträgt."},{"option":3,"text":"Die Sklaverei zu verurteilen ist berechtigt. Die Trennung, Menschen davon auszunehmen, weil sie nach ihren Maßstäben handelten, entschuldigt aber genau das, was Kontext nicht entschuldigt, und bleibt Antwort auf den zweiten Satz allein."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Jefferson, T. (1787): Notes on the State of Virginia, Query XVIII „Manners“ (Scholars' Lab, University of Virginia, Faksimile der Ausgaben 1784/1787)","oeffentlich":true,"url":"https://notes.scholarslab.org/milestones/manners.html","seite":"Query XVIII","abruf":"2026-10-12"},{"typ":"url","kurz":"Jefferson, T. (1787): Notes on the State of Virginia, Query XIV „Laws“ (Scholars' Lab, University of Virginia)","oeffentlich":true,"url":"https://notes.scholarslab.org/milestones/laws.html","seite":"Query XIV","abruf":"2026-10-12"},{"typ":"url","kurz":"Hunt, L. (2002): From the President: Against Presentism. Perspectives on History (American Historical Association)","oeffentlich":true,"url":"https://historians.org/perspectives-article/against-presentism-may-2002/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"3b30dc6061bf266c"}},{"id":"qx-b2-002","clusterId":"B","werkstueckRef":"B.17","stufe":2,"question":"Welche Entgegnung prüft die Schwärmerei von der „guten alten Zeit“ in der Sache, ohne selbst die Vorfahren abzuwerten?","scenario":"Beim Abendessen schwärmt ein Freund nach einem Historienfilm, der um 1800 spielt: „Früher waren die Menschen naturverbundener, hatten stärkere Gemeinschaften und keinen Stress. Wir sollten wieder so leben.“","options":["Man stellt der Schwärmerei überprüfbare Lebensdaten gegenüber, etwa dass die Lebenserwartung um 1800 in keiner Weltregion über 40 Jahren lag, auch wegen früh sterbender Kinder.","Man fragt ihn, ob er für ein Leben wie im Film auch auf Zahnarzt, Heizung und Kühlschrank verzichten würde, und zeigt damit, dass seine Forderung nicht ernst gemeint sein kann.","Man erklärt die Schwärmerei mit der Nostalgie nach dem Historienfilm, die es in jeder Epoche gab, und folgert daraus, dass seine Aussagen über Natur und Gemeinschaft um 1800 falsch sind.","Man hält ihm vor, dass er mit seiner Sehnsucht nach 1800 Medizin und Komfort von heute geringschätzt, und verlangt von ihm mehr Dankbarkeit für das Leben, das er heute führen darf."],"correctIndex":0,"explanation":"Die Schwärmerei pickt Ästhetisches heraus (schöne Kleider, keine Smartphones) und blendet Hunger, Krankheiten, Kindersterblichkeit, erdrückende soziale Kontrolle und fehlende Rechte aus. Der stärkste Einwand setzt dort an, wo sich etwas überprüfen lässt: Lebensdaten sind Tatsachen, kein Werturteil, und sie stellen das idealisierte Bild auf die Probe. Gegen Verklärung hilft der Blick auf den ganzen Alltag der Epoche, ohne die Menschen von damals herabzusetzen. Die Frage nach Zahnarzt, Heizung und Kühlschrank wirkt wie ein anschaulicher Test, trifft aber die Person und nicht das Bild der Zeit. Dass Sehnsucht nach früher in jeder Epoche vorkommt, erklärt ihre Herkunft, aber nicht, ob das Bild von 1800 stimmt. Der Vorwurf der Undankbarkeit klingt nach Wertschätzung der Gegenwart, ersetzt aber die Prüfung durch einen Appell.","coreRule":"⚡ Gegen die Verklärung der Vergangenheit helfen überprüfbare Daten über den ganzen Alltag der Epoche, nicht ihre Verurteilung.","beleg":"Werkstück B.17, Abschnitt „Die zweite, subtilere Falle: Die naive Romantisierung“ und Abschnitt „Bei Esoterik & New Age“; Fn. gl-b-lebenserwartung (Dattani u. a. 2023, Our World in Data)","status":"freigegeben","freigabe":{"datum":"2026-10-15","pruefsumme":"5f2abf3c28865015","vermerk":"Prüfpult (Sturm, erste Charge nach den neuen falschen Optionen)"},"kurz":"Wer das Bild von 1800 an überprüfbaren Lebensdaten misst, prüft es in der Sache und lässt die Menschen von damals und den Freund in Ruhe. Der naheliegende Fehler wäre, ihn zu beschämen oder seine Sehnsucht zu erklären, statt das Bild zu testen.","prueffrage":"Welche Seiten des damaligen Lebens zeigt ein Historienfilm, und welche lässt er meistens weg?","rueckmeldung":[{"option":1,"text":"Der Test mit Zahnarzt, Heizung und Kühlschrank ist anschaulich und erinnert an Dinge, die damals fehlten. Er setzt aber an der Person an und zeigt sie als unernst, statt zu klären, ob das Bild von 1800 stimmt."},{"option":2,"text":"Dass es Sehnsucht nach früher in jeder Epoche gab, trifft zu und erklärt, woher seine Schwärmerei kommt. Ob seine Aussagen über Natur und Gemeinschaft um 1800 stimmen, folgt daraus nicht: Das entscheiden die Tatsachen, nicht die Herkunft."},{"option":3,"text":"Mehr Dankbarkeit zu fordern klingt nach Wertschätzung der Gegenwart. Es ist aber ein Appell an sein Gewissen und wertet ihn ab, ohne etwas am Bild von 1800 zu prüfen."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dattani, S. u. a. (2023): Life Expectancy. Our World in Data","oeffentlich":true,"url":"https://ourworldindata.org/life-expectancy","abruf":"2026-10-12"},{"typ":"url","kurz":"Hunt, L. (2002): From the President: Against Presentism. Perspectives on History (AHA)","oeffentlich":true,"url":"https://historians.org/perspectives-article/against-presentism-may-2002/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Clauss, M. (2009): Ritter und Raufbolde. Vom Krieg im Mittelalter. Darmstadt: Primus","oeffentlich":false,"seite":"S. 7–8, 75–77"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"5f2abf3c28865015"}},{"id":"qx-b2-003","clusterId":"B","werkstueckRef":"B.17","stufe":3,"question":"Du hörst in einer Diskussion: „Thomas Jefferson hatte Sklaven – also war er ein monströser Heuchler.“ Jemand kontert: „Damals dachten eben alle so, also darf man ihn nicht verurteilen.“ Dann kommt der Hinweis, dass Jefferson die Sklaverei in einem eigenen Buch einen „unablässigen Despotismus“ nannte und schrieb, er zittere um sein Land, wenn er bedenke, dass Gott gerecht sei – im selben Buch äußerte er „nur als Verdacht“, Schwarze seien Weißen an Körper und Geist unterlegen. Was folgt daraus für das Argument „Damals dachten alle so“?","options":["Der Kontext verbietet jede Bewertung, weil Menschen einer fremden Epoche nur an den Maßstäben ihrer eigenen Zeit gemessen werden dürfen.","Der Kontext erklärt, aber entschuldigt nicht: Jefferson sah den Widerspruch selbst, und diesen zu verstehen bringt mehr als ein Etikett.","Der Kontext entlastet Jefferson weitgehend, weil Sklaverei damals als natürliche Ordnung galt und er sie nur kritisch kommentierte.","Der Kontext ist wertlos, weil es in jeder Zeit Menschen gab, die anders dachten als die Mehrheit, und an ihnen wird jede Figur gemessen."],"correctIndex":1,"explanation":"Beide Kurzschlüsse greifen zu kurz: weder „monströser Heuchler“ noch „Kind seiner Zeit, also unschuldig“. Dass alle gleich dachten, trifft nicht zu: Jefferson nannte die Sklaverei selbst einen „unablässigen Despotismus“, äußerte im selben Buch aber zugleich „nur als Verdacht“, Schwarze seien Weißen an Körper und Geist unterlegen. Den Widerspruch sah er also selbst. Das entschuldigt die Sklaverei nicht, aber es zu ignorieren, verhindert das Verständnis der tiefen Widersprüche, mit denen historische Akteure rangen.","coreRule":"⚡ Kontext ist eine Erklärung, kein Freispruch – und ohne ihn bleibt das Urteil blind.","beleg":"Werkstück B.17 (Anwendung: Bewertung historischer Figuren; Jefferson)","status":"freigegeben","freigabe":{"datum":"2026-10-13","pruefsumme":"4df819394debbbd9","vermerk":"Prüfpult"},"scenario":"","kurz":"Dass alle so dachten, stimmt hier nicht: Jefferson nannte die Sklaverei selbst „unablässigen Despotismus“ und äußerte zugleich den „Verdacht“, Schwarze seien unterlegen. Er sah den Widerspruch also selbst. Das entschuldigt nichts, erklärt aber mehr als ein Etikett.","prueffrage":"Was hat Jefferson selbst über die Sklaverei geschrieben, und deckt sich das mit der Behauptung, alle hätten damals gleich gedacht?","rueckmeldung":[{"option":0,"text":"Kontext gehört zum Verstehen einer Person tatsächlich dazu. Ein Bewertungsverbot folgt daraus aber nicht, zumal Jefferson die Sklaverei selbst „Despotismus“ nannte und sich so an seinen eigenen Maßstäben messen lassen muss."},{"option":2,"text":"Die Sklaverei war damals weit verbreitet, das stimmt. Dass sie allgemein als natürliche Ordnung galt, passt aber nicht zu Jeffersons eigenen Worten. Kritische Kommentare entlasten ihn auch nicht, sie zeigen eher, dass er den Widerspruch kannte."},{"option":3,"text":"Dass es auch damals Menschen gab, die anders dachten, trifft zu und widerlegt „alle dachten so“. Daraus folgt aber nicht, dass Kontext wertlos wäre. Er hilft zu verstehen, wie Einsicht und Handeln so weit auseinandergehen konnten."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Jefferson, T. (1787): Notes on the State of Virginia, Query XVIII „Manners“ (Scholars' Lab, UVA)","oeffentlich":true,"url":"https://notes.scholarslab.org/milestones/manners.html","seite":"Query XVIII","abruf":"2026-10-12"},{"typ":"url","kurz":"Jefferson, T. (1787): Notes on the State of Virginia, Query XIV „Laws“ (Scholars' Lab, UVA)","oeffentlich":true,"url":"https://notes.scholarslab.org/milestones/laws.html","seite":"Query XIV","abruf":"2026-10-12"},{"typ":"url","kurz":"Hunt, L. (2002): Against Presentism. Perspectives on History (AHA)","oeffentlich":true,"url":"https://historians.org/perspectives-article/against-presentism-may-2002/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"4df819394debbbd9"}},{"id":"qx-b2-004","clusterId":"B","werkstueckRef":"B.17","stufe":4,"question":"Welche Rückfrage prüft die Behauptung am besten, ohne sie sofort zu verwerfen oder zu übernehmen?","scenario":"Ein Politiker beschwört „die guten alten 50er“ und nennt heutige gesellschaftliche Veränderungen „Verfall und Dekadenz“.","options":["Wie erinnern sich ältere Menschen, die die 50er selbst erlebt haben, an jene Zeit, und würden sie gern wieder so leben wie damals?","Was war in den 50ern besser als heute, etwa Zusammenhalt oder Sicherheit, und was davon ist seither verloren gegangen und ließe sich zurückholen?","Welche heutigen Veränderungen meint er genau mit „Verfall und Dekadenz“, und seit wann lassen sie sich in der Gesellschaft beobachten?","Wie sahen Alltag, Rechte und Gesundheit damals wirklich aus, und wozu wird das Bild heute gebraucht, etwa um Wandel als Verfall darzustellen?"],"correctIndex":3,"explanation":"Eine „goldene“ Vergangenheit ist oft ein idealisiertes Zerrbild: Man pickt die angenehmen Seiten heraus (schöne Kleider, keine Smartphones) und blendet den Rest aus, etwa hohe Kindersterblichkeit, fehlende Rechte oder soziale Kontrolle. Außerdem dient ein solches Bild häufig dazu, gegenwärtige Veränderungen, zum Beispiel mehr Rechte für Minderheiten, als Verfall darzustellen. Eine gute Prüfung fragt deshalb zweierlei: Wie sah der tatsächliche Alltag der Epoche aus, und welche Funktion hat das Bild in der heutigen Debatte? So wird die Behauptung weder pauschal abgetan noch übernommen.","coreRule":"⚡ Prüfe bei jeder „guten alten Zeit“, wie der Alltag damals tatsächlich aussah und wofür das Bild heute gebraucht wird.","beleg":"Werkstück B.17 (Anwendung: Verschwörungsmythen, rechts-konservative Variante; Red Flags)","status":"entwurf","kurz":"Eine „goldene“ Vergangenheit wählt oft nur das Angenehme aus und blendet Rechte, Gesundheit und Kontrolle aus. Zugleich kann das Bild dazu dienen, Wandel als Verfall darzustellen. Gute Prüfung fragt nach dem wirklichen Alltag und nach der Funktion des Bildes.","prueffrage":"Für wen waren die 50er „gut“, und wer hätte damals wohl ganz anders darüber gesprochen?","rueckmeldung":[{"option":0,"text":"Zeitzeugen sind eine wertvolle Quelle, aber auch Erinnerung wählt aus und färbt nostalgisch. Es bleibt offen, wie der Alltag insgesamt aussah und wofür das Bild heute in der Debatte eingesetzt wird."},{"option":1,"text":"Hier steckt die Behauptung schon in der Frage: Es wird unterstellt, früher sei etwas besser gewesen und verloren gegangen. Geprüft wird sie so nicht, und ein Blick auf Schattenseiten der Zeit fehlt."},{"option":2,"text":"Klärt man, was genau gemeint ist und seit wann, wird die Behauptung greifbarer, das ist ein guter erster Schritt. Das Bild der 50er selbst bleibt dabei aber ungeprüft, ebenso, wozu es in der Debatte dient."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dattani, S. u. a. (2023): Life Expectancy. Our World in Data","oeffentlich":true,"url":"https://ourworldindata.org/life-expectancy","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Clauss, M. (2009): Ritter und Raufbolde. Vom Krieg im Mittelalter. Darmstadt: Primus","oeffentlich":false,"seite":"S. 7–8, 75–77"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"5f65cf8ccc7d7984"}},{"id":"qx-b2-005","clusterId":"B","werkstueckRef":"B.18","stufe":1,"question":"Was ist an dieser Begründung für das Weitermachen fehlerhaft?","options":["Sie schließt aus dem bisherigen Ausbleiben eines Schadens auf Sicherheit und deutet Schweigen als Zustimmung, obwohl es auch Selbstzensur sein kann.","Sie stützt sich auf die Einigkeit der Gruppe statt auf Gründe, obwohl die Zahl der Zustimmenden nichts darüber aussagt, ob die Konstruktion sicher ist.","Sie verallgemeinert aus nur drei Fällen; hätte die Konstruktion die Warnzeichen noch viele weitere Male ohne Schaden überstanden, wäre ihr Schluss tragfähig.","Sie setzt ihre Stellung als Leiterin ein, statt die Warnzeichen fachlich bewerten zu lassen, und ersetzt so die Prüfung der Konstruktion durch eine Anweisung."],"correctIndex":0,"explanation":"Zwei Schlüsse tragen hier nicht. Erstens: Dass dreimal nichts passiert ist, zeigt nicht, dass das Risiko klein ist. Ein Schaden, der bisher ausblieb, kann beim nächsten Mal eintreten. Genau so wurde bei der Challenger über Jahre der Dichtungsschaden als „annehmbares Risiko“ verbucht, weil Flug um Flug gut ging, bis der Start bei großer Kälte zur Katastrophe führte. Zweitens: Wer Bedenken ausdrücklich unerwünscht macht, darf Schweigen nicht als Zustimmung lesen. Ausbleibender Widerspruch kann auch Selbstzensur aus Angst vor Ausgrenzung sein.","coreRule":"⚡ Wer „bisher ging es gut“ als Beweis nimmt und Schweigen als Zustimmung liest, übersieht Risiko und Selbstzensur.","beleg":"Werkstück B.18 (Kernidee; Analyse: Die drei Stufen; Abschnitt „Die Nacht erzählt allerdings nur das Ende“; Fn. gl-b-normalisierung)","status":"entwurf","scenario":"Ein Projektteam hat dreimal in Folge Warnzeichen für ein Qualitätsproblem bemerkt, jedes Mal ohne sichtbaren Schaden. In der Sitzung sagt die Leiterin: „Bisher ist immer alles gut gegangen, also verkraftet die Konstruktion das. Wenn jemand Bedenken hat, soll er sie bitte für sich behalten, wir sind uns doch alle einig.“","kurz":"Dass bisher nichts passiert ist, zeigt nicht, dass das Risiko klein ist; der Schaden kann beim nächsten Mal kommen. Und wo Bedenken unerwünscht sind, kann Schweigen Selbstzensur sein statt Zustimmung.","prueffrage":"Was ist aus den drei Warnzeichen geworden, und wer im Team hat in der Sitzung überhaupt etwas dazu gesagt?","rueckmeldung":[{"option":1,"text":"Einigkeit sagt tatsächlich nichts über Sicherheit. Hier ist sie aber durch das Verbot von Bedenken erst hergestellt, und der Schluss aus der schadlosen Serie bleibt als eigener Fehler unbeachtet."},{"option":2,"text":"Nur um die Fallzahl geht es nicht: Auch viele weitere Fälle ohne Schaden würden nicht zeigen, dass das Risiko klein ist. Bei der Challenger ging es lange gut, bis es nicht mehr gut ging."},{"option":3,"text":"Die Anweisung der Leiterin verschärft das Problem, das stimmt. Der Fehler der Begründung liegt aber im Schluss aus dem bisherigen Ausbleiben eines Schadens und im Lesen von Schweigen als Zustimmung."}],"familie":"schweigen-ist-keine-zustimmung","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Columbia Accident Investigation Board (2003): Report, Bd. 1, Kap. 8 „History As Cause: Columbia and Challenger“","oeffentlich":true,"url":"http://s3.amazonaws.com/akamai.netstorage/anon.nasa-global/CAIB/CAIB_lowres_chapter8.pdf","seite":"S. 196","abruf":"2026-10-12"},{"typ":"url","kurz":"Rogers Commission (1986): Report, Bd. 1, Kap. V „The Contributing Cause of the Accident“ (NASA)","oeffentlich":true,"url":"https://www.nasa.gov/history/rogersrep/v1ch5.htm","abruf":"2026-10-12"},{"typ":"doi","kurz":"Esser, J. K.; Lindoerfer, J. S. (1989): Groupthink and the space shuttle Challenger accident. Journal of Behavioral Decision Making 2(3)","oeffentlich":false,"doi":"10.1002/bdm.3960020304","seite":"S. 173"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"92c154473269bbcb"}},{"id":"qx-b2-006","clusterId":"B","werkstueckRef":"B.18","stufe":2,"question":"Was ist an dieser Schlussfolgerung der Kollegin fehlerhaft?","scenario":"In der Teamsitzung stimmt dir eine Zahl nicht. Alle nicken, du schweigst – nicht weil du glaubst, die anderen wüssten es besser, sondern weil du nicht als Spielverderber dastehen willst. Später sagt dir eine Kollegin: „Du hast das ja einfach mitgetragen, also warst du überzeugt.“","options":["Sie hält dein Schweigen für Zustimmung, obwohl es auch aus Furcht vor sozialer Ablehnung entstehen kann und dann nichts über deine Überzeugung sagt.","Sie schließt aus dem Nicken der anderen im Team, dass die Zahl stimmt, obwohl die Zahl der Zustimmenden nichts darüber aussagt, ob die Zahl wahr ist.","Sie schließt aus deinem Schweigen in dieser einen Sitzung auf dein Verhalten in allen Teams, obwohl ein einzelner Vorfall dafür nicht ausreicht.","Sie kehrt die Beweislast um, als müsstest du die Zahl widerlegen, obwohl fehlender Widerspruch eine Zahl nicht belegt und derjenige sie belegen muss, der sie nennt."],"correctIndex":0,"explanation":"Äußeres Verhalten und innere Überzeugung fallen nicht zusammen. Es gibt zwei Gründe, sich einer Gruppe anzuschließen: Man hält die anderen für wissender (informativer Einfluss), oder man fürchtet Ausgrenzung, Lächerlichkeit oder Bestrafung (normativer Einfluss). Dein Schweigen entspringt dem zweiten Grund, und dann sagt das Nicken der Gruppe nichts darüber, was die Einzelnen wirklich denken. Genau so entsteht in eng verbundenen Gruppen die Illusion der Einstimmigkeit: Schweigen wird fälschlich als Zustimmung gedeutet, während Einzelne ihre Zweifel zurückhalten (Selbstzensur). In Asch-Experimenten gaben rund drei Viertel der Versuchspersonen mindestens einmal öffentlich eine offensichtlich falsche Antwort, weil alle anderen es taten (im Mittel gut ein Drittel der Antworten). Viele zweifelten dabei an der eigenen Wahrnehmung; manche aber sahen die richtige Antwort und schlossen sich trotzdem an, um nicht aus der Reihe zu fallen. Wer Einigkeit nur an äußerer Zustimmung misst, kann sich täuschen. Die anderen Deutungen nennen bekannte Denkfehler, passen aber nicht: Die Kollegin schließt nicht auf die Richtigkeit der Zahl, sondern auf deine Überzeugung. Sie verallgemeinert auch nicht auf andere Teams, sondern bezieht sich auf diese Sitzung. Und eine Beweislast für die Zahl mag bei dem liegen, der sie nennt, aber die Kollegin spricht nicht über die Zahl, sondern über dein Schweigen. Eine gute Frage wäre: „Welche Argumente haben wir noch nicht gehört oder trauen uns nicht auszusprechen?“","coreRule":"⚡ Schweigen ist kein Beleg für Zustimmung: Es kann auch aus Angst vor dem Gruppenurteil entstehen.","beleg":"Werkstück B.18 (Stufe 2; Symptom 6 Selbstzensur)","status":"entwurf","kurz":"Schweigen ist nicht gleich Zustimmung: Man kann sich anschließen, weil man Ausgrenzung scheut, und dann sagt das Mitgetragene nichts über die eigene Überzeugung. Genau so entsteht der Anschein von Einigkeit in einer Gruppe.","prueffrage":"Wie viele der Nickenden hatten vielleicht eigene Bedenken, und woran hätte die Kollegin das von außen erkennen können?","rueckmeldung":[{"option":1,"text":"Dass Zustimmung der Menge eine Zahl nicht wahr macht, stimmt. Die Kollegin behauptet aber gar nichts über die Zahl, sondern über deine Überzeugung. Ihr Fehler liegt darin, was sie aus deinem Mitgehen folgert."},{"option":2,"text":"Aus einem Einzelfall auf alles zu schließen, wäre tatsächlich ein Fehler. Die Kollegin redet aber nur über diese eine Sitzung und behauptet nichts über andere Teams. Ihr Schluss geht an anderer Stelle schief."},{"option":3,"text":"Fehlender Widerspruch belegt eine Zahl nicht, und belegen muss sie, wer sie nennt. Darum geht es der Kollegin aber nicht: Sie äußert sich nicht zur Zahl, sondern zu dem, was dein Schweigen über dich verraten soll."}],"familie":"schweigen-ist-keine-zustimmung","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Spielman, R. M.; Jenkins, W. J.; Lovett, M. D.: Psychology 2e, Kap. 12.4 „Conformity, Compliance, and Obedience“ (OpenStax)","oeffentlich":true,"url":"https://openstax.org/books/psychology-2e/pages/12-4-conformity-compliance-and-obedience","abruf":"2026-10-12"},{"typ":"doi","kurz":"Asch, S. E. (1956): Studies of Independence and Conformity: I. A Minority of One Against a Unanimous Majority. Psychological Monographs 70(9)","oeffentlich":false,"doi":"10.1037/h0093718","seite":"S. 10–11"},{"typ":"doi","kurz":"Deutsch, M.; Gerard, H. B. (1955): A Study of Normative and Informational Social Influences upon Individual Judgment. Journal of Abnormal and Social Psychology 51(3)","oeffentlich":false,"doi":"10.1037/h0046408","seite":"S. 629–633"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v6","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"7d310accedd890f9"}},{"id":"qx-b2-007","clusterId":"B","werkstueckRef":"B.18","stufe":3,"question":"Ein Kommentator sagt: „Der Gruppendruck in der Nacht davor erklärt alles.“ Welche Einschätzung dieser Erklärung passt am besten zur Schilderung?","options":["Sie greift zu kurz: Schon bei früheren Flügen waren Dichtringe angegriffen; weil diese Flüge gut gingen, galt der Schaden als annehmbar.","Sie trifft im Kern zu: Das Management überging am Vorabend die Warnung der eigenen Ingenieure, und darin liegt die eigentliche Ursache.","Sie greift zu kurz: Entscheidend war, dass die Einwände die oberste Startleitung nicht erreichten; das war vor allem ein Fehler im Meldeweg.","Sie greift zu kurz: Den Ausschlag gab die Kälte, für die die Dichtungen nicht zertifiziert waren; daran ändert kein Gruppendruck etwas."],"correctIndex":0,"explanation":"Eine einzelne dramatische Szene ist eine verlockende Ursache, aber selten die ganze. Hier hatten die Ingenieure dringend abgeraten, ihr Management revidierte die Warnung, und die oberste Startleitung erfuhr nach eigener Aussage nichts davon. Dahinter steht eine längere Vorgeschichte: Schon seit den ersten Flügen waren Dichtringe immer wieder angegriffen worden, ein Jahr zuvor nach Kältenächten besonders stark. Weil die Flüge trotzdem gut gingen, galt jeder neue Schaden als Beweis, dass die Konstruktion ihn verkraftet. Dieses Muster wird „Normalisierung der Abweichung“ genannt; die Untersuchung nach dem Absturz der Columbia 2003 fand es auch beim Isolierschaum wieder. Eine gute Ursachenanalyse fragt deshalb nicht nur, wer in der entscheidenden Nacht was sagte, sondern auch, welche Gewöhnung diese Entscheidung über Jahre vorbereitet hat. Dass das Management die Warnung überging, gehört zur Ursache, erklärt aber nicht, warum angegriffene Dichtringe überhaupt als annehmbar galten.","coreRule":"⚡ Wer ein Unglück mit der letzten Entscheidung erklärt, übersieht oft die Gewöhnung an Warnzeichen, die Jahre vorher begann.","beleg":"Werkstück B.18; Fn. gl-b-challenger (Rogers Commission 1986, Bd. 1, Kap. V; Vaughan 1996); Fn. gl-b-normalisierung (CAIB 2003, Bd. 1, Kap. 8, S. 196–197)","status":"entwurf","scenario":"Vor einem Raumfähren-Start bei Kälte rieten Ingenieure des Herstellers der Feststoffraketen dringend ab: Die Dichtungen waren bei Kälte nicht für einen sicheren Start zertifiziert. Ihr Management gab am Vorabend dennoch die Freigabe, und die oberste Startleitung sagte später aus, von den Einwänden nichts gewusst zu haben. Schon bei früheren Flügen waren Dichtringe angegriffen worden, doch weil die Flüge gut gegangen waren, wurde der Schaden als „annehmbares Risiko“ geführt. Der Start endete in der Katastrophe.","kurz":"Der Gruppendruck in der Nacht ist nur ein Teil der Ursache. Wer die eine dramatische Szene für die ganze Erklärung hält, übersieht die Vorgeschichte: Weil frühere Flüge trotz angegriffener Dichtringe gut gingen, galt der Schaden längst als annehmbar.","prueffrage":"Seit wann waren Dichtringe angegriffen, und wie wurde damit bei den Flügen davor umgegangen?","rueckmeldung":[{"option":1,"text":"Dass das Management die Warnung am Vorabend überging, gehört tatsächlich zur Ursache. Es erklärt aber nicht, warum angegriffene Dichtringe überhaupt als annehmbar galten, und damit ist die Nacht nicht „die eigentliche Ursache“."},{"option":2,"text":"Dass die Einwände die Startleitung laut ihrer Aussage nicht erreichten, ist ein wichtiger Teil der Entscheidungsnacht. Auch das bleibt eine einzelne Szene und erklärt nicht die jahrelange Gewöhnung an Schäden an den Dichtringen."},{"option":3,"text":"Die fehlende Zertifizierung für Kälte war ein Risikofaktor. „Den Ausschlag gab die Kälte“ geht aber zu weit: Sie erklärt nicht, warum trotz Warnung und früherer Dichtringschäden überhaupt gestartet wurde."}],"familie":"schweigen-ist-keine-zustimmung","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Rogers Commission (1986): Report, Bd. 1, Kap. V (NASA)","oeffentlich":true,"url":"https://www.nasa.gov/history/rogersrep/v1ch5.htm","abruf":"2026-10-12"},{"typ":"url","kurz":"Columbia Accident Investigation Board (2003): Report, Bd. 1, Kap. 8 „History As Cause: Columbia and Challenger“","oeffentlich":true,"url":"http://s3.amazonaws.com/akamai.netstorage/anon.nasa-global/CAIB/CAIB_lowres_chapter8.pdf","seite":"S. 196–197","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Vaughan, D. (1996): The Challenger Launch Decision. Chicago: University of Chicago Press","oeffentlich":false}],"thema":"Technik und KI","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"a97313a1db620d05"}},{"id":"qx-b2-008","clusterId":"B","werkstueckRef":"B.18","stufe":4,"question":"Was ist an der Schlussfolgerung der Vorsitzenden am ehesten fragwürdig?","scenario":"Ein Vorstand will Gruppendenken vermeiden. In jeder Sitzung muss reihum ein Mitglied die Rolle des „Advocatus Diaboli“ spielen und gegen den Beschlussvorschlag argumentieren. Nach einem halben Jahr fällt auf: Die Beschlüsse fallen weiterhin sehr schnell und fast immer einstimmig. Der Teufelsanwalt bringt regelmäßig Einwände vor, die nach kurzer Diskussion allen als „bekannt“ gelten. Die Vorsitzende deutet das als Beweis, dass die Gruppe gründlich prüft.","options":["Fragwürdig ist das Tempo: Wer gründlich prüft, braucht Zeit, und Beschlüsse, die nach kurzer Diskussion fallen, sind wohl kaum gründlich durchdacht.","Fragwürdig ist die Einstimmigkeit: Fällt ein halbes Jahr lang fast alles einstimmig, spricht das für sich schon dafür, dass nachlässig geprüft wird.","Fragwürdig ist der Beleg: Einwände, die reihum aus Pflicht kommen und rasch als „bekannt“ gelten, zeigen noch keinen echten Widerspruch an.","Fragwürdig ist die Deutung: Gelten die Einwände rasch als „bekannt“, haben die jeweiligen Teufelsanwälte wohl zu schwache Gegenargumente gewählt."],"correctIndex":2,"explanation":"Ein Einwand, den jemand pflichtgemäß vorbringt, weil er an der Reihe ist, zeigt noch nicht, dass die Gruppe Widerspruch ernst nimmt. Das Ritual kann den Eindruck gründlicher Prüfung erwecken, ohne dass echter Widerspruch stattfindet. Dass hier jeder Einwand schnell als „bekannt“ gilt und die Beschlüsse einstimmig bleiben, ist eher ein Warnsignal. Echter, selbst geäußerter Widerspruch ist dagegen nicht an eine Rolle gebunden und wird eher als ernsthafte Alternative geprüft. Laut Experimenten war von sich aus geäußerter Widerspruch jeder geprüften Form des bestellten Teufelsanwalts überlegen. Das heißt nicht, dass die Rolle wertlos wäre, wohl aber, dass sie echten Widerspruch nicht ersetzt. Einstimmigkeit allein beweist weder Sorgfalt noch Nachlässigkeit; entscheidend ist, ob abweichende Meinungen real geäußert und ernsthaft geprüft werden können.","coreRule":"⚡ Ein bestellter Widerspruch ersetzt nicht die Kultur, in der echter Widerspruch erwünscht ist.","beleg":"Werkstück B.18 (Verbindungen: Advocatus Diaboli)","status":"entwurf","kurz":"Einwände, die reihum aus Pflicht kommen und rasch als „bekannt“ abgehakt werden, zeigen noch keinen echten Widerspruch. Das Ritual kann Gründlichkeit nur vortäuschen, und genau das wertet die Vorsitzende als Beweis.","prueffrage":"Hat schon einmal ein Einwand einen Beschluss verändert oder verzögert, und von wem kam er?","rueckmeldung":[{"option":0,"text":"Ein rascher Beschluss kann tatsächlich ein Warnsignal sein, aber Tempo allein beweist keine Oberflächlichkeit. Der eigentliche Schwachpunkt liegt woanders: Die Vorsitzende wertet pflichtgemäße Einwände als Beleg für gründliche Prüfung."},{"option":1,"text":"Dauernde Einstimmigkeit kann stutzig machen, doch sie beweist für sich genommen weder Sorgfalt noch Nachlässigkeit. Entscheidend ist, ob abweichende Meinungen real geäußert und ernsthaft geprüft werden können. Das Problem liegt bei dem, was als Beleg gilt."},{"option":3,"text":"Dass Einwände rasch als „bekannt“ gelten, liegt kaum an schwachen Argumenten einzelner Personen. Wer aus Pflicht widerspricht, bringt oft vorhersehbare Einwände vor. Das Problem steckt im Ritual, nicht in der Leistung der Teufelsanwälte."}],"familie":"schweigen-ist-keine-zustimmung","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Nemeth, C.; Brown, K.; Rogers, J. (2001): Devil's advocate versus authentic dissent: stimulating quantity and quality. European Journal of Social Psychology 31(6), 707–720","oeffentlich":false,"doi":"10.1002/ejsp.58","seite":"S. 707, 713–717"},{"typ":"url","kurz":"Behavioral Scientist (2018): Stop Playing Devil's Advocate, and Other Advice for Better Decision Making (Interview mit Charlan Nemeth)","oeffentlich":true,"url":"https://behavioralscientist.org/stop-playing-devils-advocate-and-other-advice-for-better-decision-making/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"a0eee3911419a7ec"}},{"id":"qx-b2-009","clusterId":"B","werkstueckRef":"B.19","stufe":2,"question":"Welche Frage prüft die Werbebehauptung am besten?","scenario":"Eine Broschüre für ein Nahrungsergänzungsmittel wirbt: „Studie belegt – zwei Gesundheitswerte verbessert!“ Im Kleingedruckten steht, dass die Studie insgesamt 50 verschiedene Gesundheitswerte erfasst hat. Über die übrigen 48 Werte schweigt die Broschüre.","options":["Wurde vor der Studie festgelegt, welche Werte als Erfolgskriterium gelten sollten, und wie sahen die übrigen gemessenen Werte aus?","Wurde die Studie mit den zwei verbesserten Werten in einer Fachzeitschrift veröffentlicht, und wie oft haben andere Forschende sie seither zitiert?","Wie lange dauerte die Studie mit den 50 Werten, und hielten die zwei verbesserten Werte auch an, nachdem die Teilnehmer das Mittel abgesetzt hatten?","Wer hat die Studie zu diesem Mittel bezahlt, und stand der Geldgeber in einer geschäftlichen Beziehung zum Hersteller, der die Broschüre verteilt?"],"correctIndex":0,"explanation":"Wer 50 Werte misst, bekommt allein durch Zufall bei einigen davon eine scheinbar „signifikante“ Veränderung, ganz ohne jede Wirkung des Mittels. Entscheidend ist deshalb, ob die zwei Werte schon vor der Messung als Ziel festgelegt waren oder ob man sie erst im Nachhinein aus den Ergebnissen herausgepickt hat. Das ist, als würde man erst auf die Scheunenwand schießen und dann die Zielscheibe um die dichtesten Einschusslöcher malen. Und nur wenn man die übrigen 48 Werte kennt, lässt sich einschätzen, ob die zwei Treffer ein Volltreffer oder ein Zufallscluster sind. Dass die Studie in einer Fachzeitschrift erschien und oft zitiert wurde, klingt nach Qualität, sagt aber nicht, ob aus 50 Werten die passenden zwei herausgesucht wurden. Dauer und Nachwirkung der Verbesserung sind eine sinnvolle Frage, betreffen aber eine andere Sache als die Auswahl der Werte. Die Geldgeber zu kennen hilft bei der Einordnung, beantwortet aber nicht, ob die zwei Treffer ein Zufallscluster sind.","coreRule":"⚡ Frag nie nur nach dem Treffer, sondern nach allen Schüssen und nach dem Zeitpunkt der Zielscheibe.","beleg":"Werkstück B.19 (Anwendung: Pseudomedizin und Nahrungsergänzungsmittel; Red Flags)","status":"entwurf","kurz":"Bei 50 gemessenen Werten verbessern sich zufällig einige, auch ohne Wirkung des Mittels. Entscheidend ist, ob die zwei Werte vorab als Ziel galten und wie die übrigen 48 aussahen, sonst zeichnet man die Zielscheibe um die Treffer.","prueffrage":"Was würdest du bei 50 gemessenen Werten erwarten, wenn das Mittel überhaupt nichts bewirkt?","rueckmeldung":[{"option":1,"text":"Eine Veröffentlichung samt vieler Zitate wirkt wie ein Gütesiegel. Sie sagt aber nicht, ob aus den 50 Werten nachträglich zwei passende herausgesucht wurden, und genau das bleibt offen."},{"option":2,"text":"Ob ein Effekt anhält, ist eine sinnvolle Frage. Sie betrifft aber eine andere Sache: Selbst ein lange anhaltender Wert kann ein Zufallstreffer unter 50 Messungen sein."},{"option":3,"text":"Wer das Geld gab, hilft bei der Einordnung, und ein Interessenkonflikt wäre ein Warnzeichen. Ob die zwei Treffer unter 50 Werten ein Zufallscluster sind, beantwortet das aber nicht."}],"familie":"muster-im-zufall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"CDC/CSTE (2013): Investigating Suspected Cancer Clusters and Responding to Community Concerns. MMWR 62(8)","oeffentlich":true,"url":"https://www.cdc.gov/mmwr/pdf/rr/rr6208.pdf","seite":"S. 21–22","abruf":"2026-10-12"},{"typ":"doi","kurz":"Nosek, B. A. u. a. (2018): The preregistration revolution. PNAS 115(11) (frei über PMC5856500)","oeffentlich":true,"doi":"10.1073/pnas.1708274114","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"21fe3c42f73287b2"}},{"id":"qx-b2-010","clusterId":"B","werkstueckRef":"B.19","stufe":3,"question":"Ein Team wertet die Daten einer großen Befragung ohne vorab festgelegte Hypothese aus und stößt auf eine auffällige Häufung. Was darf es mit diesem Ergebnis redlicherweise tun?","options":["Die Häufung von Rosenkohlvorliebe und Frühjahrsgeburtstagen als vorläufige Hypothese festhalten und an einer neuen, unabhängigen Stichprobe gezielt prüfen, bevor sie als Befund gemeldet wird.","Nach einem Drittfaktor suchen, der Rosenkohlvorliebe und Geburtsmonat verbindet, und die Häufung als Befund melden, sobald er aus den Daten herausgerechnet ist.","Die Häufung mit einem Signifikanztest an denselben 3.000 Datensätzen prüfen und als Befund melden, sobald der p-Wert unter 0,05 liegt.","Einen plausiblen Mechanismus zwischen Rosenkohlvorliebe und Geburtsmonat ausarbeiten und die Häufung als Befund melden, sobald dieser Mechanismus schlüssig klingt."],"correctIndex":0,"explanation":"Das Suchen nach Mustern ist legitim, denn so entstehen Hypothesen. Ein Arzt, der aus vielen unspezifischen Symptomen eine seltene Krankheit vermutet, tut genau das. Kritisch wird es erst, wenn der Fund als Beweis ausgegeben wird. In jeder ausreichend großen, zufälligen Datenmenge entstehen zwangsläufig Cluster, daher kann der erste Fund nur eine Hypothese sein. Erst die Prüfung an einem neuen, unabhängigen Datensatz zeigt, ob das Muster mehr ist als Rauschen. Einen Drittfaktor herauszurechnen ist sinnvoll, wenn ein Zusammenhang schon als echt gilt; hier ist aber erst offen, ob die Häufung mehr als Zufall ist, und das bleibt in denselben Daten ungeklärt. Ein Signifikanztest wirkt streng, doch ein p-Wert unter 0,05 beweist bei 40 durchsuchten Merkmalen wenig, weil bei so vielen Vergleichen irgendwo zufällig einer darunter liegt. Ein schlüssig klingender Mechanismus wirkt vernünftig, doch im Nachhinein lässt sich zu fast jedem Muster einer finden, deshalb prüft er nichts.","coreRule":"⚡ Ein gefundenes Muster ist der Anfang der Prüfung, nicht ihr Ergebnis.","beleg":"Werkstück B.19 (Adaptives Talent; Kipppunkt)","status":"entwurf","scenario":"Eine Forschungsgruppe hat 40 Merkmale von 3.000 Personen erhoben. Beim Durchsehen fällt auf, dass Menschen, die gern Rosenkohl essen, auffällig oft im Frühjahr Geburtstag haben. Die Gruppe überlegt, wie sie damit umgehen soll.","kurz":"Aus dem Durchsuchen von 40 Merkmalen kann eine Häufung rein zufällig entstehen. Der Fund ist daher nur eine Hypothese, und erst eine neue, unabhängige Stichprobe zeigt, ob mehr als Rauschen dahintersteckt.","prueffrage":"Wie viele Merkmalspaare lassen sich bei 40 Merkmalen überhaupt miteinander vergleichen, und wie viele davon fallen zufällig auf?","rueckmeldung":[{"option":1,"text":"Einen Drittfaktor herauszurechnen ist sinnvoll, wenn ein Zusammenhang schon als echt gilt. Hier ist aber offen, ob die Häufung überhaupt mehr als Zufall ist, und das lässt sich in denselben Daten nicht klären."},{"option":2,"text":"Ein Signifikanztest wirkt streng, wird hier aber an denselben Daten gemacht, in denen das Muster gefunden wurde. Bei 40 durchsuchten Merkmalen liegt zufällig irgendwo ein p-Wert unter 0,05."},{"option":3,"text":"Ein schlüssiger Mechanismus gibt dem Fund Rückhalt. Im Nachhinein lässt sich aber zu fast jedem Muster einer finden, deshalb zeigt er nicht, ob die Häufung über den Zufall hinausgeht."}],"familie":"muster-im-zufall","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Nosek, B. A. u. a. (2018): The preregistration revolution. PNAS 115(11) (frei über PMC5856500)","oeffentlich":true,"doi":"10.1073/pnas.1708274114","abruf":"2026-10-12"},{"typ":"url","kurz":"CDC/CSTE (2013): Investigating Suspected Cancer Clusters and Responding to Community Concerns. MMWR 62(8)","oeffentlich":true,"url":"https://www.cdc.gov/mmwr/pdf/rr/rr6208.pdf","seite":"S. 22","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"a1d2b654c64ee46b"}},{"id":"qx-b2-011","clusterId":"B","werkstueckRef":"B.19","stufe":4,"question":"Was sollte die Stadt als Erstes prüfen, bevor sie den Mast für die Häufung verantwortlich macht?","scenario":"In einer Straße mit rund 400 Bewohnern fiel einer Anwohnerin auf, dass mehrere Nachbarn erkrankt waren. Daraufhin begannen die Anwohner zu zählen und kamen auf neun Krankheitsfälle. Eine Lokalzeitung führt die Häufung auf den Mobilfunkmast am Ende der Straße zurück, der dort seit fünfzehn Jahren steht, und druckt eine Karte mit den Wohnorten der Erkrankten. Die Stadt will reagieren.","options":["Die Fälle noch einmal unabhängig nachzählen lassen, denn eine bestätigte Häufung ist schon ein Hinweis, dass vor Ort etwas dahintersteckt.","Prüfen, ob neun Fälle bei 400 Bewohnern auch zufällig zu erwarten sind, denn ein erst beim Zählen entdecktes Muster ist nur eine Vermutung.","Die Abstände der Wohnungen zum Mast genau vermessen, denn liegen die Fälle nahe am Mast, zeigt die Karte den Zusammenhang deutlich.","Die Erkrankten fragen, wann ihre Beschwerden begannen, denn begannen sie nach dem Bau des Masts, stützt die Reihenfolge den Verdacht."],"correctIndex":1,"explanation":"In einer ausreichend großen, zufälligen Datenmenge entstehen zwangsläufig Cluster und scheinbar unwahrscheinliche Muster, auch wenn nichts dahintersteckt. Hier kommt hinzu, dass die Häufung erst beim Zählen aufgefallen ist. Ein solches nachträglich gefundenes Muster ist nur eine Hypothese. Bevor man ihm eine Bedeutung beimisst, muss geklärt werden, ob schon der Zufall genügt, um neun Fälle unter rund 400 Bewohnern zu erklären, und der Zusammenhang muss an einem neuen, unabhängigen Datensatz getestet werden. Erneutes Zählen bestätigt nur dieselben Daten, aus denen das Muster überhaupt erst stammt. Abstände auf einer Karte verstärken den Eindruck, prüfen aber nicht, ob das Muster mehr ist als Zufall. Und weil der Mast seit fünfzehn Jahren steht, begannen praktisch alle Beschwerden nach seinem Bau; diese Reihenfolge unterscheidet also nichts.","coreRule":"⚡ Bevor ein Cluster eine Ursache bekommt, muss der Zufall als Erklärung ausgeschlossen sein.","beleg":"Werkstück B.19 (Red Flags: Cluster in geografischen Daten; Kontext & Tiefe; Das Adaptive Talent; Anti-Denkmuster)","status":"entwurf","kurz":"Entdeckt man ein Muster erst beim Zählen, ist es nur eine Vermutung. Zuerst ist zu klären, ob neun Fälle bei rund 400 Bewohnern auch ohne jede Ursache zu erwarten sind, denn in genug Daten entstehen zwangsläufig scheinbare Häufungen.","prueffrage":"Wie viele Krankheitsfälle sind bei rund 400 Menschen in einem Zeitraum ohnehin normal, und wer hat wann angefangen zu zählen?","rueckmeldung":[{"option":0,"text":"Ein Zählfehler lässt sich so ausschließen, das ist nicht verkehrt. Doch erneutes Zählen bestätigt nur dieselben Daten, aus denen das Muster stammt, und sagt nichts darüber, ob der Zufall allein die neun Fälle erklärt."},{"option":2,"text":"Eine Karte mit Abständen lässt eine Nähe zum Mast auffällig wirken. Sie prüft aber nicht, ob das Muster mehr als Zufall ist, denn Wohnorte liegen immer irgendwo, und die Auswertung erfolgt an denselben Fällen, die das Muster erst ausgelöst haben."},{"option":3,"text":"Die Reihenfolge klingt nach einem Ursache-Wirkung-Test. Weil der Mast aber seit fünfzehn Jahren steht, begannen praktisch alle Beschwerden nach seinem Bau, und diese Abfolge unterscheidet daher nichts."}],"familie":"muster-im-zufall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"CDC/CSTE (2013): Investigating Suspected Cancer Clusters and Responding to Community Concerns. MMWR 62(8)","oeffentlich":true,"url":"https://www.cdc.gov/mmwr/pdf/rr/rr6208.pdf","seite":"S. 3, 22","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"e296ac2f032daae0"}},{"id":"qx-b2-012","clusterId":"B","werkstueckRef":"B.19","stufe":1,"question":"Welche Einordnung ist am besten begründet?","options":["Die Reihe ist wohl Zufall, doch nun ist Zahl bei den nächsten Würfen überfällig, weil sich Kopf und Zahl über die Zeit wieder ausgleichen müssen.","Sieben Mal Kopf in Folge hat bei einer fairen Münze nur etwa 0,8 Prozent Wahrscheinlichkeit, daher ist Zufall bei diesen 100 Würfen wenig plausibel.","Die Reihe spricht eher für einen Einfluss, denn bei einer fairen Münze wechseln sich Kopf und Zahl deutlich regelmäßiger ab als in dieser auffällig langen Folge.","Bei 100 Würfen sind sieben Mal Kopf in Folge nicht selten; eine gezinkte Münze wäre erst eine Vermutung, die an neuen, unabhängigen Würfen zu prüfen ist."],"correctIndex":3,"explanation":"Bei 100 Würfen gibt es viele Stellen, an denen eine solche Reihe beginnen könnte: Mindestens sieben Mal Kopf in Folge kommt bei einer fairen Münze in etwa jeder dritten Hunderterreihe vor, sieben gleiche Ergebnisse in Folge sogar in etwa jeder zweiten. Dein Freund hat erst die Daten angesehen und dann eine Erklärung um den Klumpen gebaut, wie jemand, der erst auf die Scheunenwand schießt und die Zielscheibe danach um die dichteste Stelle malt. Eine gezinkte Münze ist deshalb nur eine Hypothese, die an neuen, unabhängigen Würfen geprüft werden muss, bevor man ihr glaubt. Der Wert von etwa 0,8 Prozent klingt überzeugend, gilt aber nur für sieben Würfe, die man vorher festgelegt hat; hier wurde die Stelle erst im Nachhinein gesucht. Dass Zahl nun „überfällig“ sei, liest ebenfalls Bedeutung in den Zufall hinein, denn die Münze hat kein Gedächtnis.","coreRule":"⚡ Wo Zufall wirkt, entstehen Klumpen, ohne dass jemand sie verursacht hat.","quote":"Der Fehler liegt darin, diesen Zufallsclustern eine Bedeutung beizumessen, nachdem man sie gefunden hat.","quoteLabel":"Merksatz:","beleg":"Werkstück B.19 (Werkbank-Frage; Analyse)","status":"entwurf","scenario":"Ein Freund wirft 100-mal eine Münze und schreibt jedes Ergebnis auf. In der Reihe findet er sieben Mal hintereinander Kopf. Er ist sicher: „Das kann kein Zufall sein. Entweder ist die Münze gezinkt, oder irgendetwas hat das Ergebnis beeinflusst.“","kurz":"Bei 100 Würfen gibt es viele mögliche Startstellen, sodass sieben gleiche Ergebnisse in Folge bei einer fairen Münze recht häufig auftreten. Wer erst die Auffälligkeit sucht und dann erklärt, macht aus Zufall eine Hypothese, die neue Würfe prüfen müssen.","prueffrage":"In wie vielen von zehn Hunderterreihen einer fairen Münze würdest du irgendwo sieben Mal Kopf hintereinander erwarten?","rueckmeldung":[{"option":0,"text":"Dass die Reihe wohl Zufall ist, stimmt. Die Begründung nicht: Die Münze hat kein Gedächtnis, jeder Wurf ist unabhängig, und Zahl muss nichts nachholen. Nur auf lange Sicht nähert sich der Anteil 50 Prozent an."},{"option":1,"text":"Die 0,8 Prozent sind korrekt gerechnet, gelten aber nur für sieben Würfe, die man vorher festgelegt hat. Hier wurde die Stelle erst im Nachhinein gesucht, und bei 100 Würfen gibt es viele mögliche Startpunkte."},{"option":2,"text":"Von Zufall erwartet man oft mehr Abwechslung, als er tatsächlich liefert. Echte Zufallsreihen enthalten häufig längere Serien, und eine auffallend regelmäßige Abfolge wäre eher verdächtig. Lange Folgen sprechen also nicht für einen Einfluss."}],"familie":"muster-im-zufall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185 (inoffizielle Kopie auf einer Kursseite der University of Washington)","oeffentlich":true,"url":"https://sites.stat.washington.edu/peter/498.Sp16/Tversky.pdf","seite":"S. 1125","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185(4157), 1124–1131","oeffentlich":false,"doi":"10.1126/science.185.4157.1124","seite":"S. 1125"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"ecb3a1e82bcc5e80"}},{"id":"qx-b2-013","clusterId":"B","werkstueckRef":"B.20","stufe":1,"question":"Ein Schätzexperiment: Menschen sehen ein Glücksrad, das zufällig bei 10 oder 65 stehen bleibt. Danach sagen sie, ob der Anteil afrikanischer Länder in der UNO über oder unter dieser Zahl liegt, und schätzen ihn. Wer die 10 sah, schätzt im Median 25 %, wer die 65 sah, 45 %. Wie lässt sich das am besten deuten?","options":["Die Zahl auf dem Glücksrad gab besonders denen Orientierung, die kaum etwas über die UNO wussten; wer sich dort auskannte, schätzte vermutlich unbeeinflusst.","Der Abstand zwischen 25 % und 45 % beruht bei einer so wenig bekannten Frage vermutlich auf Zufall, denn solche Schätzungen streuen von Gruppe zu Gruppe stark.","Die Teilnehmer hatten keine eigene Vorstellung vom Anteil und übernahmen deshalb im Wesentlichen die Zahl, die ihnen das Glücksrad gerade angezeigt hatte.","Auch eine zufällige, völlig unpassende Zahl wie die 10 oder die 65 zieht Schätzungen in ihre Richtung, selbst wenn sie mit der UNO-Frage nichts zu tun hat."],"correctIndex":3,"explanation":"Die zufällige, bedeutungslose Zahl des Glücksrads wirkte als mentaler Anker: Die Schätzungen wurden in Richtung dieser ersten Zahl gezogen. Bei Schätzungen wirkt eine solche erste Zahl selbst dann, wenn sie erkennbar willkürlich ist.","coreRule":"⚡ Die erste Zahl zieht dein Urteil zu sich, auch wenn sie nichts mit der Frage zu tun hat.","beleg":"Werkstück B.20; Fn. gl-b-anchoring (Tversky/Kahneman 1974, Science 185, S. 1128; Rad-Detail nach Kahneman 2012, Kap. 11)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Eine zufällige, erkennbar bedeutungslose Zahl zieht Schätzungen in ihre Richtung, das ist der Ankereffekt. Naheliegend ist, die Abweichung durch Vorwissen oder Zufall zu erklären, doch die Richtung folgt genau der gesehenen Zahl.","prueffrage":"Wie wurde entschieden, wer die 10 und wer die 65 zu sehen bekam, und welche Gruppe schätzte höher?","rueckmeldung":[{"option":0,"text":"Dass Unwissende sich stärker an einer Zahl festhalten, klingt einleuchtend. Davon steht im Versuch aber nichts, und dass Kenner unbeeinflusst blieben, ist bloß vermutet: Ein Anker kann Schätzungen auch dann in seine Richtung ziehen, wenn er erkennbar willkürlich ist."},{"option":1,"text":"Schätzungen schwanken zwischen Gruppen tatsächlich, und Zufall lässt sich bei einzelnen Zahlen nie ganz ausschließen. Hier liegt der Unterschied aber genau in der Richtung der gesehenen Zahlen, 10 und 65, und das spricht gegen reinen Zufall."},{"option":2,"text":"Die Zahl hat die Schätzungen beeinflusst, das stimmt. Übernommen wurde sie aber nicht: Die Mediane von 25 % und 45 % liegen weit von 10 und 65 entfernt. Die Schätzung wird in Richtung der Zahl gezogen, ohne dass sie sie ersetzt."}],"familie":"anker-erkennen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185 (inoffizielle Kopie, Kursseite University of Washington)","oeffentlich":true,"url":"https://sites.stat.washington.edu/peter/498.Sp16/Tversky.pdf","seite":"S. 1128","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185(4157), 1124–1131","oeffentlich":false,"doi":"10.1126/science.185.4157.1124","seite":"S. 1128"},{"typ":"literatur","kurz":"Kahneman, D. (2012): Schnelles Denken, langsames Denken. München: Siedler, Kap. 11","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"c3a5d247aac00803"}},{"id":"qx-b2-014","clusterId":"B","werkstueckRef":"B.20","stufe":2,"question":"Wie wirkt der durchgestrichene Preis auf dein Urteil, und welche Frage prüft das Angebot am besten?","scenario":"Im Onlineshop steht neben einer Jacke: „UVP 199 €, jetzt nur 99 €!“ Du hattest vorher keine Vorstellung davon, was eine solche Jacke kosten sollte.","options":["Die 199 € macht die 99 € zu einem Gewinn, denn du sparst 100 € gegenüber dem Normalpreis; frag dich, ob dir diese Ersparnis den Kauf der neuen Jacke wert ist.","Die 199 € zieht dein Urteil zu sich, denn die hohe erste Zahl lässt 99 € billig wirken; frag dich, wie du den Preis ohne die 199 € ganz neu bewerten würdest.","Die 199 € wirkt kaum, denn Streichpreise durchschaut man leicht als Werbemittel; frag dich nur, ob 99 € für eine neue Jacke gut in dein Budget passen.","Die 199 € verrät die Qualität, denn der Hersteller empfiehlt den Preis nach dem Wert der Ware; frag dich, ob die Jacke so hochwertig wirkt wie 199 €."],"correctIndex":1,"explanation":"Die durchgestrichene Zahl ist ein klassischer Anker: Die erste genannte Zahl setzt den Rahmen, in dem du die zweite beurteilst, und 99 € wirken günstig, weil sie neben 199 € stehen, nicht weil du den Wert der Jacke kennst. Gegen die Wirkung hilft die Frage, wie du den Preis bewerten würdest, wenn es die erste Zahl nie gegeben hätte. Preiswissen schützt nicht zuverlässig: In einem Versuch ließen sich auch erfahrene Immobilienmakler bei der Schätzung eines Hauswerts vom vorgegebenen Angebotspreis beeinflussen (Northcraft und Neale 1987). Der Streichpreis ist außerdem kein verlässlicher Beleg für den Wert, sondern ein hoher Anker, der den tatsächlichen Preis als Schnäppchen erscheinen lässt.","coreRule":"⚡ Bewerte jeden Preis so, als hättest du den ersten genannten nie gesehen.","quote":"Wenn diese erste Zahl/diese erste Information nie existiert hätte, wie würde ich diese Situation dann völlig neu und von Grund auf bewerten?","quoteLabel":"Prüffrage:","beleg":"Werkstück B.20 (Anwendung: Preisgestaltung; Anti-Denkmuster)","status":"entwurf","kurz":"Die 99 € wirken günstig, weil die höhere Zahl direkt daneben den Rahmen setzt, nicht weil du den Wert der Jacke kennst. Prüfen lässt sich das, indem du dir den Preis ohne die erste Zahl neu anschaust.","prueffrage":"Was kosten vergleichbare Jacken bei anderen Händlern, und steht dort ebenfalls ein Streichpreis daneben?","rueckmeldung":[{"option":0,"text":"Rechnerisch stimmt es, dass 99 € um 100 € unter 199 € liegen. Ob das ein Gewinn ist, hängt aber davon ab, ob 199 € wirklich der übliche Wert ist, und das weißt du gerade nicht."},{"option":2,"text":"Streichpreise sind oft tatsächlich Werbemittel. Dass man sie deshalb leicht durchschaut, trägt aber nicht: Auch wer die Absicht kennt, wird von der Zahl beeinflusst, selbst erfahrene Fachleute ließen sich von einem vorgegebenen Preis lenken."},{"option":3,"text":"Eine Herstellerempfehlung kann Orientierung geben, ist aber kein verlässlicher Beleg für den Wert einer Ware. Ob die Jacke „wie 199 €“ wirkt, misst du dann wieder an der Zahl, die dein Urteil schon geprägt hat."}],"familie":"anker-erkennen","fertigkeit":"F4","quellen":[{"typ":"literatur","kurz":"Northcraft, G. B.; Neale, M. A. (1987): Experts, amateurs, and real estate: An anchoring-and-adjustment perspective on property pricing decisions. Organizational Behavior and Human Decision Processes 39(1), 84–97","oeffentlich":false},{"typ":"url","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185 (inoffizielle Kopie, Kursseite University of Washington)","oeffentlich":true,"url":"https://sites.stat.washington.edu/peter/498.Sp16/Tversky.pdf","seite":"S. 1128","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"ad2190b280efecc7"}},{"id":"qx-b2-015","clusterId":"B","werkstueckRef":"B.20","stufe":3,"question":"Welche Schlussfolgerung ist am besten begründet?","options":["Der Befund zu Weinpreisen und Versicherungsnummern ist weniger gesichert als gedacht; dass Anker Schätzungen beeinflussen, ist davon unabhängig weiterhin gut belegt.","Spätere Studien zum Weinpreis fanden meist schwächere Effekte; also ist der Ankereffekt insgesamt widerlegt, auch bei Schätzungen und anderen Urteilen.","Der Befund mit der Versicherungsnummer wurde begutachtet veröffentlicht; er wiegt daher schwerer als spätere Wiederholungen und bleibt gültig.","Dass mehrere Wiederholungen zum Wein überhaupt etwas fanden, wenn auch weniger, bestätigt den Befund; die schwächeren Effekte sind nur Messrauschen."],"correctIndex":0,"explanation":"Misslingt die Wiederholung eines Versuchs oder fällt der Effekt viel schwächer aus, ist der ursprüngliche Befund weniger sicher, aber nicht automatisch widerlegt. Und er sagt nur etwas über genau diese Versuchsanordnung: Dass ein zufälliger Zahlenanker die Zahlungsbereitschaft stark lenkt, ist unsicher. Dass Anker Schätzungen verzerren, ist davon getrennt gut belegt, etwa durch das Glücksrad-Experiment von Tversky und Kahneman, in dem eine erkennbar zufällige Zahl die Schätzung des Anteils afrikanischer UN-Mitglieder verschob (Median 25 % gegenüber 45 %). Selbst Maniadis und Kollegen, die deutlich kleinere Effekte fanden als Ariely und seine Kollegen, halten Ankereffekte bei Bewertungen für real und bezweifeln nur deren Größe. Dass die Wiederholungen den Ankereffekt insgesamt widerlegen, klingt konsequent, folgt aber nicht, denn sie betrafen nur diese Versuchsanordnung. Eine Begutachtung klingt nach Qualitätssiegel, schützt aber nicht vor einem Befund, den andere nicht reproduzieren können, deshalb zählen hier die Wiederholungen. Und dass die Wiederholungen etwas fanden, klingt nach Bestätigung, doch Effekte, die deutlich kleiner ausfielen oder ganz fehlten, lassen sich nicht als bloßes Messrauschen abtun.","coreRule":"⚡ Wird ein Befund schlechter bestätigt, ist er weniger sicher, nicht automatisch falsch. Prüfe, was genau wackelt, und wie stark.","beleg":"Werkstück B.20 (Analyse); Fn. gl-b-anker-preis (Ariely/Loewenstein/Prelec 2003, S. 75–77; Maniadis/Tufano/List 2014, AER 104(1), S. 277–290, dort: andere Studien fanden „(if any) much smaller effects“; Ankereffekte bei Bewertungen gelten dennoch als real, offen ist ihre Größe)","status":"entwurf","scenario":"Eine Kollegin sagt: „Ein Experiment hat gezeigt, dass Menschen mehr für einen Wein zahlen, wenn sie vorher die letzten Ziffern ihrer Sozialversicherungsnummer als Dollarbetrag notiert haben. Ein Zufallswert steuert also, was wir bereit sind zu zahlen.“ Später liest du, dass spätere Studien meist deutlich schwächere Effekte fanden, manche gar keine.","kurz":"Dass spätere Studien den Weinpreis-Effekt kaum bestätigen, macht genau diesen Befund unsicherer. Der Fehler wäre, daraus den Ankereffekt insgesamt für widerlegt zu halten: Die Wiederholungen betrafen nur diese Versuchsanordnung.","prueffrage":"Was genau fanden die späteren Studien im Vergleich zum ersten Versuch, und was wurde dort überhaupt gemessen?","rueckmeldung":[{"option":1,"text":"Dass die späteren Studien meist schwächere Effekte fanden, stimmt. Sie prüften aber nur die Weinpreis-Anordnung. Für Ankereffekte bei Schätzungen und anderen Urteilen sagt das wenig, und selbst Kritiker halten sie für real."},{"option":2,"text":"Eine Begutachtung klingt nach Qualitätssiegel, garantiert aber nicht, dass andere den Befund wiederholen können. Deshalb zählen hier die Wiederholungen, und die sprechen eher gegen ein „bleibt gültig“."},{"option":3,"text":"Dass überhaupt etwas gefunden wurde, spricht dafür, dass der Befund nicht ganz leer ist. Deutlich kleinere oder fehlende Effekte sind aber selbst ein Ergebnis und lassen sich nicht einfach als Messrauschen abtun."}],"familie":"gewissheit-kalibrieren","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Maniadis, Z.; Tufano, F.; List, J. A. (2013): One Swallow Doesn't Make a Summer: New Evidence on Anchoring Effects. CeDEx Discussion Paper 2013-07 (später AER 104(1), 277–290)","oeffentlich":true,"url":"https://www.nottingham.ac.uk/cedex/documents/papers/cedex-discussion-paper-2013-07.pdf","abruf":"2026-10-12"},{"typ":"url","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185 (inoffizielle Kopie, Kursseite University of Washington)","oeffentlich":true,"url":"https://sites.stat.washington.edu/peter/498.Sp16/Tversky.pdf","seite":"S. 1128","abruf":"2026-10-12"},{"typ":"doi","kurz":"Ariely, D.; Loewenstein, G.; Prelec, D. (2003): „Coherent Arbitrariness“: Stable Demand Curves Without Stable Preferences. Quarterly Journal of Economics 118(1), 73–106","oeffentlich":false,"doi":"10.1162/00335530360535153"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"55dd66ad3f108af2"}},{"id":"qx-b2-016","clusterId":"B","werkstueckRef":"B.20","stufe":4,"question":"Welche Erklärung passt am besten dazu, dass die Zufallszahl die Schätzungen trotzdem verschiebt?","scenario":"In einem Versuch sollen Menschen schätzen, wie viel Prozent der Mitgliedstaaten der Vereinten Nationen afrikanische Länder sind. Vorher dreht die Versuchsleitung ein Glücksrad (Ergebnis: 65) und fragt: „Liegt der Anteil über oder unter dieser Zahl?“ Danach liegen die Schätzungen deutlich höher als bei einer Vergleichsgruppe, die ohne Rad schätzt. Du weißt: Das Rad war reiner Zufall, und niemand hielt die Zahl für eine Expertenauskunft.","options":["Die Schätzenden wollen nach der Vergleichsfrage stimmig wirken und nennen deshalb einen Wert nicht allzu weit von der besprochenen Zahl.","Die Schätzenden kennen den Anteil nicht und greifen in ihrer Unsicherheit bewusst auf die einzige Zahl zurück, die im Versuch fiel.","Die Frage nach „darüber oder darunter“ ruft bevorzugt Wissen wach, das zur Zahl passt, und färbt so die anschließende Schätzung.","Die Schätzenden nehmen die Zahl als Startpunkt und rücken von dort zu wenig ab, wie man es von selbst gewählten Ausgangswerten kennt."],"correctIndex":2,"explanation":"Die klassische Erklärung „Anpassung und Verankerung“ (Start beim Anker, zu wenig Korrektur) gilt nach späteren Versuchen vor allem für selbst gewählte Ausgangswerte, hier aber war die Zahl vorgegeben. Bei vorgegebenen Ankern wirkt offenbar ein anderer Mechanismus: Schon die Frage, ob die Antwort über oder unter der Zahl liegt, ruft bevorzugt Wissen wach, das zu ihr passt. Wer die Erklärung eines Effekts prüft, sollte fragen, ob sie zu den Rahmenbedingungen passt; ob beide Mechanismen nebeneinander wirken, ist in der Forschung umstritten.","coreRule":"⚡ Anker wirken auf mehr als einem Weg: Prüfe bei einer Erklärung, ob sie zu den Umständen passt (vorgegebener oder selbst gewählter Anker), und ersetze die erste Zahl bewusst durch eine eigene Ausgangsschätzung.","beleg":"Werkstück B.20 (Analyse: Anpassung und Verankerung); Fn. gl-b-anker-mechanismus (Epley/Gilovich 2006, Psychological Science 17(4), S. 312, 317; Gegenposition Simmons/LeBoeuf/Nelson 2010)","status":"entwurf","kernregel":"⚡ Auch eine erkennbar zufällige Zahl kann Schätzungen verschieben, schon die Frage „darüber oder darunter?“ ruft passendes Wissen wach. Schätze deshalb zuerst eigenständig, bevor du eine vorgegebene Zahl beachtest.","kurz":"Eine vorgegebene Zahl wirkt wohl vor allem darüber, dass schon die Frage „darüber oder darunter?“ Wissen weckt, das zu ihr passt, und so die Schätzung färbt. Zu wenig Abrücken vom Startwert beschreibt eher selbst gewählte Ausgangswerte.","prueffrage":"Was unterscheidet diese Zahl von einem Startwert, den die Schätzenden selbst gewählt hätten, und woher kam sie?","rueckmeldung":[{"option":0,"text":"Im Versuch deutet nichts darauf hin, dass jemand stimmig wirken wollte, und die Zahl galt auch nicht als Auskunft. Zudem erklärt dieser Wunsch nicht, warum gerade eine Zufallszahl die Schätzung verschiebt."},{"option":1,"text":"Eine Zahl bewusst als Anhaltspunkt zu nutzen, setzt voraus, dass man sie für aussagekräftig hält. Das Rad war aber erkennbar Zufall und niemand sah in der Zahl eine Expertenauskunft, so dass die Wirkung eher unbemerkt zustande kommen dürfte."},{"option":3,"text":"Der Gedanke vom Startpunkt mit zu wenig Korrektur beschreibt einen bekannten Mechanismus, der aber vor allem für selbst gewählte Ausgangswerte gilt. Hier war die Zahl vorgegeben, daher passt die Erklärung schlecht zu den Rahmenbedingungen."}],"familie":"anker-erkennen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Association for Psychological Science: Abstract zu Epley, N.; Gilovich, T. (2006): The Anchoring-and-Adjustment Heuristic: Why the Adjustments Are Insufficient","oeffentlich":true,"url":"https://www.psychologicalscience.org/journals/psychological-science/j.1467-9280.2006.01704.x/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Epley, N.; Gilovich, T. (2006): The Anchoring-and-Adjustment Heuristic: Why the Adjustments Are Insufficient. Psychological Science 17(4), 311–318","oeffentlich":false,"doi":"10.1111/j.1467-9280.2006.01704.x","seite":"S. 312, 317"},{"typ":"literatur","kurz":"Simmons, J. P.; LeBoeuf, R. A.; Nelson, L. D. (2010): The effect of accuracy motivation on anchoring and adjustment: Do people adjust from provided anchors? Journal of Personality and Social Psychology 99(6)","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"9dbfc72d8eff5e48"}},{"id":"qx-b2-017","clusterId":"B","werkstueckRef":"B.21","stufe":1,"question":"Welche Erwiderung auf den Einwand des Ingenieurs prüft die Behauptung am besten, ohne die Ebenen von Werten und Fakten zu vermischen?","options":["Das Ziel steht fest. Offen ist nur der Weg, und ob er trägt, lässt sich mit den Berechnungen des Ingenieurs prüfen.","Der Ingenieur teilt das Ziel und hat nachgerechnet. Damit ist die Sachfrage geklärt, und der Plan der Aktivistin ist widerlegt.","Ob Kernenergie vertretbar ist, ist eine Wertfrage. Darauf geben Berechnungen keine Antwort, also führt der Einwand nicht weiter.","Beide Seiten haben gute Gründe. Am sinnvollsten ist ein Mittelweg aus überwiegend erneuerbaren Quellen und etwas Kernenergie."],"correctIndex":0,"explanation":"Die Aktivistin schließt von der guten Absicht auf die Richtigkeit ihrer Tatsachenannahmen und wehrt die Gegenzahlen mit einem Angriff auf Motive ab. Das vermischt zwei Ebenen: was erstrebenswert ist (Werte) und was tatsächlich funktioniert (Fakten). Das Ziel kann geklärt sein, während der Weg offen bleibt und sich anhand von Fakten und Daten klären lässt. Ob der Ingenieur recht hat, ist damit noch nicht entschieden. Das zeigt sich erst, wenn man seine Berechnungen prüft, nicht durch den Verweis auf moralische Überlegenheit. Gute Absichten sind kein Schutz vor schlechten Ergebnissen.","coreRule":"⚡ Eine gute Absicht macht die Tatsachenbehauptung nicht wahr.","beleg":"Werkstück B.21 (Kernidee; Anti-Denkmuster; Beispiel Aktivistin und Ingenieur)","status":"entwurf","scenario":"In einer Debatte über Energiepolitik sagt eine Aktivistin: „Wir kämpfen für die Rettung des Planeten, also stimmt auch unser Plan: Jede Kernenergie ist abzulehnen, und eine Versorgung allein aus Erneuerbaren ist machbar. Wer das bezweifelt, dem ist der Planet egal.“ Ein Ingenieur entgegnet: „Ich teile dein Ziel, aber meine Berechnungen zeigen, dass wir ohne Kernenergie keine stabile Versorgung gewährleisten können.“ Die Aktivistin antwortet: „Deine Zahlen sind nur Ablenkung. Wir haben die moralische Überlegenheit, und die zählt am Ende.“","kurz":"Das Ziel kann geklärt sein, während der Weg offen bleibt. Ob der Plan trägt, zeigt sich nur an Fakten und Berechnungen. Der Fehler wäre, von guter Absicht auf richtige Annahmen zu schließen und Gegenzahlen mit Moral abzuwehren.","prueffrage":"Was genau wirft die Aktivistin dem Ingenieur vor, und was sagt sie zu seinen Berechnungen selbst?","rueckmeldung":[{"option":1,"text":"Dass der Ingenieur das Ziel teilt und gerechnet hat, spricht für ihn. Ob seine Rechnung stimmt, ist damit aber nicht gezeigt, und solange sie ungeprüft ist, steht der Plan nicht widerlegt da."},{"option":2,"text":"Bei der Frage, wie viel Risiko man in Kauf nimmt, spielen Werte mit. Der Einwand betrifft aber, ob eine stabile Versorgung ohne Kernenergie gelingt, und das ist eine Sachfrage, die sich mit Daten prüfen lässt."},{"option":3,"text":"Ein Mix aus beidem kann am Ende durchaus herauskommen. Als Kompromiss vorab beantwortet er aber nicht, ob die Behauptung stimmt: Das zeigt sich erst, wenn man die Berechnungen prüft."}],"familie":"absicht-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Ad Hominem“, „Faulty Motives“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Liu, B. S.; Ditto, P. H. (2013): What Dilemma? Moral Evaluation Shapes Factual Belief. Social Psychological and Personality Science 4(3), 316–323","oeffentlich":false,"doi":"10.1177/1948550612456045"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"400c202f2311287e"}},{"id":"qx-b2-018","clusterId":"B","werkstueckRef":"B.21","stufe":2,"question":"Was lässt sich aus dieser Antwort über die Richtigkeit der Berechnungen schließen?","scenario":"In einer Debatte zur Energieversorgung legt ein Ingenieur Berechnungen vor, wonach sich eine stabile Stromversorgung mit der heutigen Technik und Speicherlösung nicht allein mit erneuerbaren Quellen sichern lässt. Die Gegenseite antwortet: „Sie arbeiten für eine moralisch korrupte Industrie. Unsere Sache ist gerecht, und das zählt am Ende.“","options":["Sie spricht eher für die Berechnungen, denn wer nur den Absender angreift, hat gegen die Zahlen selbst offenbar nichts Stichhaltiges in der Hand.","Sie spricht dafür, dass die Berechnungen umstritten sind, denn eine der beiden Seiten in der Debatte erkennt sie nicht als maßgeblich für die Entscheidung an.","Sie spricht eher gegen die Berechnungen, denn wenn er für diese Industrie arbeitet, hat er ein Interesse am Ergebnis und rechnet leicht in dessen Richtung.","Sie spricht weder für noch gegen die Berechnungen, denn ob sie stimmen, lässt sich nur an den Zahlen selbst klären, nicht an Herkunft oder Moral."],"correctIndex":3,"explanation":"Die Antwort greift das Motiv des Gegners an („moralisch korrupte Industrie“) und beruft sich auf die eigene gerechte Sache. Beides sind Aussagen über Absichten und Werte, keine über die Berechnungen. Ob eine Rechnung stimmt, hängt nicht davon ab, wer sie vorlegt oder wie gut die Ziele des Gegenübers sind. Auch wer ein moralisch hehres Ziel verfolgt, kann sich über die Fakten irren, und auch ein Gegner mit zweifelhaften Motiven kann richtig rechnen. Der Einwand wäre nur dann ein Argument, wenn er die Zahlen selbst prüft, etwa Annahmen, Rechenweg oder Datenquellen. Solange das nicht geschieht, bleibt die Sachfrage offen und muss mit den Zahlen geklärt werden. Dass die Gegenseite keine Gegenzahlen nennt, wirkt wie ein Zugeständnis, macht die Berechnungen aber nicht richtig, sondern lässt die Frage offen. Und dass jemand befangen sein kann, ist ein Grund zum genauen Hinsehen, aber kein Beleg dafür, dass die Zahlen falsch sind.","coreRule":"⚡ Wer die Motive des Gegners angreift oder die eigene Moral betont, hat seine Zahlen noch nicht widerlegt.","beleg":"Werkstück B.21 (Eingangsszene; Analyse: Selbst-Immunisierung, Ad hominem)","status":"freigegeben","freigabe":{"datum":"2026-10-15","pruefsumme":"f4d3b3cba267592b","vermerk":"Prüfpult (Sturm, erste Charge nach den neuen falschen Optionen)"},"kurz":"Die Antwort sagt etwas über Motive und Werte des Ingenieurs, nicht über seine Zahlen. Ob die Rechnung stimmt, zeigt nur ein Blick auf Annahmen, Rechenweg und Daten. Der Denkfehler: vom Absender auf den Inhalt zu schließen.","prueffrage":"Würde sich an den Berechnungen etwas ändern, wenn derselbe Ingenieur für einen Umweltverband arbeitete?","rueckmeldung":[{"option":0,"text":"Dass keine Gegenzahlen genannt werden, wirkt wie ein Zugeständnis. Es macht die Berechnungen aber nicht richtig, sondern lässt die Frage offen: Gestimmt haben sie erst, wenn sie geprüft wurden."},{"option":1,"text":"Eine Seite weist die Berechnungen zurück, ohne sie zu prüfen. Das zeigt Widerspruch, aber keine fachliche Unsicherheit: Ob Zahlen belastbar sind, hängt an Annahmen, Rechenweg und Daten, nicht daran, wer sie anerkennt."},{"option":2,"text":"Ein Eigeninteresse ist ein guter Grund, Zahlen genauer anzusehen. Es sagt aber nicht, dass sie falsch sind, denn auch wer befangen sein mag, kann richtig rechnen. Das zeigt sich nur an den Zahlen selbst."}],"familie":"absicht-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Ad Hominem“, „Faulty Motives“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"f4d3b3cba267592b"}},{"id":"qx-b2-019","clusterId":"B","werkstueckRef":"B.21","stufe":3,"question":"In einer Debatte über Energiepolitik sagt eine Aktivistin: „Wir kämpfen für die Rettung des Planeten. Die Zahlen des Ingenieurs sind nur Ablenkung, er arbeitet für eine moralisch korrupte Industrie. Wir sind moralisch im Recht, und das zählt.“ Was ist an diesem Vorgehen der Kern des Fehlers?","options":["Sie schließt von der guten Absicht ihres Ziels auf die Richtigkeit ihrer Annahmen über den Weg dorthin und prüft die Zahlen deshalb nicht.","Sie wirft der Industrie des Ingenieurs Korruption vor, ohne dafür Belege zu nennen, und lässt so ihren Vorwurf gegen ihn unbegründet.","Sie setzt mit Worten wie „Rettung des Planeten“ auf Gefühle und Dringlichkeit, wo eine nüchterne Abwägung der Vor- und Nachteile gefragt wäre.","Sie macht ihr Ziel unverhandelbar und lässt daneben keine Abwägung mit anderen berechtigten Zielen der Energiepolitik mehr zu."],"correctIndex":0,"explanation":"Ob ein Ziel gut ist (Werte) und ob ein bestimmter Weg es erreicht (Fakten), sind zwei verschiedene Fragen. Die Aktivistin schließt von der guten Absicht auf die Richtigkeit ihrer Annahmen und wehrt Gegenargumente ab, indem sie die Motive des Ingenieurs angreift, statt seine Zahlen zu prüfen. Ob er recht hat, ist damit nicht entschieden, das ließe sich nur mit den Daten klären. Eine moralische Überzeugung ist dabei nicht das Problem, sie treibt oft Reformen an. Zum Fehler wird sie, wenn sie zur Lizenz wird, die Realität nicht mehr zu prüfen, und Fakten dann als moralisch minderwertig gelten.","coreRule":"⚡ Moral gibt das Ziel vor, aber den Weg dorthin entscheiden die Fakten.","beleg":"Werkstück B.21 (Adaptives Talent; Kipppunkt)","status":"entwurf","scenario":"","kurz":"Ob ein Ziel gut ist, ist eine Wertfrage, ob ein Weg es erreicht, eine Tatsachenfrage. Die Aktivistin schließt von der guten Absicht auf richtige Annahmen und greift Motive an, statt Zahlen zu prüfen. Ob der Ingenieur recht hat, klären nur die Daten.","prueffrage":"Womit begegnet die Aktivistin den Zahlen des Ingenieurs, und was davon betrifft die Zahlen selbst?","rueckmeldung":[{"option":1,"text":"Ein Vorwurf ohne Beleg ist tatsächlich schwach. Auch ein belegter Vorwurf würde die Zahlen aber nicht widerlegen. Das eigentliche Problem liegt darin, dass die Motive des Ingenieurs angegriffen werden, statt zu prüfen, ob seine Zahlen stimmen."},{"option":2,"text":"Aufgeladene Sprache ist ein Merkmal der Rede, aber nicht der Kern des Fehlers. Eine starke moralische Überzeugung kann berechtigt sein und Reformen antreiben. Problematisch wird sie erst, wenn sie als Grund dient, Fakten nicht mehr zu prüfen."},{"option":3,"text":"Ziele gegeneinander abzuwägen ist in der Energiepolitik wichtig, davon ist im Beispiel aber nicht die Rede. Hier geht es um etwas anderes: Ob ein Weg das Ziel erreicht, ist eine Tatsachenfrage, die sich nicht durch moralische Überlegenheit entscheiden lässt."}],"familie":"absicht-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Liu, B. S.; Ditto, P. H. (2013): What Dilemma? Moral Evaluation Shapes Factual Belief. Social Psychological and Personality Science 4(3), 316–323","oeffentlich":false,"doi":"10.1177/1948550612456045"},{"typ":"url","kurz":"Dowden, B.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „Faulty Motives“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v7","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"0cab85245e1a50a5"}},{"id":"qx-b2-020","clusterId":"B","werkstueckRef":"B.21","stufe":4,"question":"Was ist ein produktiver erster Zug in dieser Debatte?","scenario":"In deinem Verein streiten zwei Lager über die Methoden eines Tierschutz-Protests. Lager A sagt: „Wir blockieren Schlachthof-Zufahrten, denn das ist der einzige Weg, der der Sache gerecht wird.“ Lager B meint: „Die Blockaden schaden uns eher, weil sie Spenden und Unterstützung kosten.“ Beide wollen weniger Tierleid und halten sich für moralisch im Recht.","options":["Beide Lager ihre Beweggründe darlegen lassen und dem folgen, das glaubwürdiger für die Tiere eintritt, weil gute Absichten für gute Methoden sprechen.","Die Mitglieder abstimmen lassen, welche Methode der Verein künftig nutzt, weil eine Mehrheitsentscheidung fair ist und beide Lager daran bindet.","Das gemeinsame Ziel, weniger Tierleid, als geklärt festhalten und getrennt davon anhand von Daten prüfen, welcher Weg es am ehesten erreicht.","Sich auf einen Mittelweg einigen, etwa Blockaden nur an einzelnen Tagen, weil dann beide Lager Zugeständnisse machen und der Streit im Verein endet."],"correctIndex":2,"explanation":"Hier streiten zwei Lager nicht über Werte, sondern über eine Tatsachenfrage: Welcher Weg führt tatsächlich zum gemeinsamen Ziel? Gute Absichten sagen nichts darüber, ob eine Methode wirkt. Man kann das Richtige wollen und sich trotzdem über den Weg irren. Sinnvoll ist deshalb, das Ziel als geklärt zu betrachten und die Wege an Fakten und Daten zu messen: Wie haben ähnliche Aktionen auf Spenden, Mitglieder und öffentliche Meinung gewirkt? Erst dann lässt sich begründet entscheiden. Der Vergleich der Beweggründe wirkt fair, ersetzt aber die Faktenprüfung durch Selbstvergewisserung, denn lautere Absichten sagen nicht, welche Methode wirkt. Ein Mittelweg klingt nach einem Kompromiss, ist aber keine Prüfung, weil er nur fragt, wie sich beide Lager treffen, und nicht, was das Ziel erreicht.","coreRule":"⚡ Erst das Ziel klären, dann die Wege an den Fakten messen.","beleg":"Werkstück B.21 (Anti-Denkmuster; Verbindungen: Stahlmann-Argument)","status":"entwurf","kurz":"Beide Lager wollen dasselbe, streiten also über eine Tatsachenfrage: Welcher Weg wirkt? Gute Absichten beantworten das nicht. Man kann das Richtige wollen und sich über den Weg irren. Deshalb gehört die Methode auf den Prüfstand der Daten.","prueffrage":"Wenn sich herausstellte, dass Blockaden tatsächlich Spenden kosten, würde das etwas an den Absichten von Lager A ändern?","rueckmeldung":[{"option":0,"text":"Lautere Absichten sind hier ohnehin gegeben, denn beide wollen weniger Tierleid. Sie sagen aber nicht, welche Methode wirkt: Man kann das Richtige wollen und sich über den Weg trotzdem irren."},{"option":1,"text":"Eine Abstimmung ist fair und schafft Verbindlichkeit. Sie zeigt aber nur, was mehrheitlich gewollt wird, nicht, was wirkt. Sinnvoll wäre sie erst, nachdem die Wirkung der Methoden geprüft wurde."},{"option":3,"text":"Ein Mittelweg wirkt versöhnlich, weil beide etwas abgeben. Er beantwortet aber nur, wie sich die Lager treffen, nicht, was dem Ziel dient. Ob Blockaden an einzelnen Tagen helfen oder schaden, bleibt ungeprüft."}],"familie":"absicht-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Liu, B. S.; Ditto, P. H. (2013): What Dilemma? Moral Evaluation Shapes Factual Belief. Social Psychological and Personality Science 4(3), 316–323","oeffentlich":false,"doi":"10.1177/1948550612456045"},{"typ":"url","kurz":"Dowden, B.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „Faulty Motives“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"5e83926474789181"}},{"id":"qx-b2-021","clusterId":"B","werkstueckRef":"B.22","stufe":1,"question":"Was erklärt am besten, warum so viele Menschen nicht erkennen können, ob das Posting ernst gemeint ist?","options":["Ohne erkennbaren Hinweis auf die Absicht lässt sich eine Parodie auf Extremes nicht von echtem Extremismus unterscheiden, der oft ebenso absurd klingt.","Die Leser bewegen sich in Echokammern und kennen den Tonfall anderer Gruppen nicht mehr, weshalb sie Beiträge aus fremden Lagern regelmäßig falsch einordnen.","Die Leser prüfen die Behauptung nicht an Quellen; wer sie nachschlägt, erkennt am Ergebnis, ob der Verfasser sie ernst meint, und kann sie einordnen.","Der Wahrheitseffekt wirkt: Was man mehrfach liest, hält man eher für wahr, und so wird aus einem Scherz in der Debatte schrittweise Ernst, ohne dass die Leser es bemerken."],"correctIndex":0,"explanation":"Ohne Tonfall, Mimik und Körpersprache fehlen im Netz die Signale, an denen man im Gespräch Satire von Ernst unterscheidet. Hinzu kommt: Die Wirklichkeit des Extremismus ist oft so bizarr, dass eine Parodie davon kaum noch abweicht. Deshalb kann dieselbe Aussage für den einen ein Witz und für den anderen aufrichtig sein, und echter Extremismus wird umgekehrt manchmal für Satire gehalten. Ein Beispiel: Die Bewegung „Birds Aren’t Real“ war von Anfang an Satire, wurde aber von Fremden häufig für echte Verschwörungsgläubigkeit gehalten. Die Unsicherheit liegt also im fehlenden Kontext, nicht in einer erkennbaren Gesinnung des Verfassers. Sinnvoll ist deshalb, Kontext und Absicht zu prüfen, statt vorschnell nach dem eigenen Eindruck zu urteilen.","coreRule":"⚡ Ohne klaren Hinweis auf die Absicht lässt sich Satire über Extremes nicht verlässlich von echtem Extremismus unterscheiden: Prüfe Kontext und Absicht, statt nur nach deinem Eindruck zu urteilen.","beleg":"Werkstück B.22 (Kernidee; Analyse); Fn. gl-b-poe (Nathan Poe 2005; Aikin 2013)","status":"entwurf","scenario":"Auf einer Social-Media-Plattform erscheint der Beitrag: „Alle Tauben sind Überwachungsdrohnen der Regierung. Wer das noch bezweifelt, ist naiv.“ Kein Emoji, kein Hinweis auf Ironie, keine Angabe zum Autor. Unter dem Beitrag streiten sich die Leute: Ein Teil stimmt empört zu, ein anderer Teil lacht über den vermeintlichen Witz. Eine Person fragt: „Ist das ernst gemeint oder Satire?“ Niemand kann es sicher sagen.","kurz":"Im Netz fehlen Tonfall und Mimik, an denen man sonst Satire von Ernst unterscheidet, und echter Extremismus klingt oft selbst so absurd wie eine Parodie. Wer den Beitrag aus dem eigenen Eindruck heraus einordnet, rät nur.","prueffrage":"Was an diesem Beitrag, außerhalb seines Wortlauts, würde etwas über die Absicht des Verfassers verraten?","rueckmeldung":[{"option":1,"text":"Echokammern gibt es, und sie verzerren manches Urteil über fremde Lager. Hier streiten aber beide Lager im selben Thread, und schon der fehlende Kontext erklärt die Unsicherheit. Dass Leser Fremdes „regelmäßig“ falsch einordnen, ist eine Zusatzannahme."},{"option":2,"text":"Nachschlagen klingt gründlich, bringt hier aber nichts: Dass Tauben keine Drohnen sind, gilt für Ernst und Scherz gleichermaßen. Das Ergebnis der Prüfung verrät also nichts über die Absicht des Verfassers."},{"option":3,"text":"Der Wahrheitseffekt ist ein bekannter Mechanismus, wirkt aber erst, wenn man dieselbe Aussage mehrfach liest. Im Szenario gibt es nur diesen einen Beitrag, und der Effekt erklärt ohnehin nur, was man für wahr hält, nicht ob etwas Satire ist."}],"familie":"satire-oder-ernst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Wikipedia: Poe's law","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Poe%27s_law","abruf":"2026-10-12"},{"typ":"url","kurz":"TED (2023): How to Be a Better Human – Do we have something to learn from conspiracy theories? (w/ Peter McIndoe), Transkript","oeffentlich":true,"url":"https://www.ted.com/podcasts/how-to-be-a-better-human/do-we-have-something-to-learn-from-conspiracy-theories-w-peter-mcindoe-transcript","abruf":"2026-10-12"},{"typ":"doi","kurz":"Aikin, S. F. (2013): Poe's Law, group polarization, and argumentative failure in religious and political discourse. Social Semiotics 23(3), 301–317","oeffentlich":false,"doi":"10.1080/10350330.2012.719728"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"45f8e39e276afad2"}},{"id":"qx-b2-022","clusterId":"B","werkstueckRef":"B.22","stufe":2,"question":"Was ist an dieser Schlussfolgerung fehlerhaft?","options":["Aus der Größe der Menge folgt nicht, dass die Menschen glauben, was auf den Schildern steht; sie könnten mitspielen, der Auftritt allein beweist es nicht.","Aus der Größe der Menge folgt nicht, dass die Behauptung auf den Schildern stimmt; was viele vertreten, ist nicht deshalb wahr (Argumentum ad populum).","Die Zeitung gibt die Behauptung der Bewegung verzerrt wieder und widerlegt eine überzogene Fassung, statt die tatsächliche Aussage zu prüfen (Strohmann).","Die Zeitung schließt von den Teilnehmern einer Kundgebung auf die ganze Bevölkerung, obwohl Kundgebungsbesucher eine besondere Auswahl sind (Selektionsverzerrung)."],"correctIndex":0,"explanation":"Von außen sehen Ernst und Spiel gleich aus: Wer ein Schild hochhält, kann glauben, was darauf steht, oder die Rolle des Gläubigen bewusst spielen. Genau so war es bei der Bewegung „Birds Aren’t Real“: Ihr Gründer Peter McIndoe gab 2021 öffentlich zu, dass sie von Anfang an Satire war, und viele der jungen Leute auf den Kundgebungen kannten den Witz und spielten die Gläubigen nur. Wer allein aus Auftritt und Menge auf aufrichtigen Glauben schließt, behandelt eine Möglichkeit als Tatsache. Solange keine Hinweise auf die Absicht vorliegen, ist die ehrliche Antwort Unsicherheit und der nächste Schritt eine Prüfung des Kontexts.","coreRule":"⚡ Wo Satire und Ernst gleich klingen, entscheidet nur der Kontext der Absicht.","beleg":"Werkstück B.22 (Eingangsszene); Fn. gl-b-birds (Lorenz 2021, New York Times, 9.12.2021; McIndoe im TED-Podcast 24.07.2023; NPR 08.12.2023)","status":"entwurf","scenario":"Eine Bewegung behauptet auf Schildern, alle Vögel seien von der Regierung durch Überwachungsdrohnen ersetzt worden. Zu ihren Kundgebungen kommen Hunderte junge Leute. Eine Zeitung schreibt: „Hunderte Menschen glauben ernsthaft, dass es keine echten Vögel gibt. So weit ist der Verschwörungswahn gekommen.“","quote":"","quoteLabel":"","kurz":"Wer ein Schild hochhält, kann glauben, was darauf steht, oder den Gläubigen nur spielen; von außen sieht beides gleich aus. Die Zeitung behandelt eine Möglichkeit als Tatsache, statt zuerst den Kontext zu prüfen.","prueffrage":"Was genau hat die Zeitung gesehen, und was davon verrät, was in den Köpfen der Teilnehmenden vorgeht?","rueckmeldung":[{"option":1,"text":"Dass Verbreitung allein nichts beweist, stimmt. Die Zeitung hält die Behauptung aber gar nicht für wahr, sondern für Wahn. Ein Schluss von der Menge auf die Wahrheit liegt hier also nicht vor."},{"option":2,"text":"Ein Strohmann setzt eine verzerrte Wiedergabe voraus. Die Zeitung gibt die Behauptung der Schilder aber unverändert wieder. Der Fehler liegt woanders: im Schluss auf aufrichtigen Glauben."},{"option":3,"text":"Kundgebungsbesucher sind tatsächlich keine Zufallsauswahl. Die Zeitung spricht aber nur über die Teilnehmer und verallgemeinert nicht auf die Bevölkerung. Der Fehler liegt daher nicht in einer Verallgemeinerung."}],"familie":"satire-oder-ernst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Wikipedia: Birds Aren't Real","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Birds_Aren%27t_Real","abruf":"2026-10-12"},{"typ":"url","kurz":"TED (2023): How to Be a Better Human – Peter McIndoe, Transkript","oeffentlich":true,"url":"https://www.ted.com/podcasts/how-to-be-a-better-human/do-we-have-something-to-learn-from-conspiracy-theories-w-peter-mcindoe-transcript","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Lorenz, T. (2021): Birds Aren't Real, or Are They? Inside a Gen Z Conspiracy Theory. The New York Times, 9.12.2021","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"c4c10a47d7600b67"}},{"id":"qx-b2-023","clusterId":"B","werkstueckRef":"B.22","stufe":3,"question":"Ein Mitglied der Gruppe sagt: „Das war doch nur ein Witz, versteht ihr keinen Spaß?“ Was ist an dieser Verteidigung als Beweis dafür, dass die Memes harmlos sind, fehlerhaft?","scenario":"In einer Online-Gruppe kursieren hasserfüllte Memes. Wird die Gruppe dafür kritisiert, heißt es regelmäßig: „Das war doch nur ein Witz, versteht ihr keinen Spaß?“ Weitere Hinweise auf Ironie, etwa Übertreibung gegen die eigene Position oder eine erkennbare Pointe, gibt es nicht.","options":["Die Verteidigung beruht auf einer unprüfbaren Selbstauskunft, die an der Wirkung nichts ändert: Die Botschaft verbreitet sich, die Verantwortung wird abgelehnt.","Die Verteidigung greift die Kritiker an: Sie wirft ihnen fehlenden Humor vor und macht so deren Empfindlichkeit zum Thema statt den Inhalt der Memes.","Die Verteidigung übersieht, dass Humor Geschmackssache ist: Was die einen witzig finden, verletzt andere, und darum lässt sich die Frage kaum entscheiden.","Die Verteidigung lässt die Betroffenen außen vor: Ob ein Meme harmlos ist, hängt davon ab, ob sich die Gemeinten verletzt fühlen, nicht vom Urteil der Gruppe."],"correctIndex":0,"explanation":"Ob etwas Satire ist, entscheidet nicht die nachträgliche Behauptung des Absenders, sondern der Kontext und die erkennbare Absicht des Autors. Online fehlen Tonfall, Mimik und Körpersprache, deshalb sind Ironie und Ernst oft nicht zu trennen (Poe’s Law). Genau das lässt sich ausnutzen: Wer hasserfüllte Memes verbreitet und sich bei Kritik auf „nur ein Witz“ zurückzieht, normalisiert seine Ideologie und lehnt zugleich jede Verantwortung dafür ab. Satire ist ein gesundes Ventil und ein hochentwickeltes soziales Werkzeug, aber der Hinweis „nur ein Witz“ ersetzt weder Kontext noch erkennbare Absicht. Nützliche Prüffragen sind: Gibt es erkennbare Ironiesignale, etwa Emojis oder ein „/s“? Gibt es eine etablierte Gruppe von Menschen, die genau das aufrichtig glaubt? Und was verrät der Kontext über die Absicht des Autors?","coreRule":"⚡ „War nur Spaß“ ist kein Beweis für Satire, sondern oft der Rückzugsraum für Ernst.","beleg":"Werkstück B.22 (Anwendung: politischer Extremismus & Trolle; Kipppunkt)","status":"entwurf","kurz":"„Nur ein Witz“ ist eine Behauptung des Absenders, die sich nicht überprüfen lässt. Ob etwas Satire ist, zeigen Kontext und erkennbare Absicht. Ohne beides verbreitet sich die Botschaft weiter, während jede Verantwortung abgelehnt wird.","prueffrage":"Welche erkennbaren Signale im Meme selbst zeigen, dass der Autor die Aussage nicht ernst meint?","rueckmeldung":[{"option":1,"text":"Dass die Kritiker mit dem Humorvorwurf abgekanzelt werden, ist tatsächlich ein Ablenkungsmanöver. Als Beweis für Harmlosigkeit scheitert die Verteidigung aber schon früher: Eine bloße Selbstauskunft ersetzt weder Kontext noch erkennbare Absicht."},{"option":2,"text":"Humor ist zum Teil Geschmackssache, das stimmt. Ob etwas Satire ist, lässt sich aber nicht nur nach Geschmack beurteilen: Ironiesignale, Kontext und die erkennbare Absicht liefern durchaus Anhaltspunkte, an denen sich die Frage prüfen lässt."},{"option":3,"text":"Die Perspektive der Gemeinten ist wichtig und wird bei „nur ein Witz“ gern übergangen. Als alleiniger Maßstab trägt sie aber nicht: Ob etwas Satire ist, zeigt sich an Kontext und erkennbarer Absicht, nicht allein daran, wer sich verletzt fühlt."}],"familie":"satire-oder-ernst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Wikipedia: Poe's law","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Poe%27s_law","abruf":"2026-10-12"},{"typ":"doi","kurz":"Aikin, S. F. (2013): Poe's Law, group polarization, and argumentative failure in religious and political discourse. Social Semiotics 23(3), 301–317","oeffentlich":false,"doi":"10.1080/10350330.2012.719728"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v7","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"509c8c000b0f6a25"}},{"id":"qx-b2-024","clusterId":"B","werkstueckRef":"B.22","stufe":4,"question":"Welches Vorgehen ist hier am sinnvollsten?","scenario":"Eine Kollegin teilt eine unglaubliche Schlagzeile: „Bericht: Bundesregierung will Schulpflicht durch freiwilliges Lernen per App ersetzen“. Du hältst es für einen Scherz, bist dir aber nicht sicher. Auf Nachfrage sagt sie nur: „Klingt doch total plausibel, oder?“","options":["Du wendest das Sparsamkeitsprinzip an: Ein Scherz erklärt die Schlagzeile über die Schulpflicht einfacher als ein echter Regierungsplan, und du stufst sie so ein.","Du prüfst Quelle, Kontext und mögliche Absicht der Schlagzeile und fragst dich, ob jemand das wirklich ernsthaft vertritt, bevor du dich festlegst.","Du bewertest, ob sich freiwilliges Lernen per App als Ersatz der Schulpflicht fachlich begründen lässt, und hältst die Schlagzeile für echt, wenn die Idee überzeugt.","Du leitest die Schlagzeile mit dem Vermerk „Quelle unklar“ an weitere Kollegen weiter, damit sie gemeinsam einordnen, ob die Regierung das wirklich plant."],"correctIndex":1,"explanation":"Ob ein Text ernst oder ironisch gemeint ist, lässt sich aus dem Inhalt allein oft nicht ablesen. Die Wirklichkeit des Extremismus und des Verschwörungsglaubens ist mitunter bizarrer als jede Parodie, und Satire-Seiten werden regelmäßig für echte Nachrichten gehalten. „Zu abwegig, um ernst zu sein“ ist deshalb kein sicherer Schluss. Verlässlich ist der Blick auf Quelle, Kontext und Absicht und die Frage, ob eine reale Gruppe genau das aufrichtig glaubt. Das Sparsamkeitsprinzip klingt vernünftig, setzt aber voraus, dass man Erklärungen an Belegen vergleichen kann, und die fehlen hier noch. Eine fachliche Begründung der Idee wirkt sorgfältig, sagt aber nichts darüber, ob jemand sie wirklich vertritt oder ob die Meldung echt ist; das ist eine Frage nach der Herkunft. Das Weiterleiten mit Vermerk wirkt vorsichtig, verbreitet die Schlagzeile aber, bevor die Frage geklärt ist.","coreRule":"⚡ Absurdität allein entscheidet nicht über Satire; Kontext und Quelle tun es.","quote":"Unabhängig davon, ob ich das persönlich für einen Witz halte: Gibt es eine etablierte Gruppe von Menschen, die genau das aufrichtig glaubt? Bevor ich reagiere, sollte ich den Kontext und die Absicht des Autors prüfen.","quoteLabel":"Beispielgedanke:","beleg":"Werkstück B.22 (Anti-Denkmuster; Red Flags; Anwendung: Fake News & Satire)","status":"entwurf","kurz":"Ob eine Meldung ernst oder ironisch gemeint ist, verrät ihr Inhalt oft nicht, denn die Wirklichkeit ist mitunter bizarrer als jede Parodie. „Zu abwegig für echt“ ist daher kein sicherer Schluss; erst Quelle, Kontext und Absicht schaffen Klarheit.","prueffrage":"Woran hast du bisher festgemacht, dass es ein Scherz sein könnte, und wie sicher ist dieses Zeichen?","rueckmeldung":[{"option":0,"text":"Die einfachere Erklärung wirkt vernünftig, doch ein Vergleich von Erklärungen braucht Belege, und die fehlen noch. Außerdem ist „zu abwegig, um ernst zu sein“ kein sicherer Schluss: Manches Echte ist absurder als jede Parodie."},{"option":2,"text":"Ob die Idee fachlich überzeugt, ist eine sorgfältige Überlegung, beantwortet aber eine andere Frage. Sie sagt nichts darüber, ob die Meldung echt ist oder ob jemand das wirklich plant; das klärt nur der Blick auf die Herkunft."},{"option":3,"text":"Der Vermerk „Quelle unklar“ ist vorsichtig gemeint, trotzdem geht die Schlagzeile weiter, bevor geklärt ist, ob sie stimmt. Zuerst prüfen, dann teilen: Dann kann gemeinsames Einordnen auf einer tragfähigen Grundlage stattfinden."}],"familie":"satire-oder-ernst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Wikipedia: Poe's law","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Poe%27s_law","abruf":"2026-10-12"},{"typ":"doi","kurz":"Aikin, S. F. (2013): Poe's Law, group polarization, and argumentative failure in religious and political discourse. Social Semiotics 23(3), 301–317","oeffentlich":false,"doi":"10.1080/10350330.2012.719728"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"4accf0b39ce4acfd"}},{"id":"qx-b2-025","clusterId":"B","werkstueckRef":"B.23","stufe":1,"question":"Welcher Denkfehler steckt im Schluss des Moderators?","options":["Er nimmt an, die Wahrheit liege in der Mitte, obwohl die beiden Seiten unterschiedlich gut belegt sind (Mittelweg-Trugschluss).","Er übergeht, dass die Ozeanografin vom Fach ist, und gibt der Ansicht eines Laien dasselbe Gewicht (Missachtung der Expertise).","Er behandelt die Internetrecherchen des Gastes wie einen Beleg, obwohl ihre Herkunft und Güte ungeprüft sind (ungeprüfte Quelle).","Er stellt mit dem verdünnten Martini eine neue Behauptung auf, die keine der beiden Seiten belegt hat (unbelegte Behauptung)."],"correctIndex":0,"explanation":"Die Ozeanografin stützt sich auf Messdaten, der Gast nur auf Internetrecherchen ohne belastbare Fakten. Der Moderator wendet eine Kompromiss-Heuristik an, die bei Geschmacksfragen oft taugt (Kino oder Theater? Dann eben ein gemeinsames Abendessen), und überträgt sie auf eine Tatsachenfrage. Die Realität ist aber nicht verpflichtet, zwischen einer belegten und einer unbelegten Aussage zu liegen. Wenn eine Seite erdrückende Belege hat und die andere keine, liegt die Wahrheit bei den Belegen, nicht in der Mitte.","coreRule":"⚡ Die Wahrheit liegt bei den Beweisen, nicht automatisch in der Mitte.","beleg":"Werkstück B.23 (Eingangsszene Ozean/Gin; Kernidee; Analyse; Fußnoten: keine). Frage vom Definitionsabruf zur Fehlererkennung am konkreten Fall umgebaut.","status":"entwurf","scenario":"In einer Podiumsdiskussion sagt eine Ozeanografin: „Nach allen verfügbaren Messdaten ist der Ozean mit Wasser gefüllt.“ Ein Gast widerspricht: „Nach meinen Recherchen im Internet ist der Ozean mit reinem Gin gefüllt.“ Der Moderator fasst zusammen: „Zwei extreme Positionen. Die Wahrheit liegt wohl in der Mitte. Der Ozean ist also eine Art verdünnter Martini.“","kurz":"Der Moderator sucht den Kompromiss, wo es um eine Tatsache geht. Bei Geschmacksfragen taugt die Mitte oft, doch die Wirklichkeit liegt nicht zwischen einer belegten und einer unbelegten Aussage, sondern dort, wo die Belege liegen.","prueffrage":"Worauf stützt sich jede der beiden Aussagen, und wie gut lässt sich das jeweils nachprüfen?","rueckmeldung":[{"option":1,"text":"Fachwissen ist ein guter Anlass, genauer hinzusehen. Entscheidend ist aber, was die Aussage belegt, nicht wer sie sagt. Der Fehler liegt darin, Belegtes und Unbelegtes zu mitteln, und das wäre auch bei zwei Laien falsch."},{"option":2,"text":"Die Internetrecherchen des Gastes sind tatsächlich dünn. Der Moderator macht sie aber nicht zum Beleg, er mittelt nur zwischen den Seiten. Der Fehler liegt in diesem Schritt, nicht in der Quelle des Gastes."},{"option":3,"text":"Der verdünnte Martini ist tatsächlich nirgends belegt. Er ist aber nur das Ergebnis des Mittelns, und dieser Schritt trägt nicht: Die Mitte zwischen belegt und unbelegt ist selbst unbelegt."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Wikipedia: Argument to moderation","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Argument_to_moderation","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „False Balance“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Harker, D. (2015): Creating Scientific Controversies: Uncertainty and Bias in Science and Society. Cambridge University Press","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"4e6f7f6f63386b7b"}},{"id":"qx-b2-026","clusterId":"B","werkstueckRef":"B.23","stufe":2,"question":"Welches Vorgehen ist für beide Streitpunkte zusammen am sinnvollsten?","options":["Bei der Temperatur einigt ihr euch auf 20,5 Grad, und beim Dachfenster einigt ihr euch darauf, dass es wohl nur ein bisschen undicht ist.","Bei der Temperatur einigt ihr euch auf 20,5 Grad, und beim Dachfenster seht ihr beim nächsten Regen nach, ob wieder eine Pfütze entsteht.","Bei der Temperatur messt ihr, welcher Wert objektiv der richtige ist, und beim Dachfenster seht ihr beim nächsten Regen nach, ob es tropft.","Bei der Temperatur einigt ihr euch auf 20,5 Grad, und beim Dachfenster stimmt ihr zu dritt ab, ob es als dicht oder als undicht gelten soll."],"correctIndex":1,"explanation":"Bei der Temperatur geht es um Vorlieben: Lena friert schnell, Tom schwitzt schnell, und ihr habt ein gemeinsames Ziel, eine Wohnung, in der es allen erträglich ist. Dort ist ein Mittelweg wie 20,5 Grad tatsächlich eine gute, pragmatische Lösung. Ob das Dachfenster dicht ist, ist dagegen eine Tatsache. Sie lässt sich nicht aushandeln, sondern wird durch eine Beobachtung entschieden: Bildet sich beim nächsten Regen wieder eine Pfütze, ist es undicht. Die Mitte zwischen einer gut belegten Aussage (Lenas Pfütze) und einer unbelegten ist nicht automatisch wahr, denn die Wahrheit liegt dort, wo die Belege liegen. Sich auf „ein bisschen undicht“ zu einigen oder darüber abzustimmen, klingt friedlich, behandelt aber eine Tatsachenfrage wie eine Geschmacksfrage. Umgekehrt klingt Messen gründlich, doch für das Wohlbefinden zweier verschiedener Menschen gibt es keinen objektiv richtigen Wert, den ein Thermometer anzeigen könnte.","coreRule":"⚡ Kompromisse gehören in die Welt der Präferenzen, nicht in die Welt der Tatsachen.","beleg":"Werkstück B.23 (Kontext & Tiefe; Der Kipppunkt)","status":"entwurf","scenario":"Du wohnst mit Lena und Tom in einer Wohngemeinschaft. Lena friert schnell und will die Heizung auf 22 Grad, Tom schwitzt schnell und will 19 Grad. Außerdem behauptet Tom, das Dachfenster im Flur sei dicht, Lena dagegen hat nach dem letzten Regen eine Pfütze darunter gefunden. Heute Abend wollt ihr beide Streitpunkte klären.","quote":"","quoteLabel":"","kurz":"Bei der Temperatur geht es um Vorlieben, da ist ein Mittelweg wie 20,5 Grad gut. Ob das Fenster dicht ist, ist eine Tatsache und lässt sich nur durch Beobachtung klären. Der Fehler wäre, beides gleich zu behandeln.","prueffrage":"Handelt es sich bei jedem der beiden Streitpunkte um etwas, das sich durch Hinschauen entscheiden lässt, oder um etwas anderes?","rueckmeldung":[{"option":0,"text":"Ein Kompromiss wirkt hier fair, weil beide ein Stück nachgeben. Bei einer Tatsache ist die Mitte aber nicht automatisch wahr: Lenas Pfütze ist ein Beleg, Toms Aussage dagegen nicht, und „ein bisschen undicht“ klärt nichts."},{"option":2,"text":"Das Fenster so zu prüfen, ist genau richtig. Bei der Temperatur gibt es aber keinen objektiv richtigen Wert: Ein Thermometer zeigt nur, wie warm es ist, nicht, was für Lena und Tom angenehm ist."},{"option":3,"text":"Eine Abstimmung klingt gerecht und passt gut zu Geschmacksfragen. Ob Wasser durchkommt, hängt aber nicht von Mehrheiten ab, sondern davon, was man beim nächsten Regen beobachtet."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Wikipedia: Argument to moderation","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Argument_to_moderation","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"9d1dd88177caca55"}},{"id":"qx-b2-027","clusterId":"B","werkstueckRef":"B.23","stufe":3,"question":"In einer Schlichtung schlägt jemand vor: „Der Brandstifter will, dass das Haus brennt, die Feuerwehr will es löschen – einigen wir uns darauf, dass nur das halbe Haus abbrennt.“ Was ist an diesem Vorschlag das Kernproblem?","options":["Der Vorschlag ist ein fauler Kompromiss, wie er in Schlichtungen häufig vorkommt: Beide Seiten bekommen nur die Hälfte und sind am Ende gleich unzufrieden.","Der Vorschlag tut so, als lägen beide Ziele auf derselben Waage, obwohl sie gegensätzlich sind: Das halbe Haus zu opfern wäre für eine Seite ein voller Sieg.","Der Vorschlag belohnt das Auftreten mit maßlosen Forderungen: Wer etwas Zerstörerisches verlangt, erhält durch die Einigung am Ende wenigstens die Hälfte davon.","Der Vorschlag behandelt das Haus wie einen Betrag, den man beliebig teilen kann: Bei einem Gebäude lässt sich eine solche Hälfte aber kaum sinnvoll abgrenzen."],"correctIndex":1,"explanation":"Ein Kompromiss ist nur sinnvoll, wenn die Positionen symmetrisch genug sind. Hier sind die Ziele grundlegend asymmetrisch: Das eine Ziel ist, dass nichts brennt, das andere, dass es brennt. „Das halbe Haus“ klingt nach Mitte, wäre aber ein kompletter Sieg für den Brandstifter und eine komplette Niederlage für die Feuerwehr. Die Mitte zwischen zwei Positionen ist also nicht automatisch die vernünftigste Lösung, sondern kann ein Ergebnis sein, das nur einer Seite nützt. Man kann drei Arten von Asymmetrie unterscheiden: Fakten, Ziele und Macht. Vor einem Kompromiss lohnt die Prüfung, ob die Positionen symmetrisch genug sind.","coreRule":"⚡ Prüfe vor jedem Kompromiss, ob die Ziele überhaupt auf derselben Waage liegen.","beleg":"Werkstück B.23 (Das Problem der Asymmetrie; Kipppunkt)","status":"entwurf","scenario":"","kurz":"Eine Mitte wirkt fair, ist es aber nur bei halbwegs symmetrischen Positionen. Hier sind die Ziele gegensätzlich: Das halbe Haus wäre für den Brandstifter ein voller Sieg, für die Feuerwehr eine Niederlage. Die Mitte nützt nur einer Seite.","prueffrage":"Was genau will die Feuerwehr erreichen, und was genau der Brandstifter?","rueckmeldung":[{"option":0,"text":"Faule Kompromisse gibt es, und sie lassen oft beide unzufrieden zurück. Hier stimmt das Bild nicht: Das halbe Haus ist für den Brandstifter ein voller Erfolg, nicht die Hälfte davon. Es trifft also nicht beide gleich."},{"option":2,"text":"Dass maßlose Forderungen belohnt werden können, ist ein reales Verhandlungsproblem. Der Vorschlag krankt aber an etwas anderem: Er behandelt zwei gegensätzliche Ziele wie gleichrangige Positionen, bei denen die Mitte fair wäre."},{"option":3,"text":"Ein Haus lässt sich in der Praxis durchaus teilweise zerstören, etwa ein Flügel oder eine Etage. Die Schwierigkeit liegt nicht im Abgrenzen der Hälfte, sondern darin, dass diese Hälfte dem Brandstifter komplett nützt und der Feuerwehr komplett schadet."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Wikipedia: Argument to moderation","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Argument_to_moderation","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"612ef0bc158bc867"}},{"id":"qx-b2-028","clusterId":"B","werkstueckRef":"B.23","stufe":4,"question":"Was ist an dem Schluss der Zuschauerin fehlerhaft, und was hat die Sendung damit zu tun?","scenario":"Eine Talkshow lädt zur Klimafrage eine Klimawissenschaftlerin und einen Leugner ein, beide mit exakt gleichen Redeanteilen. Eine Zuschauerin sagt danach: „Dann liegt die Wahrheit wohl irgendwo dazwischen. Ganz so schlimm wird es nicht, aber ein bisschen was ist vielleicht dran.“","options":["Die Sendung lässt eine beruhigende Sicht neben der beunruhigenden zu Wort kommen, und die Zuschauerin neigt zur angenehmeren Deutung (Wunschdenken).","Die Sendung erzeugt den Anschein gleichwertiger Seiten, und die Zuschauerin löst die ungleiche Beweislage als Mittelweg auf (Mittelweg-Trugschluss).","Die Sendung lädt den Leugner ein, und die Zuschauerin schließt daraus, die Redaktion halte seine Sicht für ernst zu nehmen (Autoritätsargument).","Die Sendung zeigt ein einziges Streitgespräch, und die Zuschauerin schließt daraus auf den Stand der gesamten Klimaforschung (voreilige Verallgemeinerung)."],"correctIndex":1,"explanation":"Die gleichwertige Darstellung beider Seiten erzeugt den Eindruck, beide Positionen stünden auf gleich festem Boden. Wer diesen Eindruck übernimmt, rechnet die Positionen zu einem „vernünftigen“ Kompromiss zusammen. Bei Tatsachenfragen gibt es aber keine Pflicht der Wirklichkeit, zwischen einer gut belegten Aussage und einer durch gar keine Beweise gestützten zu liegen. Der Schluss auf die Mitte ist hier ein Trugschluss, weil er die ungleiche Beweislage ignoriert. Und die Sendung hängt damit zusammen, weil die Darstellung als gleichwertig diesen Schluss nahelegt. Zugleich bleibt der Mittelweg bei Geschmacks- und Interessenfragen oft vernünftig. Entscheidend ist, die Positionen vorher nach Belegen zu gewichten, statt sie als gleichwertig zu behandeln.","coreRule":"⚡ Gleich viel Redezeit heißt nicht gleich viel Belege.","beleg":"Werkstück B.23 (Anwendung: Journalismus; Verbindungen: Falsche Ausgewogenheit)","status":"entwurf","kurz":"Gleiche Redeanteile lassen beide Seiten gleich gut belegt wirken, und aus diesem Eindruck folgt leicht die „Wahrheit in der Mitte“. Bei Tatsachenfragen gibt es diese Pflicht zur Mitte aber nicht: Die Positionen müssen erst nach ihren Belegen gewichtet werden.","prueffrage":"Wie viel Redezeit bekam jede Seite, und entspricht das dem Anteil der Fachleute, die jeweils so urteilen?","rueckmeldung":[{"option":0,"text":"Dass die Zuschauerin die angenehmere Deutung bevorzugt, ist gut möglich. Der Fehler im Schluss liegt aber woanders: Sie mittelt zwei Positionen, ohne ihre sehr ungleichen Belege zu gewichten."},{"option":2,"text":"Eine Einladung kann zwar Ernsthaftigkeit signalisieren. Die Zuschauerin beruft sich aber gar nicht auf die Redaktion, sondern rechnet die beiden Positionen zu einer Mitte zusammen, und genau das trägt nicht."},{"option":3,"text":"Aus einem einzelnen Gespräch auf eine ganze Forschung zu schließen, wäre tatsächlich voreilig. Die Zuschauerin tut das aber nicht, sondern bildet aus zwei Aussagen einen Mittelwert, obwohl nur eine davon gut belegt ist."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „False Balance“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"Northwestern University, SESP Magazine (Sommer 2022): The Perils of Bothsidesism","oeffentlich":true,"url":"https://sesp.northwestern.edu/magazine/summer-2022/the-perils-of-bothsidesism.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Imundo, M. N.; Rapp, D. N. (2022): When Fairness is Flawed: Effects of False Balance Reporting and Weight-of-Evidence Statements on Beliefs and Perceptions of Climate Change. Journal of Applied Research in Memory and Cognition","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"58e22424ee736488"}},{"id":"qx-b2-029","clusterId":"B","werkstueckRef":"B.24","stufe":1,"question":"Was ist an dieser Erklärung der Reporterin am ehesten fehlerhaft?","options":["Sie führt ein Geschehen mit vielen zusammenwirkenden Ursachen auf einen einzigen Schuldigen zurück und übergeht die übrigen Faktoren (monokausaler Fehlschluss).","Sie nennt keinen Beleg dafür, dass der Bauleiter geschlampt hat; erst mit einem solchen Nachweis wäre ihre Erklärung tragfähig (unbelegte Behauptung).","Sie urteilt erst nach dem Einsturz und hält deshalb für ein klares Versäumnis des Bauleiters, was vorher womöglich schwer zu erkennen war (Rückschaufehler).","Sie greift mit dem Schlampen des Bauleiters die Ursache heraus, die am leichtesten vorstellbar ist, und hält sie für die wahrscheinlichste (Verfügbarkeitsheuristik)."],"correctIndex":0,"explanation":"Ein Unglück wie dieses entsteht in der Regel aus dem Zusammenspiel vieler Faktoren: Materialermüdung, Belastung, Wartung und Wetter greifen ineinander. Die Reporterin reduziert das auf einen einzigen Bösewicht. Das ist leicht zu erzählen und emotional befriedigend, blendet aber alle übrigen Beiträge aus und führt zu einer scheinbar einfachen Lösung, nämlich den Bauleiter auszutauschen. Bleiben Materialermüdung und mangelnde Wartung bestehen, kann die nächste Brücke genauso versagen. Dass der Bauleiter einen Anteil gehabt haben kann, ist damit nicht ausgeschlossen. Der Fehler liegt darin, ihn zur alleinigen Ursache zu erklären.","coreRule":"⚡ Wo viele Faktoren zusammenwirken, ist die Erklärung mit einem einzigen Schuldigen verdächtig. Frag dich: Welche weiteren Faktoren könnten beigetragen haben?","beleg":"Werkstück B.24 (Kernidee; Analyse)","status":"entwurf","scenario":"Nach dem Einsturz einer Brücke sagt eine Reporterin im Fernsehen: „Die Wahrheit ist ganz einfach: Der Bauleiter hat geschlampt, er ist an allem schuld.“ Ein Gutachten nennt zugleich mehrere Faktoren: ein Baumaterial, das über Jahre ermüdet ist, eine Überlastung durch Schwerverkehr, aufgeschobene Wartungsarbeiten und ungewöhnlich starke Regenfälle.","kurz":"Der Einsturz geht laut Gutachten auf mehrere zusammenwirkende Faktoren zurück, nicht auf eine einzelne Person. Ein Schuldiger ist leicht zu erzählen, blendet aber Material, Belastung, Wartung und Wetter aus. Ein Anteil des Bauleiters bleibt möglich.","prueffrage":"Wie viele Faktoren nennt das Gutachten, und wie viele davon kommen in der Erklärung der Reporterin vor?","rueckmeldung":[{"option":1,"text":"Dass die Reporterin keinen Beleg nennt, stimmt. Selbst mit einem Nachweis, dass der Bauleiter geschlampt hat, bliebe die Erklärung aber falsch: Das Gutachten nennt mehrere Faktoren, und ein einzelner erklärt den Einsturz nicht allein."},{"option":2,"text":"Ein Urteil im Nachhinein kann tatsächlich verzerren. Davon ist hier aber nichts zu erkennen: Es geht nicht darum, was der Bauleiter vorher hätte wissen können, sondern darum, dass die Reporterin ein Zusammenspiel mehrerer Faktoren auf eine einzige Person verkürzt."},{"option":3,"text":"Ein Schuldiger ist leicht zu erzählen, das spielt hier tatsächlich hinein. Das Szenario zeigt aber nichts über eine Wahrscheinlichkeitsschätzung der Reporterin. Ihr Fehler liegt darin, dass ein Zusammenspiel mehrerer Faktoren auf einen einzigen verkürzt wird."}],"familie":"monokausal-erkennen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Reason, J. (2000): Human error: models and management. BMJ 320(7237), 768–770","oeffentlich":true,"doi":"10.1136/bmj.320.7237.768","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1117770/","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Oversimplification“, „Scapegoating“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"7c4317b9b57b2609"}},{"id":"qx-b2-030","clusterId":"B","werkstueckRef":"B.24","stufe":2,"question":"Welches Merkmal des Prospekts ist das deutlichste Warnzeichen für eine unzulässige Vereinfachung?","scenario":"Ein Prospekt erklärt: „Fast alle Krankheiten haben eine Wurzel: Schlacken im Darm. Unsere Detox-Kur beseitigt sie.“","options":["Der Prospekt nennt keine Studie, die zeigt, dass die Detox-Kur die Schlacken im Darm beseitigt, und die Aussage bleibt so eine unbelegte Behauptung.","Der Anbieter verdient am Verkauf der Detox-Kur gegen die Schlacken im Darm, und seine Darstellung ist deshalb vermutlich einseitig.","Sehr verschiedene Krankheiten werden auf eine einzige Wurzelursache zurückgeführt, und dafür wird eine ebenso einfache Lösung verkauft.","Der Prospekt sagt nicht, woran man erkennt, dass die Kur die Schlacken beseitigt hat, und die Aussage lässt sich so nie widerlegen."],"correctIndex":2,"explanation":"Krankheiten haben sehr verschiedene, oft mehrere zusammenwirkende Ursachen. Dass eine einzige „Wurzelursache“ fast alle erklären soll, ist ein typischer monokausaler Fehlschluss. Verdächtig wird es zusätzlich, wenn die Lösung genauso einfach ist wie die Ursache und genau das Produkt ist, das der Prospekt verkauft. Die Reduktion eines vielfältigen Problems auf ein einfaches Ziel ist ein Muster, das man bei komplexen Themen immer prüfen sollte.","coreRule":"⚡ Eine Ursache und eine Lösung, beide ganz einfach: bei komplexen Problemen ein Warnsignal.","beleg":"Werkstück B.24 (Anwendung: Pseudomedizin; Red Flags)","status":"entwurf","kurz":"Sehr verschiedene Krankheiten haben meist verschiedene, oft mehrere zusammenwirkende Ursachen. Eine einzige „Wurzel“ für fast alle samt passender Einfachlösung ist ein typischer monokausaler Fehlschluss, hier genau beim Produkt des Anbieters.","prueffrage":"Welche Aussage des Prospekts müsste am stärksten belegt sein, damit die Kur hält, was sie verspricht?","rueckmeldung":[{"option":0,"text":"Fehlende Belege sind bei Werbung ein berechtigtes Warnzeichen. Sie sagen aber nichts darüber, ob ein vielfältiges Problem auf eine einzige Ursache verkürzt wird, und genau danach fragt die Aufgabe."},{"option":1,"text":"Wer am Verkauf verdient, stellt sein Produkt oft einseitig dar, und das rät zur Vorsicht. Das betrifft aber den Interessenkonflikt, nicht die Vereinfachung selbst; sie wäre auch ohne Verkaufsabsicht ein Fehlschluss."},{"option":3,"text":"Eine Behauptung, deren Erfolg sich nicht überprüfen lässt, ist ein ernstes Warnzeichen für Unwiderlegbarkeit. Das ist aber ein anderes Problem als die Verkürzung vieler verschiedener Krankheiten auf eine einzige Ursache."}],"familie":"monokausal-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „Oversimplification“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"NCCIH (National Center for Complementary and Integrative Health): Detoxes and Cleanses: What You Need To Know","oeffentlich":true,"url":"https://www.nccih.nih.gov/health/detoxes-and-cleanses-what-you-need-to-know","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"b131be5008d46ee2"}},{"id":"qx-b2-031","clusterId":"B","werkstueckRef":"B.24","stufe":3,"question":"Nach einem Schiffsunglück zeigt eine Untersuchung mehrere zusammenwirkende Ursachen: einen starken Sturm, einen unentdeckten Haarriss im Rumpf, eine Fehlentscheidung des Kapitäns unter Druck, eine unzureichend geschulte Crew und veraltete Rettungsboote. Ein Reeder kündigt an, nur den Kapitän zu entlassen, und erklärt: „Damit ist das Problem gelöst.“ Warum ist dieser Schluss riskant?","options":["Weil die übrigen Ursachen wie Haarriss und Crew weiter bestehen und das nächste Schiff gefährden, selbst wenn der Kapitän ersetzt wird.","Weil der Kapitän unter Druck entschied; bleibt dieser Druck bestehen, kann auch ein neuer Kapitän in dieselbe Fehlentscheidung geraten.","Weil der Kapitän nur eine von mehreren Ursachen ist und niemand gezeigt hat, dass gerade seine Entscheidung den größten Anteil hatte.","Weil der starke Sturm zum Unglück beitrug und sich nicht abstellen lässt; bei solchem Wetter bleibt die Gefahr, wen der Reeder auch entlässt."],"correctIndex":0,"explanation":"Der Reeder greift aus mehreren zusammenwirkenden Ursachen eine einzige heraus und behandelt sie als die Lösung. Wer nur dieses einfache Ziel bekämpft, lässt die übrigen Ursachen unangetastet: den Haarriss im Rumpf, die schlecht geschulte Crew, die veralteten Rettungsboote. Das nächste Schiff trägt dann dieselben Risiken. Bei einfachen, technischen Problemen wie einem Wackelkontakt ist die Suche nach der einen Ursache dagegen oft richtig; bei komplexen Systemen mit vielen zusammenwirkenden Faktoren führt sie in die Irre. Eine gute Prüffrage lautet: Welche fünf weiteren, vielleicht weniger offensichtlichen Faktoren könnten ebenfalls zu diesem Ergebnis beigetragen haben?","coreRule":"⚡ Wer nur den Sündenbock behandelt, lässt die Ursachen des Problems unangetastet.","beleg":"Werkstück B.24 (Das Geheimnis des Schiffsunglücks; Der Kipppunkt)","status":"entwurf","scenario":"","kurz":"Mehrere Ursachen wirkten zusammen, und der Reeder behebt nur eine. Haarriss, schlecht geschulte Crew und veraltete Rettungsboote bleiben, das nächste Schiff trägt dieselben Risiken. Der Fehler ist, aus vielen Faktoren einen herauszugreifen und ihn als Lösung zu behandeln.","prueffrage":"Welche Faktoren, die nichts mit dem Kapitän zu tun haben, tauchen im Untersuchungsbericht noch auf?","rueckmeldung":[{"option":1,"text":"Dass der Druck bestehen bleibt, ist ein berechtigtes Beispiel dafür, was bei einer Entlassung unverändert bleibt. Es ist aber nur eine unter mehreren Ursachen; auch Rumpf, Schulung und Rettungsboote wirken weiter, und der Schluss des Reeders bleibt aus diesem breiteren Grund riskant."},{"option":2,"text":"Dass der Anteil des Kapitäns nicht belegt ist, stimmt. Der Reeder behauptet aber gar nicht, seine Entscheidung wiege am schwersten, sondern dass mit der Entlassung alles erledigt sei. Selbst bei größtem Anteil blieben die übrigen Ursachen bestehen."},{"option":3,"text":"Der Sturm lässt sich tatsächlich nicht beeinflussen. Das Szenario nennt ihn aber nur als einen von mehreren Beiträgen; gefährlich wird die Lage vor allem durch die beeinflussbaren Ursachen wie Rumpf, Crew und Rettungsboote, die der Reeder unangetastet lässt."}],"familie":"monokausal-erkennen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Reason, J. (2000): Human error: models and management. BMJ 320(7237), 768–770","oeffentlich":true,"doi":"10.1136/bmj.320.7237.768","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1117770/","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „Oversimplification“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"0e2e14eb6315658c"}},{"id":"qx-b2-032","clusterId":"B","werkstueckRef":"B.24","stufe":4,"question":"Welche Prüfung wendest du auf diese Slogans an?","scenario":"Im Wahlkampf heißt es: „Warum geht es uns schlecht? Wegen der Milliardäre!“ Das gegnerische Lager antwortet mit ebenso einfachen Parolen über eine andere Gruppe.","options":["Beide Parolen nennen eine Gruppe als Ursache; prüfe, ob die Milliardäre bzw. die andere Gruppe tatsächlich zu der schlechten wirtschaftlichen Lage beitragen.","Beide Parolen kommen aus dem Wahlkampf; prüfe, welches Lager weniger eigene Interessen verfolgt, und halte dich an dessen Erklärung der schlechten Lage.","Beide Parolen sind einseitig; prüfe, ob die Wahrheit zwischen ihnen liegt und die Milliardäre wie die andere Gruppe je einen Teil zur schlechten Lage beitragen.","Beide Parolen machen eine einzige Gruppe zum Schuldigen, die Milliardäre bzw. die andere; frag, welche weniger offensichtlichen Faktoren mitwirken könnten."],"correctIndex":3,"explanation":"Beide Slogans haben denselben Fehler: Ein vielschichtiges Problem wie wirtschaftliche Not hat selten eine einzige Ursache, sondern entsteht aus dem Zusammenspiel vieler Faktoren. Eine Parole, die eine einzige Gruppe als Schuldige benennt, ist eingängig und emotional befriedigend, aber gerade deshalb verdächtig. Die richtige Prüfung fragt unabhängig von der politischen Richtung, welche weiteren, weniger offensichtlichen Faktoren mitgewirkt haben könnten. Einzelne Akteure können tatsächlich zu einem Problem beitragen, nur selten allein. Die Prüfung von Zahlen ist bei Parolen oft sinnvoll, hier nennt aber keine Parole eine Zahl, deren Herkunft sich klären ließe. Der Vergleich mit dem Originalzusammenhang hilft bei verkürzten Zitaten, doch hier wird niemand zitiert. Die Prüfung früherer Prognosen lohnt bei Versprechen, aber die Parolen sagen nichts über die Zukunft, sie benennen nur Schuldige.","coreRule":"⚡ Eine Erklärung wird nicht dadurch besser, dass sie einen klaren Schuldigen anbietet.","beleg":"Werkstück B.24 (Anwendung: In der Politik; Anti-Denkmuster: Aktivierungs-Frage), keine Fußnoten","status":"entwurf","kurz":"Wirtschaftliche Not hat selten eine einzige Ursache, sondern entsteht aus vielen Faktoren. Wer eine Gruppe als Schuldige nennt, bleibt beim Slogan-Schema, egal welche. Prüfen heißt: Welche weniger offensichtlichen Faktoren wirken mit?","prueffrage":"Was wäre in den Slogans eigentlich zu erklären, und wie viele Ursachen kommen darin vor?","rueckmeldung":[{"option":0,"text":"Dass einzelne Akteure zu einem Problem beitragen können, ist durchaus möglich. Doch diese Prüfung bleibt in der Fragestellung der Parole stecken: Sie fragt nur nach der einen Gruppe und blendet aus, was sonst noch mitwirkt."},{"option":1,"text":"Eigeninteressen im Wahlkampf zu bedenken, ist grundsätzlich sinnvoll. Aber dann entscheidet das Vertrauen in ein Lager, nicht eine Prüfung der Ursachen. Und beide Parolen haben denselben Fehler, unabhängig davon, wer sie ausruft."},{"option":2,"text":"Dass beide Parolen einseitig sind, stimmt. Der Mittelweg ist aber selbst ein Schema: Er kennt nur zwei Verursacher und fragt nicht, welche weiteren Faktoren eine Rolle spielen. Die Mitte zwischen zwei verkürzten Erklärungen ist nicht automatisch richtig."}],"familie":"monokausal-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Oversimplification“, „Scapegoating“, „Bandwagon“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"4d04f52efd4ebb93"}},{"id":"qx-b2-033","clusterId":"B","werkstueckRef":"B.25","stufe":1,"question":"Welche Frage hilft dir am besten zu erkennen, ob du deine Denkwerkzeuge gerade als Späher oder als Soldat einsetzt?","options":["Habe ich die Denkfehler meines Gegenübers korrekt benannt, und lassen sich meine Einwände zum Gesundheitsthema fachlich belegen?","Wie überzeugend wirken meine Einwände auf Dritte, die die Diskussion zum Gesundheitsthema mitlesen, und bleibe ich dabei sachlich?","Welche Beobachtung zum Gesundheitsthema würde mich dazu bringen, meine eigene Einschätzung zu ändern, und habe ich danach gesucht?","Habe ich mich vor der Diskussion über das Gesundheitsthema in aktuelle Studien eingelesen, damit meine Einwände belastbar sind?"],"correctIndex":2,"explanation":"Dieselben Werkzeuge (Recherche, Logik, Befragung) können der Wahrheitssuche dienen oder dem Gewinnen um jeden Preis. Zwei Anwälte mit identischem Handwerk zeigen das: Anwalt A sammelt auch die Fakten, die seinem Mandanten schaden, baut den stärksten Fall der Gegenseite, um Schwachstellen zu finden, und ist bereit, seine Strategie bei widersprüchlichen Beweisen anzupassen. Anwalt B sucht nur Munition für seine vorgefasste Schlussfolgerung. Wer prüft, welche Beobachtung ihn umstimmen würde und ob er danach gesucht hat, testet genau diese Offenheit für Gegenbeweise; das ist die Haltung des Spähers. Dass du Denkfehler kennst, macht dich noch nicht zum Wahrheitssucher. Entscheidend ist, wofür du die Werkzeuge einsetzt und ob du sie auch auf dich selbst anwendest. Die Frage nach korrekt benannten Denkfehlern prüft die Treffsicherheit deiner Einwände, nicht dein Ziel; auch ein Soldat kann richtig liegen. Die Wirkung auf Mitlesende und der sachliche Ton betreffen die Außenwirkung, nicht die Offenheit für Gegenbeweise. Die Vorbereitung mit Studien kann Soldat wie Späher dienen und zeigt erst durch das Ziel, was sie ist.","coreRule":"⚡ Werkzeuge des Denkens sind neutral: Entscheidend ist, ob du sie auch gegen deine eigene Position richtest.","beleg":"Werkstück B.25 (Eingangsszene; Kernidee); Fn. gl-b-galef (Galef, TEDxPSU 2016; The Scout Mindset 2021)","status":"entwurf","scenario":"Du hast dich intensiv mit logischen Fehlschlüssen beschäftigt. In einer Diskussion über ein Gesundheitsthema fällt dir auf, dass du vor allem darauf achtest, wo dein Gegenüber einen Denkfehler macht. Dein Ziel ist es, die Diskussion zu gewinnen.","kurz":"Entscheidend ist, ob eine Beobachtung dich umstimmen könnte und ob du nach ihr gesucht hast. Wer nur prüft, ob seine Einwände stimmen, testet die Treffsicherheit, nicht das Ziel: Auch ein Soldat kann richtig liegen.","prueffrage":"Worauf achtest du in dieser Diskussion bisher vor allem, und was soll am Ende dabei herauskommen?","rueckmeldung":[{"option":0,"text":"Treffsichere, belegbare Einwände sind wichtig. Sie sagen aber nur, ob du richtig liegst, nicht wozu du deine Werkzeuge einsetzt: Auch jemand, der nur gewinnen will, kann mit seinen Einwänden recht haben."},{"option":1,"text":"Sachlichkeit und Überzeugungskraft sind sinnvolle Ziele. Sie betreffen jedoch die Außenwirkung. Wer gewinnen will, fragt genauso, und über deine Offenheit für Gegenbeweise sagt das nichts."},{"option":3,"text":"Gute Vorbereitung macht Einwände belastbarer. Dasselbe Einlesen kann aber der Wahrheitssuche dienen oder nur Munition für eine feste Schlussfolgerung liefern; erst das Ziel zeigt, was es ist."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Galef, J. (2016): Why you think you're right -- even if you're wrong. TEDxPSU, Februar 2016 (TED-Seite mit Transkript)","oeffentlich":true,"url":"https://www.ted.com/talks/julia_galef_why_you_think_you_re_right_even_if_you_re_wrong/transcript","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Galef, J. (2021): The Scout Mindset. New York: Portfolio","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"b351833e1ea4f481"}},{"id":"qx-b2-034","clusterId":"B","werkstueckRef":"B.25","stufe":2,"question":"Welche Haltung zeigt sich in dieser Selbstbeobachtung, und was folgt daraus?","scenario":"Du merkst: In Online-Debatten freust du dich vor allem, wenn du den Gegner „besiegt“ hast. Dein Wissen über Denkfehler nutzt du vor allem, um andere zu katalogisieren und abzuwerten. Deine wichtigen Meinungen hast du trotz ständigen Debattierens lange nicht mehr geändert.","options":["Du verteidigst eine feste Position: Das Wissen dient dem Gewinnen und dem Status, und die Gefahr, selbstgerecht zu werden, ist schon nahe.","Du hast eine gefestigte Sicht: Dass du sie trotz vieler Debatten lange nicht ändern musstest, spricht dafür, dass sie gut begründet ist.","Du bist kritisch, nur zu scharf im Ton: Die Denkfehler anderer zu benennen ist richtig, allein das Abwerten solltest du dir abgewöhnen.","Du hast Freude am Wettstreit: Dass dich ein gewonnener Schlagabtausch freut, ist menschlich und sagt über dein Denken noch wenig aus."],"correctIndex":0,"explanation":"Wer sich über das Besiegen anderer freut, sein Wissen über Denkfehler vor allem zum Abwerten nutzt und trotz ständiger Debatten nie umdenkt, setzt Werkzeuge des kritischen Denkens als Waffen ein, nicht als Instrumente der Selbstkorrektur. Dass man trotz ständigen Debattierens lange keine wichtige Meinung aufgrund neuer Beweise geändert hat, ist ein Warnzeichen für die Soldaten-Mentalität. Eine lange unveränderte Meinung ist also kein Beleg dafür, dass die eigene Sicht stimmt. Kippt die Liebe zum Recht-Haben über die Liebe zur Wahrheit, wird aus dem Skeptiker ein Dogmatiker mit schärferem Schwert.","coreRule":"⚡ Frag dich bei jedem Denkwerkzeug: Setze ich es ein, um die Wahrheit zu finden, oder um recht zu behalten?","quote":"Benutze ich dieses Werkzeug wie ein Späher oder wie ein Soldat?","quoteLabel":"Prüffrage:","beleg":"Werkstück B.25 (Red Flags; Kipppunkt; Anti-Denkmuster)","status":"freigegeben","freigabe":{"datum":"2026-10-15","pruefsumme":"62eefc04fcab94e6","vermerk":"Prüfpult (Sturm, erste Charge nach den neuen falschen Optionen)"},"kurz":"Wer Denkfehler vor allem bei anderen sucht und trotz vieler Debatten nie umdenkt, nutzt kritisches Denken als Waffe statt zur Selbstkorrektur. Dass eine Meinung lange gleich bleibt, belegt dabei nicht, dass sie stimmt.","prueffrage":"Wie oft hat eine deiner vielen Debatten in letzter Zeit eine deiner wichtigen Meinungen tatsächlich verändert?","rueckmeldung":[{"option":1,"text":"Gefestigte Sichten gibt es, und gut begründete Meinungen müssen sich nicht ständig ändern. Dass sie lange gleich blieb, zeigt aber nur Stabilität, keine Begründung, zumal du dein Wissen nie gegen dich selbst richtest."},{"option":2,"text":"Das Abwerten ist tatsächlich ein Problem, und Denkfehler zu benennen ist an sich in Ordnung. Ein milderer Ton ändert aber nichts an der Haltung: Das Wissen dient dem Gewinnen, und deine eigenen Meinungen bleiben unberührt."},{"option":3,"text":"Freude am Wettstreit ist menschlich, und ein gewonnener Schlagabtausch darf Spaß machen. Dein Fall geht darüber hinaus: Du wertst andere ab und änderst trotz vieler Debatten nie eine wichtige Meinung. Das ist mehr als ein gutes Gefühl."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Galef, J. (2016): Why you think you're right -- even if you're wrong. TEDxPSU, Februar 2016 (TED-Seite mit Transkript)","oeffentlich":true,"url":"https://www.ted.com/talks/julia_galef_why_you_think_you_re_right_even_if_you_re_wrong/transcript","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Galef, J. (2021): The Scout Mindset. New York: Portfolio","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"62eefc04fcab94e6"}},{"id":"qx-b2-035","clusterId":"B","werkstueckRef":"B.25","stufe":4,"question":"Wie gehst du mit diesem Gesprächspartner am besten um?","scenario":"In einem Forum fordert jemand eine „offene Debatte“ zu einer Behauptung, die längst nach allen Regeln der Wissenschaft widerlegt wurde. Er lügt dabei systematisch, stellt deine Argumente verzerrt als Strohmänner dar und besteht darauf, du müsstest als Skeptiker offen bleiben.","options":["Du führst die Debatte so lange weiter, bis er seinen Irrtum öffentlich einräumt und dir in der Sache recht gibt.","Du prüfst die Behauptung immer wieder neu und offen, weil Skepsis verlangt, jede Idee ständig zu hinterfragen.","Du stellst fest, dass er sich nicht an die Bedingungen einer ehrlichen Auseinandersetzung hält, und steigst aus der Debatte aus.","Du bietest einen Mittelweg an, bei dem beide Seiten gleich viel nachgeben und sich in der Mitte treffen."],"correctIndex":2,"explanation":"Offenheit heißt, Behauptungen anhand von Belegen zu prüfen, nicht, jede Idee gleich zu behandeln. Eine Behauptung, die längst nach allen Regeln der Wissenschaft widerlegt wurde, verdient keine erneute offene Prüfung: Eine erneute „offene“ Debatte darüber verschwendet Zeit und ist eine Form der falschen Ausgewogenheit. Wer zudem systematisch lügt und Strohmänner baut, will nicht herausfinden, was stimmt, sondern gewinnen. Hier ist die „offene“ Fortführung der Debatte keine Tugend, sondern Selbstschädigung; darum greift die Ausstiegs-Strategie. Auch ein Mittelweg löst das Problem nicht, denn dein Gegenüber sucht gar nicht die Wahrheit. Der Ausstieg ist daher kein Akt der Engstirnigkeit, sondern eine begründete Entscheidung, die deine Energie schützt.","coreRule":"⚡ Offenheit heißt, Behauptungen ernsthaft zu prüfen, nicht, jedem Debattenpartner unbegrenzt Zeit und Aufmerksamkeit zu schenken.","beleg":"Werkstück B.25 (Die Grenzen der Offenheit; Anti-Denkmuster)","status":"freigegeben","freigabe":{"datum":"2026-10-15","pruefsumme":"070df7c706860229","vermerk":"Prüfpult (Sturm, erste Charge nach den neuen falschen Optionen)"},"kurz":"Eine längst widerlegte Behauptung verdient keine erneute „offene“ Prüfung, und wer systematisch lügt und Strohmänner baut, will gewinnen statt klären. Offenheit heißt nicht, um jeden Preis weiterzudiskutieren; der Ausstieg ist begründet.","prueffrage":"Was ist über die Behauptung selbst längst geklärt, und was hat er bisher mit deinen Argumenten gemacht?","rueckmeldung":[{"option":0,"text":"Hartnäckigkeit klingt nach Standhaftigkeit. Wer aber systematisch lügt und Strohmänner baut, will nicht herausfinden, was stimmt, und wird kaum einlenken. Du würdest nur Zeit und Kraft in eine Debatte stecken, die nicht auf Klärung zielt."},{"option":1,"text":"Skepsis heißt, Behauptungen anhand von Belegen zu prüfen, nicht, jede Idee gleich zu behandeln. Eine längst widerlegte Behauptung immer wieder neu zu öffnen, wäre falsche Ausgewogenheit und keine Offenheit."},{"option":3,"text":"Ein Mittelweg ist oft ein guter Ausgleich, wenn Interessen gegeneinanderstehen. Bei einer Tatsachenfrage gibt es aber keine Mitte zwischen widerlegt und nicht widerlegt. Außerdem sucht dein Gegenüber gar keine Lösung, sondern will gewinnen."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Grimes, D. R. (2019): A dangerous balancing act. EMBO Reports 20(8), e48706","oeffentlich":true,"doi":"10.15252/embr.201948706","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6680130/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Schmid, P.; Schwarzer, M.; Betsch, C. (2020): Weight-of-Evidence Strategies to Mitigate the Influence of Messages of Science Denialism in Public Discussions. Journal of Cognition 3(1), 36","oeffentlich":true,"doi":"10.5334/joc.125","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7528676/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"070df7c706860229"}},{"id":"qx-b2-036","clusterId":"B","werkstueckRef":"B.25","stufe":3,"question":"Was erklärt dieses Verhalten am besten?","scenario":"Jemand wirft in Online-Diskussionen ständig anderen „Strohmann“ und „Zirkelschluss“ vor und kennt viele Fachbegriffe für Denkfehler. Wird aber seine eigene Lieblingsthese kritisiert, tauchen dieselben Fehler in seinen Antworten auf. Er hat seine Ansicht seit Jahren nicht korrigiert, obwohl er täglich debattiert.","options":["Er setzt sein Wissen über Denkfehler als Waffe gegen andere ein, um seine vorgefasste Meinung zu verteidigen, statt es zur Selbstkorrektur zu nutzen.","Er hält seine Lieblingsthese für gut begründet, und solange ihn kein Einwand wirklich überzeugt, sieht er keinen Anlass, seine Ansicht zu ändern.","Er erkennt Denkfehler bei anderen leichter als bei sich, ein verbreiteter blinder Fleck, der sich mit mehr Übung im Debattieren allmählich geben sollte.","Er hängt an seiner Lieblingsthese, und weil ihn Kritik daran stärker trifft, unterlaufen ihm dort im Eifer Fehler, die er bei anderen sofort bemerkt."],"correctIndex":0,"explanation":"Der bloße Besitz von Denkwerkzeugen macht niemanden zum wahrheitssuchenden Denker. Die Julia Galef zugeschriebene Unterscheidung beschreibt es so: Wer in der Soldaten-Mentalität denkt, will eine Position verteidigen und nutzt sein Wissen als Waffe. Wer in der Späher-Mentalität denkt, will herausfinden, was tatsächlich stimmt, und prüft zuerst sich selbst. Hier zeigen drei Signale die Soldaten-Haltung: Die Fehlerjagd richtet sich nur nach außen, die eigene These bleibt unangetastet, und trotz täglicher Debatten hat sich über Jahre nichts geändert. Auch kluge Verschwörungsgläubige sind ein typisches Beispiel: Sie werfen anderen Fehlschlüsse vor und begehen dieselben selbst. Das Ziel entscheidet, ob die Werkzeuge der Wahrheit oder der Verteidigung dienen.","coreRule":"⚡ Wissen über Denkfehler schützt nicht vor ihnen; es verpflichtet zur Selbstprüfung.","beleg":"Werkstück B.25 (Anwendung: Verschwörungs-„Forscher“; Kipppunkt)","status":"entwurf","kurz":"Er nutzt sein Wissen über Denkfehler, um seine Position zu verteidigen, nicht um herauszufinden, was stimmt. Deshalb richtet sich die Fehlersuche nur nach außen, und die eigene These bleibt trotz täglicher Debatten jahrelang unangetastet.","prueffrage":"Gegen wen richtet er seine Fehlervorwürfe, und was hat sich nach Jahren täglicher Debatten an seiner eigenen Ansicht verändert?","rueckmeldung":[{"option":1,"text":"Seine These für gut begründet zu halten, klingt nach einer ruhigen Erklärung. Dieselben Fehler, die er anderen vorwirft, stecken aber in seinen eigenen Antworten, und das spricht gegen eine solide Begründung. Dass ihn kein Einwand überzeugt, ist hier das Symptom."},{"option":2,"text":"Bei anderen Fehler leichter zu sehen als bei sich selbst, ist tatsächlich verbreitet und kann hier mitspielen. Ein bloßer blinder Fleck würde sich aber mit täglicher Übung eher bessern. Dass sich über Jahre nichts bewegt, deutet auf ein anderes Ziel als bloßes Übersehen."},{"option":3,"text":"Die Bindung an die eigene These und der Eifer können Fehler begünstigen. Ein Ausrutscher im Eifer erklärt aber nicht, warum die Fehlerjagd durchgehend nur nach außen geht und sich über Jahre nichts ändert. Das Muster wirkt eher gewollt als zufällig."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Galef, J. (2016): Why you think you're right -- even if you're wrong. TEDxPSU, Februar 2016 (TED-Seite mit Transkript)","oeffentlich":true,"url":"https://www.ted.com/talks/julia_galef_why_you_think_you_re_right_even_if_you_re_wrong/transcript","abruf":"2026-10-12"},{"typ":"doi","kurz":"West, R. F.; Meserve, R. J.; Stanovich, K. E. (2012): Cognitive Sophistication Does Not Attenuate the Bias Blind Spot. Journal of Personality and Social Psychology 103(3), 506–519","oeffentlich":false,"doi":"10.1037/a0028857"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"8e6e591e1dfad976"}},{"id":"qx-b2-037","clusterId":"B","werkstueckRef":"B.26","stufe":1,"question":"Was ist die sinnvollste Reaktion auf diesen Impuls?","scenario":"Beim Kauf von Konzerttickets blinkt ein roter Balken: „Nur noch 17 Tickets verfügbar! 250 Leute sehen sich dieses Angebot gerade an!“ Du wolltest eigentlich noch ein paar Tage überlegen, ob du hingehst. Jetzt schlägt dein Herz schneller, und du spürst den Impuls, sofort zu bestellen.","options":["Die 250 Interessenten als Hinweis nehmen, dass sich das Konzert lohnt, und bestellen, bevor die letzten 17 Tickets weg sind.","Innehalten und prüfen, ob dich der blinkende Balken oder der Wert des Konzerts antreibt, und erst danach entscheiden, ob du bestellst.","Deinem schnellen Herzschlag trauen, der zeigt, wie sehr du dieses Konzert willst, und sofort bestellen, solange es Tickets gibt.","Nachprüfen, ob wirklich nur noch 17 Tickets übrig sind, und bei echter Knappheit bestellen, weil sie zeigt, dass das Konzert begehrt ist."],"correctIndex":1,"explanation":"„Nur noch 17“ (Knappheit) und „250 Leute sehen sich das gerade an“ (sozialer Beweis) sagen nichts darüber, ob das Konzert dir das Geld wert ist. Sie erzeugen Zeitdruck und sollen die ruhige Abwägung umgehen. Seltenes wirkt automatisch wertvoller, und was viele wollen, wirkt automatisch richtig, auch wenn beides über den eigentlichen Wert nichts verrät. Der Impuls ist ein Warnsignal, kein Argument. Sinnvoll ist, ihn zu bemerken und gezielt zu fragen: Will ich das, weil ich den Wert verstanden habe, oder nur, weil ich Angst habe, es zu verpassen?","coreRule":"⚡ „Nur noch wenige“ und „viele schauen gerade“ sind Druckmittel, keine Informationen über den Wert. Prüfe, was dich antreibt, bevor du entscheidest.","beleg":"Werkstück B.26 (Eingangsszene Situation B; Analyse: drei Heuristiken; Anwendung: Alltag & Konsum)","status":"entwurf","kurz":"Der Balken erzeugt Zeitdruck, sagt aber nichts darüber, ob dir das Konzert sein Geld wert ist. Der Fehler: Seltenes und Begehrtes wirkt automatisch wertvoll. Erst den Impuls bemerken, dann fragen, ob dich der Wert oder die Angst, etwas zu verpassen, antreibt.","prueffrage":"Was verraten dir die beiden Zahlen im roten Balken über das Konzert selbst?","rueckmeldung":[{"option":0,"text":"250 Ansehende wirken wie ein Qualitätszeichen. Sie sehen aber nur auf dasselbe Angebot und urteilen nicht unabhängig, sodass die Zahl über den Wert des Konzerts nichts verrät."},{"option":2,"text":"Der Herzschlag fühlt sich wie echtes Wollen an. Hier hat ihn aber der Balken ausgelöst, er ist ein Warnsignal und kein Argument dafür, dass dir das Konzert den Preis wert ist."},{"option":3,"text":"Die Zahl nachzuprüfen ist sorgfältig und besser als blindes Vertrauen. Doch auch echte Knappheit sagt nichts darüber, ob das Konzert den Preis wert ist, und eigentlich wolltest du erst überlegen, ob du hingehst."}],"familie":"mehrheit-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Federal Trade Commission (2022): Bringing Dark Patterns to Light. Staff Report, September 2022","oeffentlich":true,"url":"https://www.ftc.gov/system/files/ftc_gov/pdf/P214800%20Dark%20Patterns%20Report%209.14.2022%20-%20FINAL.pdf","seite":"21–22, 37","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"eb17fa1d08fa22e2"}},{"id":"qx-b2-038","clusterId":"B","werkstueckRef":"B.26","stufe":3,"question":"Ein Kollege schwärmt von einem Vermögenswert, dessen Preis sich in sechs Monaten vervielfacht hat. Du fragst ihn, warum er gerade jetzt kauft. Welche Antwort deutet am stärksten darauf hin, dass er sich in einer Spekulationsblase bewegt?","options":["„Die Preise sind höher als vor einem Jahr, und auch große Anleger kaufen deutlich mehr dazu als früher.“","„Ich habe mir Gewinne, Umsätze und Kennzahlen angesehen, und sie tragen den Anstieg aus meiner Sicht weiterhin.“","„Seit sich die ersten Kritiker gemeldet haben, hat sich der Anstieg verlangsamt, ich warte, ob er wieder anzieht.“","„Ob er etwas wert ist, weiß ich nicht genau, aber morgen ist er teurer, und ich will nicht als Einziger draußen bleiben.“"],"correctIndex":3,"explanation":"Typisch für eine Blase ist, dass sich die Begründung vom Wert auf die Erwartung weiterer Preissteigerungen verlagert und die Angst, nicht dabei zu sein, den Kauf antreibt. Dann kauft man, weil der Preis steigt, nicht weil man verstanden hat, was der Vermögenswert wert ist. Ein höherer Preis oder zusätzliche Käufe allein sind noch kein Beleg, auch ein kräftiger Anstieg kann durch Gewinne und Umsätze gedeckt sein. Entscheidend ist, woher die Rechtfertigung stammt: aus dem Wert der Sache oder aus der Hoffnung auf den nächsten Käufer.","coreRule":"⚡ Prüfe die Begründung: Kaufst du wegen des Wertes oder weil der Preis gestern gestiegen ist?","quote":"","quoteLabel":"","beleg":"Werkstück B.26 (Red Flags: eine Spekulationsblase; Anti-Denkmuster)","status":"entwurf","scenario":"","kurz":"Wer kauft, weil der Preis morgen höher sein wird, und aus Angst, draußen zu bleiben, stützt sich nicht mehr auf den Wert der Sache. Der naheliegende Fehler ist, schon den Preisanstieg selbst als Zeichen einer Blase zu lesen.","prueffrage":"Was müsste dein Kollege über den Vermögenswert selbst wissen, um beurteilen zu können, ob der heutige Preis angemessen ist?","rueckmeldung":[{"option":0,"text":"Gestiegene Preise und mehr Käufe großer Anleger wirken wie ein Warnsignal. Beides gibt es aber auch bei einem Anstieg, den Gewinne und Umsätze decken, und dass er den Wert nicht kennt oder nur aus Angst kauft, draußen zu bleiben, sagt er nicht."},{"option":1,"text":"Wer Gewinne, Umsätze und Kennzahlen prüft, begründet seinen Kauf mit dem Wert der Sache. Das ist das Gegenteil einer Blasenlogik, auch wenn sich im Einzelfall streiten lässt, ob die Zahlen den Anstieg wirklich tragen."},{"option":2,"text":"Das Abwarten nach der Kritik zeigt, dass er auf den Kursverlauf schaut. Er kauft aber gerade nicht überstürzt, und weder Unwissen über den Wert noch die Angst, draußen zu bleiben, ist darin zu erkennen."}],"familie":"mehrheit-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Shiller, R. J. (2014): Speculative Asset Prices (Nobel Prize Lecture). Cowles Foundation Discussion Paper 1936","oeffentlich":true,"url":"https://cowles.yale.edu/sites/default/files/2022-08/d1936.pdf","seite":"2","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Kindleberger, C. P.; Aliber, R. Z. (2005): Manias, Panics, and Crashes. 5. Aufl., Hoboken: Wiley","oeffentlich":false}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"604127df74b21fb9"}},{"id":"qx-b2-039","clusterId":"B","werkstueckRef":"B.26","stufe":4,"question":"Welche Frage stellst du dir, bevor du auf das Angebot eingehst?","scenario":"Eine Freundin drängt: „Es gibt nur 20 Plätze beim Wochenend-Workshop mit dem berühmten Guru. Danach nimmt er drei Jahre lang keine neuen Schüler. Alle sagen, es hat ihr Leben verändert.“","options":["Kann ich mir den Workshop zeitlich und finanziell leisten, wenn ich mich jetzt rasch anmelde, bevor die 20 Plätze an andere vergeben sind?","Würde ich den Workshop auch ohne die Begrenzung auf 20 Plätze und ohne Frist buchen, oder treibt mich die Angst, etwas zu verpassen?","Ist der Guru wirklich so berühmt, wie meine Freundin sagt, und welche Ausbildung oder nachprüfbaren Erfolge kann er selbst vorweisen?","Wer genau sagt, der Workshop habe sein Leben verändert, und kann ich mit einigen dieser Menschen selbst sprechen, bevor ich zusage?"],"correctIndex":1,"explanation":"Platzbegrenzung („nur 20 Plätze“), Frist („drei Jahre keine neuen Schüler“) und Erfolgsberichte („alle sagen, es hat ihr Leben verändert“) sagen nichts darüber, ob der Workshop hält, was er verspricht. Knappheit und Exklusivität lassen Dinge automatisch wertvoller erscheinen, und eine große Zahl von Begeisterten wirkt als sozialer Beweis: Popularität wird mit Wert verwechselt. Beides erzeugt Zeitdruck und den Wunsch, zu einer auserwählten Gruppe zu gehören. Die beste Prüffrage trennt deshalb den Wert der Sache von dem Druck, der um sie herum aufgebaut wird: Würde das Angebot auch ohne Verknappung überzeugen? Wenn nicht, bezahlst du für die Angst vor dem Verpassen und nicht für den Inhalt.","coreRule":"⚡ Wer wegen der Angst vor dem Verpassen kauft, bezahlt für das Gefühl, nicht für die Sache.","beleg":"Werkstück B.26 (Eingangsszene Situation C; Anwendung: Esoterik; Anti-Denkmuster)","status":"entwurf","kurz":"Knappheit, Frist und viele Begeisterte sagen nichts darüber, ob der Workshop hält, was er verspricht. Sie lassen ihn nur wertvoller wirken und erzeugen Zeitdruck. Erst die Frage, ob er auch ohne Verknappung überzeugt, trennt Inhalt und Druck.","prueffrage":"Welche der drei Aussagen deiner Freundin sagt etwas darüber, was im Workshop tatsächlich geschieht?","rueckmeldung":[{"option":0,"text":"Zeit und Geld zu prüfen ist vernünftig. Die Frage übernimmt aber die Knappheit als gegeben und plant im Rahmen des Drucks („rasch anmelden“), statt ihn selbst zu hinterfragen. Ob der Workshop den Preis wert ist, bleibt offen."},{"option":2,"text":"Nach Qualifikation und nachprüfbaren Erfolgen des Gurus zu fragen ist sinnvoll. Sie bleibt aber beim Menschen, nicht beim Angebot: Auch ein ausgewiesener Guru kann Plätze künstlich verknappen, und der Druck bliebe unberührt."},{"option":3,"text":"Mit Teilnehmenden zu sprechen ist eine gute Quellenprüfung und kann viel zeigen. Es bleibt aber bei den Erfolgsberichten, und viele Begeisterte beweisen noch keinen Wert. Der Einfluss von Knappheit und Frist auf deine Entscheidung wäre so noch nicht geprüft."}],"familie":"mehrheit-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Federal Trade Commission (2022): Bringing Dark Patterns to Light. Staff Report, September 2022","oeffentlich":true,"url":"https://www.ftc.gov/system/files/ftc_gov/pdf/P214800%20Dark%20Patterns%20Report%209.14.2022%20-%20FINAL.pdf","seite":"21–22","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"39281f62eebfd3eb"}},{"id":"qx-b2-040","clusterId":"B","werkstueckRef":"B.26","stufe":2,"question":"Welche Beobachtung zeigt am deutlichsten, dass hier Angst vor dem Verpassen ausgenutzt wird, statt dass ein Angebot überzeugen soll?","scenario":"Eine Bekannte lädt dich zu einem „Business-Abend“ ein. „Wer jetzt Mitglieder anwirbt, sichert sich die beste Position und wird reich“, sagt sie. „Es gibt nur noch wenige Startplätze, und heute entscheiden sich schon die Ersten.“ Über das Produkt selbst spricht sie kaum.","options":["Der Gewinn wird mit dem Anwerben neuer Mitglieder und den knappen Startplätzen begründet, während über das Produkt selbst kaum gesprochen wird.","Das Versprechen, reich zu werden, ist so groß, dass es schon für sich genommen übertrieben klingt und eher die Gier als die Vernunft anspricht.","Die Einladung kommt von einer Bekannten, die selbst Mitglieder anwerben will, sodass ihre Begeisterung eher ihr selbst nützt als dir.","Über das Produkt selbst spricht sie kaum, sodass offen bleibt, was dort eigentlich verkauft wird, und dir die Grundlage für ein Urteil fehlt."],"correctIndex":0,"explanation":"Bei Angeboten, die vor allem Reichtum durch Anwerben, Zeitdruck und Knappheit versprechen, wird nicht der Wert einer Sache verkauft, sondern die Sorge, eine einmalige Chance zu verpassen. Das Produkt tritt in den Hintergrund. Künstlich erzeugter Zeitdruck sowie Werbung mit Knappheit und Exklusivität sind typische Warnzeichen für FOMO-Manipulation. Entscheidend ist, woraus der versprochene Gewinn entsteht: Wird er mit dem Rekrutieren neuer Mitglieder statt mit dem Produkt begründet, ist das die FOMO-Mechanik von Multi-Level-Marketing und Schneeballsystemen.","coreRule":"⚡ Wer vor allem die Angst vor dem Verpassen verkauft, verkauft nicht den Wert der Sache.","beleg":"Werkstück B.26 (Anwendung: Multi-Level-Marketing & Schneeballsysteme; Red Flags: FOMO-Manipulation)","status":"entwurf","kurz":"Hier wird nicht das Produkt, sondern die Sorge verkauft, eine einmalige Chance zu verpassen: Der Gewinn kommt vom Anwerben, dazu kommen knappe Plätze und Eile. Gier oder Eigeninteresse sind nur Nebenschauplätze.","prueffrage":"Was müsste eine seriöse Einladung zu einem Verkaufsabend enthalten, das in ihren Worten fehlt?","rueckmeldung":[{"option":1,"text":"Ein sehr großes Versprechen sollte misstrauisch machen, und es spricht Gier an. Warum man es eilig haben soll, erklärt das aber nicht: Das zeigen erst Knappheit, Zeitdruck und die Begründung des Gewinns."},{"option":2,"text":"Dass die Bekannte selbst anwirbt, kann ihre Begeisterung färben. Ein Eigeninteresse macht eine Aussage aber nicht falsch und zeigt nicht den Druck, nichts verpassen zu dürfen. Dafür muss man auf Knappheit und Eile achten."},{"option":3,"text":"Dass das Produkt kaum vorkommt, stimmt und ist ein echtes Warnzeichen. Es erklärt aber nur, warum dir die Urteilsgrundlage fehlt. Dass hier Angst vor dem Verpassen im Spiel ist, zeigen erst Knappheit, Zeitdruck und der Gewinn durchs Anwerben."}],"familie":"mehrheit-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Federal Trade Commission, Consumer Advice: Multi-Level Marketing Businesses and Pyramid Schemes","oeffentlich":true,"url":"https://consumer.ftc.gov/articles/multi-level-marketing-businesses-and-pyramid-schemes","abruf":"2026-10-12"},{"typ":"url","kurz":"Federal Trade Commission (2022): Bringing Dark Patterns to Light. Staff Report, September 2022","oeffentlich":true,"url":"https://www.ftc.gov/system/files/ftc_gov/pdf/P214800%20Dark%20Patterns%20Report%209.14.2022%20-%20FINAL.pdf","seite":"21–22","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"1652da970fa0a454"}},{"id":"qx-b2-041","clusterId":"B","werkstueckRef":"B.27","stufe":1,"question":"Welche Erklärung für Lenas Meinungswechsel ist die sparsamste?","scenario":"Lena fand das Programm einer neuen Partei lange unausgegoren; im Freundeskreis hieß die Partei „Die Spinner“, die Umfragen lagen bei 3 %. Dann springt die Partei auf 15 %. In Lenas Feed erscheinen positive Artikel, und zwei Kollegen, die sie für klug hält, loben das Programm. Lena liest es noch einmal und findet es jetzt „erfrischend anders“. Nach der Wahl, bei der die Partei 25 % erreicht, sagt sie: „Ich habe mir das genau angesehen. Die haben einfach die besten Lösungen.“ Am Programm selbst wurde zwischen den Umfragen und der Wahl nichts geändert.","options":["Mit dem Umfrageplus stieg für sie die wahrgenommene Glaubwürdigkeit der Ideen, obwohl das Programm gleich blieb.","Mit dem Umfrageplus las sie das Programm gründlicher und fand Stärken, die ihr beim ersten Blick entgangen waren.","Mit dem Umfrageplus legte sie das Vorurteil ihres Freundeskreises ab, das ihr den Blick aufs Programm verstellt hatte.","Mit dem Umfrageplus sah sie die Partei öfter im Feed, und die Ideen wirkten auf sie durch Gewöhnung weniger fremd."],"correctIndex":0,"explanation":"Verglichen werden muss, was sich zwischen den beiden Urteilen tatsächlich geändert hat. Das Programm blieb gleich; geändert haben sich nur die Umfragewerte und die Signale aus Lenas Umfeld, also positive Artikel und das Lob zweier geschätzter Kollegen. Die sparsamste Erklärung nimmt deshalb an, dass dieses gewachsene Ansehen ihr Urteil verschoben hat: Popularität dient als Ersatz für Qualität („Wenn so viele das gut finden, muss etwas dran sein“), das ist der Mitläufer-Effekt. Auch Lenas Satz, sie habe sich alles genau angesehen, ändert daran nichts, denn die Ideen selbst sind dieselben geblieben.","coreRule":"⚡ Ändert sich nur die Zahl der Anhänger und nicht die Idee, dann sagt der Meinungswechsel etwas über die Stimmung aus, nicht über die Idee.","beleg":"Werkstück B.27 (Eingangsszene; Kernidee)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Am Programm änderte sich nichts, nur Umfragewerte und Lob aus Lenas Umfeld. Am sparsamsten erklärt das ihren Wechsel: Beliebtheit diente als Ersatz für Qualität. Dass sie „genau hingesehen“ hat, ändert daran nichts, denn die Ideen blieben dieselben.","prueffrage":"Was genau hat sich zwischen Lenas erstem und ihrem zweiten Urteil nachweislich geändert?","rueckmeldung":[{"option":1,"text":"Beim zweiten Lesen kann einem tatsächlich mehr auffallen. Doch dafür müsste man annehmen, Lena habe beim ersten Mal Stärken übersehen, wovon im Szenario nichts steht. Verändert hat sich nur das Ansehen der Partei, nicht der Inhalt des Programms."},{"option":2,"text":"Ein Vorurteil kann den Blick tatsächlich verstellen. Das Szenario sagt aber nicht, dass Lena es teilte: Sie fand das Programm von sich aus unausgegoren. Und warum sollte es gerade durch das Umfrageplus fallen? Dazu bräuchte es zusätzliche Annahmen."},{"option":3,"text":"Häufigeres Sehen kann Ideen vertrauter machen, und im Feed erschienen tatsächlich mehr Artikel. Das Szenario hebt aber vor allem ihren Inhalt hervor, nämlich positive Berichte und das Lob zweier geschätzter Kollegen. Das wachsende Ansehen erklärt den Wechsel sparsamer als bloße Gewöhnung."}],"familie":"mehrheit-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Bandwagon“, „Appeal to the People“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"d8a851c19778a935"}},{"id":"qx-b2-042","clusterId":"B","werkstueckRef":"B.27","stufe":2,"question":"Bei welcher dieser Entscheidungen ist „Mach, was die Mehrheit macht“ eine vertretbare Abkürzung?","options":["Beim Abendessen, weil ein Fehlgriff dort nur 15 Euro und einen mäßigen Abend kostet und du morgen einfach ein anderes Lokal ausprobieren kannst.","Beim Mittel für dein Kind, weil die lange Schlange am Stand zeigt, dass viele Eltern es kaufen und es offenbar bei vielen Kindern gut wirkt.","Bei der Kryptowährung, weil die Leute am Nebentisch nach eigener Aussage schon Gewinne gemacht haben und der Kurs gerade spürbar weiter steigt.","Beim Reisebericht, weil ein Video, das millionenfach geteilt wurde, vor dir schon von sehr vielen Menschen gesehen und für glaubwürdig befunden wurde."],"correctIndex":0,"explanation":"„Das volle Lokal ist wohl das bessere“ funktioniert als schnelle Faustregel, weil sich dahinter viele einzelne Erfahrungen bündeln, ein Fehlgriff hier nur 15 Euro und einen mäßigen Abend kostet und du morgen woanders essen kannst: Die Entscheidung ist umkehrbar und das Risiko gering. Je höher der mögliche Schaden und je schwerer die Entscheidung zurückzunehmen ist, desto weniger darf Popularität die eigene Prüfung von Fakten, Logik und Ethik ersetzen. Beim Mittel für dein Kind steht möglicherweise die Gesundheit auf dem Spiel, und dass viele Eltern es kaufen, sagt wenig über Wirksamkeit und Verträglichkeit. Wer seine Ersparnisse anlegt, weil andere gerade Gewinne machen, kauft nicht, weil der Wert unterbewertet wäre, sondern weil der Preis steigt; das treibt Blasen. Und dass ein Video millionenfach geteilt wurde, ist keine Prüfung, ob die Altstadt wirklich 2000 Jahre alt ist, zumal du es als Tatsache in die Zeitung bringen willst.","coreRule":"⚡ Der Mehrheit zu folgen genügt für den Filmabend, aber nicht für Wahrheitsfragen oder riskante Entscheidungen.","beleg":"Werkstück B.27 (Adaptives Talent; Kipppunkt)","status":"entwurf","scenario":"Du verbringst ein Wochenende in einer fremden Stadt. Fürs Abendessen für etwa 15 Euro schwankst du zwischen einem vollen Lokal und dem fast leeren daneben. Auf dem Markt verkauft ein Stand ein Mittel gegen Reisekrankheit für Kinder, und davor steht eine lange Schlange. Am Nebentisch schwärmen alle von einer Kryptowährung, mit der sie Gewinne gemacht haben, und du überlegst, deine Ersparnisse hineinzustecken. Außerdem willst du für die Zeitung deines Heimatorts einen Reisebericht schreiben und darin als Tatsache bringen, die Altstadt sei 2000 Jahre alt, weil ein millionenfach geteiltes Video das sagt.","kurz":"Beim Abendessen darfst du dich an der Menge orientieren: Viele Erfahrungen stecken im vollen Lokal, ein Fehlgriff kostet wenig und lässt sich morgen korrigieren. Je höher der Schaden und je schwerer rückgängig, desto weniger ersetzt Beliebtheit die eigene Prüfung.","prueffrage":"Was steht bei dieser Entscheidung auf dem Spiel, und lässt sich ein Fehlgriff später noch korrigieren?","rueckmeldung":[{"option":1,"text":"Die lange Schlange zeigt, dass viele das Mittel kaufen, nicht, dass es wirkt oder gut verträglich ist. Weil bei einem Kind möglicherweise die Gesundheit auf dem Spiel steht, sollte hier die eigene Prüfung zählen."},{"option":2,"text":"Gewinne anderer und ein steigender Kurs zeigen nur, dass der Preis gerade steigt, nicht, dass der Wert stimmt. Wer deshalb kauft, treibt womöglich eine Blase mit, und bei Ersparnissen ist der Schaden groß und schwer rückgängig."},{"option":3,"text":"Millionenfaches Teilen zeigt Verbreitung, aber nicht, dass jemand die Aussage geprüft hat. Als Tatsache in der Zeitung trägst du die Verantwortung dafür, dass das Alter der Altstadt wirklich belegt ist."}],"familie":"mehrheit-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „Bandwagon“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"Shiller, R. J. (2014): Speculative Asset Prices (Nobel Prize Lecture). Cowles Foundation Discussion Paper 1936","oeffentlich":true,"url":"https://cowles.yale.edu/sites/default/files/2022-08/d1936.pdf","seite":"2","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"76fd739e31e1816a"}},{"id":"qx-b2-043","clusterId":"B","werkstueckRef":"B.27","stufe":3,"question":"Welche Rückfrage prüft diese Erklärung am besten?","options":["Woher kam das Geld, mit dem so viele Anleger kaufen konnten, und wie stark wuchs die Kreditvergabe in dieser Zeit?","Hat der Kommentator ein eigenes finanzielles Interesse an der Aktie, sodass seine Erklärung gefärbt sein könnte?","Wie treffsicher waren frühere Kursprognosen dieses Kommentators, und wie oft lag er in seinen Erklärungen daneben?","Auf welchen Zeitraum und welchen Startkurs bezieht sich die Verdreifachung genau, und wie wurde sie berechnet?"],"correctIndex":0,"explanation":"Das Nachziehen hinter denen, die gerade Gewinne machen, ist real: Wer sieht, dass andere mit Spekulation verdienen, steigt ein. Das erklärt aber nur, warum Menschen kaufen wollen, nicht, womit sie kaufen. Bei einer einzelnen Aktie kann das Geld aus anderen Anlagen umgeschichtet werden; bei großen Manien sehen die Ökonomen Charles Kindleberger und Robert Aliber den eigentlichen Motor dagegen im Kredit, der in guten Zeiten rasch wächst, und das Mitlaufen ist bei ihnen ein Teil des Booms, nicht seine alleinige Ursache. Wer „der Herdentrieb allein“ behauptet, übersieht deshalb mindestens die Frage der Finanzierung. Die beste Rückfrage sucht diesen fehlenden Faktor. Ein Eigeninteresse des Kommentators ist ein vernünftiger Gedanke, betrifft aber seine Glaubwürdigkeit und sagt nichts über die Ursache des Anstiegs. Seine frühere Treffsicherheit zeigt, wie verlässlich er ist, nicht aber, ob der Herdentrieb hier allein genügt. Wie die Verdreifachung gerechnet wurde, klärt die genannte Zahl, nicht die behauptete Alleinursache.","coreRule":"⚡ Der Herdentrieb heizt Blasen an, aber das Geld dafür kommt aus wachsendem Kredit: Wer eine einzige Ursache behauptet, sollte nach den fehlenden fragen.","beleg":"Werkstück B.27 (Anwendung: Finanzmärkte); Fn. gl-b-kredit (Kindleberger/Aliber 2005, S. 12 und 29)","status":"entwurf","scenario":"Ein Börsenkommentator erklärt den starken Kursanstieg einer Aktie: „Sie hat sich in einem Jahr verdreifacht, weil alle auf den Zug aufgesprungen sind. Der Herdentrieb allein hat diese Blase gemacht.“","kurz":"Mitlaufen erklärt nur, warum Menschen kaufen wollen, nicht, womit sie kaufen. Wer „der Herdentrieb allein“ sagt, übersieht die Finanzierung. Bei großen Manien gilt Kredit als Motor, das Mitlaufen eher als Teil des Booms.","prueffrage":"Welche Auskunft könnte zeigen, dass der Herdentrieb allein den Anstieg nicht erklärt?","rueckmeldung":[{"option":1,"text":"Ein Eigeninteresse wäre ein berechtigter Gedanke, wenn es um die Glaubwürdigkeit des Kommentators geht. Ob der Herdentrieb den Anstieg allein erklärt, beantwortet es aber nicht, denn dafür zählt die Sache selbst und nicht, wer sie behauptet."},{"option":2,"text":"Eine schlechte Trefferquote macht den Kommentator weniger verlässlich, doch das betrifft ihn, nicht diese Erklärung. Auch jemand, der sonst oft danebenliegt, kann hier recht haben, und ein Treffsicherer kann sich irren. Geprüft wird so nicht, ob der Herdentrieb allein genügt."},{"option":3,"text":"Eine genaue Rechnung klärt, ob die Verdreifachung stimmt. Diese Zahl wird aber gar nicht bestritten, sondern ihre behauptete Ursache. Selbst mit sauber geklärter Basis bliebe offen, ob Mitlaufen allein den Anstieg erklärt."}],"familie":"monokausal-erkennen","fertigkeit":"F2","quellen":[{"typ":"literatur","kurz":"Kindleberger, C. P.; Aliber, R. Z. (2005): Manias, Panics, and Crashes: A History of Financial Crises. 5. Aufl., Hoboken: Wiley","oeffentlich":false},{"typ":"url","kurz":"Schularick, M.; Taylor, A. M. (2009/2011): Credit Booms Gone Bust: Monetary Policy, Leverage Cycles and Financial Crises, 1870–2008. NBER Working Paper 15512","oeffentlich":true,"url":"https://www.nber.org/papers/w15512","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"dfa0bb76ce6f1f1f"}},{"id":"qx-b2-044","clusterId":"B","werkstueckRef":"B.27","stufe":4,"question":"Welche Prüffrage hilft dir am besten, die Aussage zu beurteilen, ohne aus ihrer Größe auf ihre Wahrheit zu schließen?","scenario":"Ein Video behauptet etwas Spektakuläres. Darunter steht: „10 Millionen Aufrufe! Hunderttausende sind schon auf der Straße! Wir werden jeden Tag mehr!“ Dein Bekannter sagt: „Bei so vielen Leuten muss doch etwas dran sein.“","options":["Sind die zehn Millionen Aufrufe echt und nicht gekauft, denn erst geprüfte Zahlen sagten, wie viele Menschen die Behauptung teilen?","Wer hat das Video eingestellt und wer verdient an den Aufrufen, denn ein Geschäftsinteresse spräche gegen die Wahrheit der Behauptung?","Wie würde ich die Behauptung beurteilen, wenn nur ich davon wüsste, denn dann zählten allein die Belege, nicht Klickzahlen?","Wie schnell wächst die Zahl der Aufrufe pro Tag, denn ein auffälliges Tempo könnte auf gesteuerte Verbreitung hindeuten?"],"correctIndex":2,"explanation":"Aufrufe, Demonstrationsgrößen und Wachstum sagen etwas darüber aus, wie viele Menschen eine Behauptung teilen, nicht darüber, ob sie stimmt. Das ist die Verwechslung von Popularität mit Richtigkeit. Zudem erzeugt Popularität weitere Popularität: Wer mitläuft, macht die Bewegung größer und scheinbar überzeugender, ohne dass ein einziger Beleg hinzukommt. Prüfen lässt sich die Aussage nur, wenn man die Menge gedanklich ausblendet und fragt, was die Belege allein hergeben. Die anderen Fragen klingen sinnvoll, bleiben aber bei der Menge oder beim Absender: Selbst echte, nicht gekaufte Aufrufe sagen nichts darüber, ob die Behauptung stimmt. Ein Geschäftsinteresse macht eine Aussage nicht falsch, das lässt sich nur an den Belegen prüfen. Und auch ein auffällig steiles Wachstum, selbst wenn es gesteuert wäre, verrät nichts über den Wahrheitsgehalt.","coreRule":"⚡ Eine große Anhängerschaft ist ein Beleg für Beliebtheit, nicht für Wahrheit.","quote":"","quoteLabel":"","beleg":"Werkstück B.27 (Anwendung: Verschwörungsmythen & Kulte; Anti-Denkmuster)","status":"entwurf","kurz":"Aufrufe, Demonstrationsgrößen und Wachstum zeigen nur, wie viele eine Behauptung teilen, nicht, ob sie stimmt. Wer die Menge gedanklich ausblendet und fragt, was die Belege allein hergeben, trennt Beliebtheit von Richtigkeit.","prueffrage":"Welche der Angaben unter dem Video sagt etwas darüber, ob das Behauptete tatsächlich zutrifft?","rueckmeldung":[{"option":0,"text":"Gekaufte Klicks kommen tatsächlich vor, und eine Prüfung der Zahlen ist nicht verkehrt. Aber selbst ganz echte Aufrufe sagen nur, wie viele die Behauptung teilen, nicht, ob sie stimmt. Die Frage bleibt bei der Menge."},{"option":1,"text":"Wer von einer Behauptung profitiert, verdient einen genaueren Blick. Eine Aussage wird dadurch aber nicht falsch: Ein Geschäftsinteresse spricht nicht gegen die Wahrheit, das zeigt sich erst an den Belegen. Die Frage bleibt beim Absender."},{"option":3,"text":"Ein auffällig steiles Wachstum kann auf gesteuerte Verbreitung hindeuten, und das ist gut zu wissen. Über den Wahrheitsgehalt verrät es trotzdem nichts, denn auch gesteuert verbreitete Aussagen können stimmen oder falsch sein. Die Frage bleibt bei der Menge."}],"familie":"mehrheit-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Appeal to the People“, „Bandwagon“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"27b6b32b6ccc0a51"}},{"id":"qx-b2-045","clusterId":"B","werkstueckRef":"B.28","stufe":1,"question":"Welche Erklärung passt am besten zu diesem Preisunterschied, und was spricht gegen den Einwand der Teilnehmerin?","scenario":"Bei einem Experiment bekommt die eine Hälfte einer Gruppe eine Kaffeetasse geschenkt, die andere Hälfte nicht. Wer eine Tasse hat, will sie im Schnitt erst ab einem deutlich höheren Preis verkaufen, als die Übrigen bereit sind, für dieselbe Tasse zu zahlen. Eine Teilnehmerin sagt: „Die Tassen sind ja alle gleich. Dann haben die Besitzer eben genauer geprüft, wie gut sie ist.“","options":["Der Unterschied entsteht erst durch das Besitzen: Wer die Tasse hat, erlebt das Abgeben als Verlust und gewichtet ihn stärker als den Erlös, obwohl die Tassen identisch sind.","Der Unterschied entsteht durch bessere Information: Wer die Tasse hat, kann ihre Qualität in der Hand genauer beurteilen und verlangt deshalb mehr, obwohl die Tassen identisch sind.","Der Unterschied entsteht durch Knappheit: Wer die Tasse hat, hält sie für selten, weil nur die Hälfte der Gruppe eine bekam, und verlangt deshalb mehr, obwohl die Tassen identisch sind.","Der Unterschied entsteht durch Verankerung: Wer die Tasse hat, richtet sich nach dem Ladenpreis, den er für sie vermutet, und verlangt deshalb mehr, obwohl die Tassen identisch sind."],"correctIndex":0,"explanation":"Die Tassen sind identisch. Der einzige Unterschied zwischen den Gruppen ist der Besitz. Wer eine Tasse hat, für den wird sie Teil des Referenzpunkts. Sie herzugeben wird dann als Verlust erlebt, und ein Verlust wiegt meist schwerer als ein gleich hoher Gewinn. Deshalb verlangen die Besitzer mehr, als die anderen zahlen würden (Besitztumseffekt). Der Einwand der Teilnehmerin scheitert daran, dass identische Tassen keinen Qualitätsunterschied bieten, den die Besitzer genauer prüfen könnten. Dasselbe Muster steckt hinter „30 Tage kostenlos testen“: Was man schon hat, gibt man ungern zurück.","coreRule":"⚡ Wenn identische Dinge nur wegen des Besitzes unterschiedlich bewertet werden, steckt oft Verlustaversion dahinter: Was ich habe, wird Teil meines Referenzpunkts, und Hergeben zählt als Verlust.","beleg":"Werkstück B.28 (Analyse: Besitztumseffekt; Anwendung: Marketing)","status":"freigegeben","freigabe":{"datum":"2026-10-15","pruefsumme":"2ae6083e3e480446","vermerk":"Prüfpult (Sturm, erste Charge nach den neuen falschen Optionen)"},"kurz":"Der Preisunterschied entsteht durch den Besitz selbst: Wer die Tasse hat, erlebt das Abgeben als Verlust, und der wiegt meist schwerer als ein gleich hoher Erlös. Eine genauere Prüfung erklärt nichts, denn bei identischen Tassen gibt es nichts zu entdecken.","prueffrage":"Welche Information über die Tasse könnten die Besitzer haben, die den anderen fehlt, wenn alle Tassen gleich sind?","rueckmeldung":[{"option":1,"text":"Genaueres Prüfen lohnt sich, wenn Gegenstände verschieden sind. Hier sind die Tassen aber identisch, also gibt es in der Hand nichts zu entdecken, das den höheren Preis begründen könnte."},{"option":2,"text":"Knappheit kann Preise steigern. Hier sehen aber auch die Übrigen, dass nur die Hälfte eine Tasse bekam, sie träfe also beide Gruppen und erklärt nicht, warum nur die Besitzer mehr verlangen."},{"option":3,"text":"Ein vermuteter Ladenpreis kann Preisvorstellungen prägen. Er stünde aber auch den Übrigen als Anker zur Verfügung, würde also beide Gruppen betreffen und nicht den Unterschied zwischen ihnen erklären."}],"familie":"verlust-und-gewinn-abwaegen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Kahneman, D.; Knetsch, J. L.; Thaler, R. H. (1991): Anomalies: The Endowment Effect, Loss Aversion, and Status Quo Bias. Journal of Economic Perspectives 5(1), 193–206","oeffentlich":true,"doi":"10.1257/jep.5.1.193","url":"https://www.aeaweb.org/articles?id=10.1257/jep.5.1.193","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kahneman, D.; Knetsch, J. L.; Thaler, R. H. (1990): Experimental Tests of the Endowment Effect and the Coase Theorem. Journal of Political Economy 98(6), 1325–1348","oeffentlich":false,"doi":"10.1086/261737"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"2ae6083e3e480446"}},{"id":"qx-b2-046","clusterId":"B","werkstueckRef":"B.28","stufe":3,"question":"Ein Artikel behauptet: „Wissenschaftlich bewiesen: Verluste wiegen genau doppelt so schwer wie Gewinne.“ Zur Prüfung liest du die zugrunde liegenden Messungen nach. Die klassische Studie kam auf einen Faktor von 2,25. Eine große Zusammenstellung vieler späterer Arbeiten ergab im Mittel etwa 1,96. Betrachtet man nur Entscheidungen zwischen riskanten Lotterien, liegt der Wert bei etwa 1,31. Was folgt daraus für die Behauptung?","options":["Der Artikel überzeichnet: Der Wert ist eine Faustregel, die je nach Methode deutlich schwankt, und keine feste Konstante.","Der Artikel liegt richtig: Der Mittelwert vieler Arbeiten von etwa 1,96 entspricht praktisch dem Faktor 2 und stützt die Aussage.","Der Artikel ist fragwürdig: Weil die Werte so weit auseinanderliegen, bleibt offen, ob Verluste überhaupt schwerer wiegen.","Der Artikel liegt im Kern richtig: Der Lotteriewert betrifft einen Sonderfall, ohne ihn liegen die Messungen nahe beim Faktor 2."],"correctIndex":0,"explanation":"Die Messwerte streuen je nach Methode erheblich: 2,25 in der klassischen Studie, etwa 1,96 im Mittel vieler späterer Arbeiten, nur etwa 1,31 bei riskanten Lotterien. Eine Größe, die so stark von der Messmethode abhängt, ist keine feste Konstante, sondern eine Faustregel. „Genau doppelt“ und „wissenschaftlich bewiesen“ verleihen der Zahl eine Präzision, die die Daten nicht hergeben. Die Gegenrichtung ist ebenso ein Fehlschluss: Schwankende Schätzwerte bedeuten nicht, dass der Effekt verschwindet. Die genannten Messungen liegen durchgehend über 1; wie stark der Effekt ausfällt, hängt von Methode und Kontext ab. Gal und Rucker (2018) bestreiten sogar, dass Verluste im Allgemeinen stärker wirken als gleich hohe Gewinne. Das „doppelt so stark“ ist also eine gerundete Faustregel, kein Naturgesetz. Der Mittelwert von etwa 1,96 liegt zwar in der Nähe von 2, macht aber „genau“ und „bewiesen“ bei einer Spanne von 1,31 bis 2,25 nicht wahr.","coreRule":"⚡ Eine Zahl, die je nach Messmethode stark schwankt, ist eine Faustregel, keine Konstante.","beleg":"Werkstück B.28 (Kernidee; Analyse); Fn. gl-b-verlust (Tversky/Kahneman 1992, S. 311; Brown u. a. 2024, JEL 62(2); Walasek u. a. 2024, JEP 103; Gal/Rucker 2018)","status":"entwurf","scenario":"","kurz":"Eine Größe, die je nach Messmethode zwischen 1,31 und 2,25 liegt, ist eine Faustregel und keine feste Konstante. „Genau doppelt“ und „bewiesen“ täuschen eine Präzision vor, die die Daten nicht hergeben.","prueffrage":"Wie weit liegen die drei genannten Werte auseinander, und welcher davon ist genau 2?","rueckmeldung":[{"option":1,"text":"Der Mittelwert von 1,96 liegt tatsächlich nahe bei 2. Ein Durchschnitt verdeckt aber die Spanne von 1,31 bis 2,25, und bei dieser Streuung sind „genau doppelt“ und „bewiesen“ zu stark."},{"option":2,"text":"Die Werte streuen tatsächlich stark. Schwankende Schätzungen heißen aber nicht, dass der Effekt verschwindet: Alle genannten Messungen liegen über 1. Offen ist nur, wie groß er ist."},{"option":3,"text":"Ohne den Lotteriewert lägen die übrigen Werte nahe bei 2. Eine unbequeme Messung auszuklammern, ist aber selektiv, und auch dann bliebe „genau“ und „bewiesen“ eine Präzision, die die Daten nicht hergeben."}],"familie":"zahl-zur-quelle","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Brown, A. L.; Imai, T.; Vieider, F. M.; Camerer, C. F. (2024): Meta-Analysis of Empirical Estimates of Loss Aversion (Preprint MetaArXiv; Zeitschriftenfassung JEL 62(2), 485–516)","oeffentlich":true,"doi":"10.31222/osf.io/hnefr","abruf":"2026-10-12"},{"typ":"doi","kurz":"Walasek, L.; Mullett, T. L.; Stewart, N. (2024): A meta-analysis of loss aversion in risky contexts. Journal of Economic Psychology 103, 102740","oeffentlich":false,"doi":"10.1016/j.joep.2024.102740"},{"typ":"doi","kurz":"Gal, D.; Rucker, D. D. (2018): The Loss of Loss Aversion: Will It Loom Larger Than Its Gain? Journal of Consumer Psychology 28(3), 497–516","oeffentlich":false,"doi":"10.1002/jcpy.1047"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"966bfb6f4d036d6c"}},{"id":"qx-b2-047","clusterId":"B","werkstueckRef":"B.28","stufe":4,"question":"Welche Erklärung ihres Verhaltens ist am sparsamsten, wenn du nur ihre Lage betrachtest?","scenario":"Eine Bekannte ist seit Jahren in einer Gemeinschaft, die ihr viel bedeutet: Dort sind ihre engsten Freunde, ihre Rolle und das Gefühl, etwas Besonderes zu wissen. Sie hat investiert und gespendet. Nun hat ihr jemand die zentralen Behauptungen der Gruppe überzeugend widerlegt. Trotzdem sagt sie: „Du magst ja recht haben, aber ich bleibe.“","options":["Sie gewichtet den erwarteten Verlust durch einen Austritt stärker als den Gewinn, die Wahrheit zu erkennen.","Sie will das Geld und die Spenden, die sie in die Gruppe gesteckt hat, nicht umsonst gegeben haben.","Sie bleibt vor allem aus Gewohnheit, weil ihr ein Wechsel nach so vielen Jahren zu mühsam erscheint.","Sie scheut das Eingeständnis vor ihren Freunden, sich geirrt zu haben, und bleibt, um es zu vermeiden."],"correctIndex":0,"explanation":"Wer aus einer Gemeinschaft austritt, verliert nicht nur eine Überzeugung, sondern auch Freunde, Identität, das Gefühl besonderen Wissens und die investierte Zeit und das Geld. Menschen gewichten Verluste meist stärker als gleich große Gewinne (Verlustaversion); wie stark, hängt von Methode und Lage ab. Deshalb kann der erwartete Verlust schwerer wiegen als der Gewinn, die Wahrheit zu erkennen, und diese Erklärung kommt mit ihrer geschilderten Lage aus. Die Verlust-Erklärung beschreibt zudem einen Mechanismus, kein Urteil über die Intelligenz der Bekannten.","coreRule":"⚡ Wer fragt, warum jemand nicht geht, sollte zuerst fragen, was der Austritt ihn kosten würde, nicht nur, ob er recht hat.","beleg":"Werkstück B.28 (Anwendung: Verschwörungsmythen & Kulte)","status":"entwurf","kurz":"Wer austritt, verliert Freunde, Rolle, das Gefühl besonderen Wissens und das Investierte, und Verluste wiegen meist schwerer als gleich große Gewinne. Diese Lage reicht als Erklärung. Man muss ihr keine Gewohnheit oder Scham unterstellen.","prueffrage":"Was hängt für sie außer der Frage, ob die Behauptungen stimmen, noch an dieser Gemeinschaft?","rueckmeldung":[{"option":1,"text":"Das verlorene Geld und die Spenden gehören tatsächlich zum Verlust, den ein Austritt bedeutet. Es ist aber nur ein Posten neben Freunden, Rolle und dem Gefühl, etwas Besonderes zu wissen, und erklärt ihr Bleiben allein nicht."},{"option":2,"text":"Bequemlichkeit klingt plausibel, steht aber nirgends in ihrer Lage. Dort geht es um Freunde, Identität und Investiertes, also um echte Verluste und nicht um bloße Mühe. Die Erklärung fügt etwas hinzu, das nicht nötig ist."},{"option":3,"text":"Ein Irrtumseingeständnis vor den Freunden wäre unangenehm und zählt zum sozialen Verlust. Sie räumt aber selbst ein, dass der andere recht haben mag, scheut das Eingeständnis also nicht. Zudem erfasst der Gedanke nur einen Teil dessen, was sie beim Austritt verlöre."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Kahneman, D.; Knetsch, J. L.; Thaler, R. H. (1991): Anomalies: The Endowment Effect, Loss Aversion, and Status Quo Bias. Journal of Economic Perspectives 5(1), 193–206","oeffentlich":true,"doi":"10.1257/jep.5.1.193","url":"https://www.aeaweb.org/articles?id=10.1257/jep.5.1.193","abruf":"2026-10-12"},{"typ":"doi","kurz":"Brown, A. L.; Imai, T.; Vieider, F. M.; Camerer, C. F. (2024): Meta-Analysis of Empirical Estimates of Loss Aversion (Preprint MetaArXiv)","oeffentlich":true,"doi":"10.31222/osf.io/hnefr","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"e62501f598f04bbc"}},{"id":"qx-b2-048","clusterId":"B","werkstueckRef":"B.28","stufe":2,"question":"Welche Frage prüft am besten, ob du das Abo behalten solltest?","scenario":"Seit Jahren läuft von deinem Konto ein Abo ab, das du kaum noch nutzt. Eine Freundin sagt: „Kündige es doch einfach.“ Du antwortest: „Aber ich habe schon so viel dafür bezahlt, das kann ich jetzt nicht wegwerfen.“","options":["Hatte ich beim Abschluss vor Jahren gute Gründe, und war der Vertrag damals rückblickend eine vernünftige Entscheidung?","Wenn ich das Abo heute nicht hätte, würde ich es jetzt neu abschließen und dafür diesen Aufwand an Geld und Zeit betreiben?","Was verliere ich, wenn ich jetzt kündige, verglichen mit dem, was ich gewinne, wenn das Abo einfach weiterläuft wie bisher?","Wie viel habe ich bisher insgesamt bezahlt, und wie lange müsste ich das Abo noch nutzen, damit sich diese Ausgaben rechnen?"],"correctIndex":1,"explanation":"Eine gute Entscheidung schaut nach vorn: Was bringt mir das Abo ab jetzt, und was kostet es mich ab jetzt? Am klarsten wird das, wenn man sich vorstellt, man besäße es nicht, und fragt, ob man heute Geld und Zeit dafür aufwenden würde. Das bereits Eingezahlte ist nicht mehr zurückzuholen, egal ob du kündigst oder nicht. Wer darauf schaut, wirft gutes Geld schlechtem hinterher (versunkene Kosten). Die Abwägung „Verlust bei Kündigung gegen Gewinn beim Weiterlaufen“ bleibt am bestehenden Abo als Referenzpunkt hängen, sodass Kündigen als Verlust erscheint.","coreRule":"⚡ Frag nicht, was du schon investiert hast, sondern ob du heute neu einsteigen würdest.","quote":"würde ich mein Geld, meine Zeit oder meinen Verstand heute dafür aufwenden, um exakt hier einzusteigen?","quoteLabel":"Prüffrage für festgefahrene Entscheidungen:","beleg":"Werkstück B.28 (Anti-Denkmuster: Clean-Slate-Test; Werkbank-Frage)","status":"entwurf","kurz":"Der Gedankengang trägt, weil er nach vorn schaut: Würdest du das Abo heute neu abschließen? Bereits Gezahltes ist weg, egal ob du kündigst oder nicht; wer es mitrechnet, wirft gutes Geld schlechtem hinterher.","prueffrage":"Welcher Teil der Kosten hängt davon ab, ob du heute kündigst oder behältst, und welcher steht ohnehin fest?","rueckmeldung":[{"option":0,"text":"Ob der Vertrag damals vernünftig war, ist verständlicherweise ein naheliegender Gedanke. Er sagt aber nichts darüber, was das Abo dir ab jetzt bringt und kostet, und genau das entscheidet, ob du es behalten solltest."},{"option":2,"text":"Kosten und Nutzen abzuwägen ist grundsätzlich der richtige Ansatz. Hier gilt das bestehende Abo aber als Normalzustand, sodass Kündigen automatisch wie ein Verlust aussieht und der Vergleich schon in eine Richtung kippt."},{"option":3,"text":"Die bisherige Summe zu zählen, fühlt sich wie ordentliches Rechnen an. Sie ist aber nicht mehr zurückzuholen, ob du kündigst oder nicht, und taugt deshalb nicht als Maßstab für die Zukunft: Was zählt, sind künftiger Nutzen und künftige Kosten."}],"familie":"versunkene-kosten","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Watzek, J.; Brosnan, S. F. (2020): Capuchin and rhesus monkeys show sunk cost effects in a psychomotor task. Scientific Reports 10, 20396","oeffentlich":true,"doi":"10.1038/s41598-020-77301-w","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7683735/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost. Organizational Behavior and Human Decision Processes 35(1), 124–140","oeffentlich":false,"doi":"10.1016/0749-5978(85)90049-4"},{"typ":"doi","kurz":"Kahneman, D.; Knetsch, J. L.; Thaler, R. H. (1991): Anomalies: The Endowment Effect, Loss Aversion, and Status Quo Bias. Journal of Economic Perspectives 5(1), 193–206","oeffentlich":true,"doi":"10.1257/jep.5.1.193","url":"https://www.aeaweb.org/articles?id=10.1257/jep.5.1.193","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"42c3cdfae0fcc5c6"}},{"id":"qx-b2-049","clusterId":"B","werkstueckRef":"B.29","stufe":2,"question":"Was ist an Lenas Schlussfolgerung fehlerhaft?","options":["Sie schließt aus dem Nicht-Finden auf das Nicht-Vorhandensein, obwohl Verzerrungen meist unbewusst ablaufen und sich beim Nach-innen-Schauen nicht zeigen.","Sie hat sich nur kurz befragt und zu früh aufgehört, obwohl eine längere und gründlichere Selbstprüfung ihre Voreingenommenheit wohl ans Licht gebracht hätte.","Sie prüft sich mit Wissen über Denkfehler, das sie gerade erst erwirbt, obwohl man eigene Verzerrungen erst mit mehr Übung zuverlässig an sich selbst erkennt.","Sie prüft nur ihre Motive und nicht ihre Sachargumente, obwohl auch eine gut gemeinte Position inhaltlich falsch sein kann und erst geprüft werden müsste."],"correctIndex":0,"explanation":"Lena beurteilt sich über ihre Gedanken und Absichten, den Kollegen aber über sein sichtbares Verhalten. In ihren Gedanken findet sie fast immer gute Absichten. Die meisten Verzerrungen laufen jedoch unbewusst ab und sind durch einfaches Nach-innen-Schauen grundsätzlich nicht auffindbar. Aus „ich finde nichts“ folgt deshalb nicht „da ist nichts“. Zuverlässiger ist ein Blick von außen: ihr eigenes Verhalten prüfen (Welche Gegenargumente ignoriere ich? Welche Quellen nutze ich?) oder jemanden bitten, die eigene Position auseinanderzunehmen.","coreRule":"⚡ Wer nur in sich hineinschaut, findet gute Absichten und übersieht die Verzerrung.","beleg":"Werkstück B.29 (Analyse: Der Introspektions-Trugschluss)","status":"entwurf","scenario":"Lena arbeitet sich durch eine Liste typischer Denkfehler. Bei ihrem Kollegen erkennt sie sofort, dass er nur Studien zitiert, die seine Meinung stützen. Danach prüft sie sich selbst: Sie geht in Gedanken durch, was sie bei ihrer eigenen Position antreibt, findet dort nur den Wunsch, die Wahrheit herauszufinden, und stellt fest: „Bei mir ist keine Voreingenommenheit im Spiel.“","kurz":"Wer nur nach innen schaut, findet fast immer gute Absichten, aber unbewusste Verzerrungen zeigen sich dort meist nicht. Aus „ich finde nichts“ folgt darum nicht „da ist nichts“; zuverlässiger ist der Blick auf das eigene Verhalten.","prueffrage":"Woran würde man bei Lena und bei ihrem Kollegen jeweils erkennen, ob Voreingenommenheit im Spiel ist?","rueckmeldung":[{"option":1,"text":"Eine kurze Befragung wirkt oberflächlich, und mehr Gründlichkeit klingt nach der naheliegenden Abhilfe. Die meisten Verzerrungen bleiben beim Nach-innen-Schauen aber auch bei langem Grübeln verborgen, die Methode selbst trägt nicht."},{"option":2,"text":"Anfänger überschätzen sich oft, deshalb klingt „mehr Übung“ plausibel. Lena erkennt den Fehler beim Kollegen aber sofort, ihr Wissen reicht also. Auch mit Übung bleibt Nach-innen-Schauen ein unzuverlässiger Weg zu unbewussten Verzerrungen."},{"option":3,"text":"Auch eine gut gemeinte Position kann inhaltlich falsch sein, und Sachargumente zu prüfen ist sinnvoll. Das ist aber nicht der Fehler in Lenas Schluss: Sie folgert aus ihrer Motivprüfung, sie sei unvoreingenommen, obwohl sich Verzerrungen dort meist nicht zeigen."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Pronin, E. (2007): Perception and misperception of bias in human judgment. Trends in Cognitive Sciences 11(1), 37–43 (Zusammenfassung frei auf PubMed)","oeffentlich":true,"doi":"10.1016/j.tics.2006.11.001","url":"https://pubmed.ncbi.nlm.nih.gov/17129749/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Pronin, E.; Kugler, M. B. (2007): Valuing thoughts, ignoring behavior: The introspection illusion as a source of the bias blind spot. Journal of Experimental Social Psychology 43(4), 565–578","oeffentlich":false,"doi":"10.1016/j.jesp.2006.05.011"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"8c699e8b4b0523c8"}},{"id":"qx-b2-050","clusterId":"B","werkstueckRef":"B.29","stufe":3,"question":"Was ist an Jonas' Schlussfolgerung am problematischsten?","options":["Er folgert aus seinem Wissen über Denkfehler, gegen sie immun zu sein, obwohl laut Befunden auch höhere kognitive Fähigkeit den blinden Fleck nicht verkleinert.","Er beruft sich auf sein Studium, obwohl ein Abschluss in einer Diskussion über einen Zeitungsartikel kein Sachargument ist und vom eigentlichen Inhalt ablenkt.","Er verlässt sich auf sein Wissen aus dem Studium, obwohl man Denkfehler erst nach langer Übung im Alltag sicher genug erkennt, um selbst vor ihnen geschützt zu sein.","Er urteilt vorschnell über seinen Kollegen, obwohl er nicht weiß, was hinter dessen Denken steckt, und dessen vermeintliche Fehler deshalb falsch deuten könnte."],"correctIndex":0,"explanation":"Die meisten Verzerrungen wirken unbewusst. Wer nach innen schaut, findet meist gute Absichten und schließt daraus, dass keine Voreingenommenheit im Spiel ist. Auch Klugheit schützt nicht: In einer Studie von West, Meserve und Stanovich (2012) mit Studierenden verkleinerten weder höhere kognitive Fähigkeit noch einschlägige Denkstile den blinden Fleck, wenn überhaupt ging höhere Fähigkeit mit einem etwas größeren einher. Eine mögliche Erklärung: Klügere können ihre voreingenommenen Schlüsse geschickter rational begründen. Daraus folgt für Jonas: Sein Wissen macht ihn vor allem besser darin, Fehler bei anderen zu entdecken, nicht bei sich selbst. Sinnvoller wäre ein externer Check, etwa jemanden zu bitten, die eigene Position gezielt zu zerlegen.","coreRule":"⚡ Wissen über Denkfehler und hohe Intelligenz schützen nicht vor dem eigenen blinden Fleck; prüfe dich von außen, nicht nur durch Nach-innen-Schauen.","beleg":"Werkstück B.29 (Analyse: Intelligenz schützt nicht); Fn. gl-b-blindspot (West/Meserve/Stanovich 2012, JPSP 103(3), S. 511, 515)","status":"entwurf","scenario":"In einer Diskussion über einen Zeitungsartikel sagt Jonas: „Ich habe Statistik und Logik studiert und kenne die gängigen Denkfehler in- und auswendig. Von denen lasse ich mich nicht mehr täuschen. Bei meinem Kollegen erkenne ich sie sofort, bei mir selbst ist das kein Thema.“","kurz":"Wissen über Denkfehler macht nicht immun: Auch Kluge haben einen blinden Fleck, oft sogar einen etwas größeren. Der Fehler liegt im Schluss von „ich kenne sie“ auf „sie betreffen mich nicht“, denn Wissen hilft vor allem beim Erkennen fremder Fehler.","prueffrage":"Worauf stützt Jonas seine Aussage, bei ihm selbst seien Denkfehler kein Thema?","rueckmeldung":[{"option":1,"text":"Sein Studium führt Jonas nur als Grund an, warum er sich für gefeit hält, nicht als Argument zum Artikel. Daran, dass ein Abschluss in der Sache nichts belegt, stimmt zwar etwas. Der Denkfehler liegt aber im Schluss von Wissen auf eigene Immunität."},{"option":2,"text":"Dass Übung im Alltag sicher schützt, klingt plausibel, ist aber nicht belegt: Weder höhere Fähigkeit noch einschlägige Denkstile verkleinerten den blinden Fleck. Mehr Übung im Erkennen löst das Problem nicht, ein externer Check eher."},{"option":3,"text":"Ein Urteil über andere ohne Kenntnis ihrer Gründe kann tatsächlich vorschnell sein. Im Szenario geht es aber um Jonas' Blick auf sich selbst: Er hält sich für unbeeinflusst, und genau das ist die schwache Stelle, nicht seine Sicht auf den Kollegen."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"West, R. F.; Meserve, R. J.; Stanovich, K. E. (2012): Cognitive Sophistication Does Not Attenuate the Bias Blind Spot. Journal of Personality and Social Psychology 103(3), 506–519 (Zusammenfassung frei auf PubMed)","oeffentlich":true,"doi":"10.1037/a0028857","url":"https://pubmed.ncbi.nlm.nih.gov/22663351/","abruf":"2026-10-12"},{"typ":"url","kurz":"Pronin, E. (2007): Perception and misperception of bias in human judgment. Trends in Cognitive Sciences 11(1), 37–43 (Zusammenfassung frei auf PubMed)","oeffentlich":true,"doi":"10.1016/j.tics.2006.11.001","url":"https://pubmed.ncbi.nlm.nih.gov/17129749/","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"3950386aada92d83"}},{"id":"qx-b2-051","clusterId":"B","werkstueckRef":"B.29","stufe":4,"question":"Was solltest du als Nächstes tun, um herauszufinden, ob du selbst voreingenommen bist?","scenario":"In einer hitzigen Diskussion über Ernährung bist du überzeugt, der Einzige am Tisch zu sein, der objektiv urteilt. Du hast viel über Denkfehler gelesen und erkennst bei deinem Gegenüber sofort Bestätigungsfehler und selektive Quellenwahl.","options":["Du bittest eine vertraute Person mit anderer Meinung, dein Argument nach Kräften auseinanderzunehmen, und hörst zunächst nur zu.","Du prüfst genau, ob die Studien deines Gegenübers methodisch sauber sind und seine Schlüsse daraus tragen.","Du nimmst dir einen Tag Abstand und gehst deine Argumente danach in Ruhe allein noch einmal Punkt für Punkt durch.","Du suchst weitere hochwertige Studien zu deinem Standpunkt, damit deine Position auf einer breiteren Belegbasis steht."],"correctIndex":0,"explanation":"Die meisten Verzerrungen wirken unbewusst. Von innen suchst du mit demselben Gehirn, das den Fehler macht: Findest du keine Voreingenommenheit, heißt das nicht, dass keine da ist. Klüger zu sein schützt kaum davor. In einer Studie ging höhere kognitive Fähigkeit sogar eher mit einem größeren blinden Fleck einher, und kluge Menschen können voreingenommene Schlüsse oft geschickter rechtfertigen. Was von innen unsichtbar bleibt, kann ein Blick von außen sichtbar machen: Jemand, der anderer Meinung ist und dein Argument ernsthaft angreift, findet Lücken, die du selbst nicht siehst. Dass du dann zunächst nur zuhörst, verhindert, dass du die Kritik sofort wegerklärst. Die Studien des Gegenübers zu prüfen ist sinnvoll, sagt aber etwas über seine Quellen und nichts über deine eigene Verzerrung. Abstand und Nachdenken allein helfen gegen Hitze, nicht gegen einen blinden Fleck, den dasselbe Denken erzeugt. Und weitere Belege für den eigenen Standpunkt zu sammeln bestätigt ihn nur, statt ihn zu testen.","coreRule":"⚡ Was du von innen nicht siehst, zeigt dir nur ein Blick von außen.","beleg":"Werkstück B.29 (Anti-Denkmuster: Die wirksamste Taktik; Anwendung: Der intellektuelle Skeptiker)","status":"entwurf","kurz":"Voreingenommenheit wirkt meist unbemerkt, und von innen suchst du mit demselben Denken, das den Fehler macht. Erst jemand mit anderer Sicht, den du zunächst nur anhörst, kann Lücken zeigen, die du selbst nicht siehst.","prueffrage":"Wer hat dein eigenes Argument in dieser Diskussion bisher überhaupt auf Schwächen geprüft?","rueckmeldung":[{"option":1,"text":"Die Studien des Gegenübers zu prüfen ist sinnvoll, sagt aber nur etwas über seine Quellen. Ob du selbst verzerrt urteilst, bleibt dabei unberührt, denn die Prüfung richtet sich nach außen."},{"option":2,"text":"Ein Tag Abstand kühlt die Hitze der Diskussion ab. Dasselbe Denken, das einen blinden Fleck erzeugt, geht deine Argumente aber erneut durch und übersieht ihn deshalb sehr wahrscheinlich wieder."},{"option":3,"text":"Weitere gute Studien machen deine Position vielleicht breiter belegt, aber sie testen sie nicht. Wer nur Belege für den eigenen Standpunkt sammelt, bestätigt ihn und macht genau das, was du beim anderen kritisierst."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"West, R. F.; Meserve, R. J.; Stanovich, K. E. (2012): Cognitive Sophistication Does Not Attenuate the Bias Blind Spot. Journal of Personality and Social Psychology 103(3), 506–519 (Zusammenfassung frei auf PubMed)","oeffentlich":true,"doi":"10.1037/a0028857","url":"https://pubmed.ncbi.nlm.nih.gov/22663351/","abruf":"2026-10-12"},{"typ":"url","kurz":"Pronin, E. (2007): Perception and misperception of bias in human judgment. Trends in Cognitive Sciences 11(1), 37–43 (Zusammenfassung frei auf PubMed)","oeffentlich":true,"doi":"10.1016/j.tics.2006.11.001","url":"https://pubmed.ncbi.nlm.nih.gov/17129749/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"f8ec7215b3ef1c10"}},{"id":"qx-b2-052","clusterId":"B","werkstueckRef":"B.29","stufe":1,"question":"Wie lässt sich am besten erklären, was in dieser Situation passiert?","options":["Lena kennt kaum Gegenpositionen, weil sie fast nur passende Artikel gesammelt hat, und hält ihre Sicht deshalb für vernünftig (einseitige Informationslage).","Lena nennt Tom „komplett voreingenommen“ und greift damit seine Person an, statt sich mit seinen Gründen zu befassen (Ad-hominem-Argument).","Lena hält sich für objektiver als Tom, weil sie in sich hineinhorcht und dort nur gute Absichten findet (blinder Fleck für eigene Verzerrungen).","Lena erklärt Toms Auswahl mit seinem Charakter, statt zu bedenken, dass auch Umstände sie prägen können (fundamentaler Attributionsfehler)."],"correctIndex":2,"explanation":"Lena misst Tom an seinem Verhalten, sich selbst aber an ihren Absichten: Sie horcht in sich hinein, findet dort nur den Wunsch nach Wahrheit und hält sich deshalb für objektiver. Viele Verzerrungen wirken jedoch unbewusst und zeigen sich beim Nach-innen-Schauen nicht; aus „nichts gefunden“ folgt nicht „nichts da“. Ihr eigener Schreibtisch zeigt dasselbe Muster, das sie Tom vorwirft. Ein Ankereffekt passt nicht, denn von einem ersten Artikel, an dem sie alles misst, ist keine Rede, sie beruft sich auf ihre Innenschau. Für einen falschen Konsens gibt es keinen Hinweis, denn sie spricht nur über Tom und sich selbst, nicht über eine Mehrheit der Kollegen. Ein Autoritätsargument liegt nicht vor, denn sie verweist auf keine Fachleute, sondern verlässt sich auf ihr eigenes Urteil.","coreRule":"⚡ Was du bei anderen sofort siehst, übersiehst du bei dir selbst am leichtesten.","beleg":"Werkstück B.29 (Kernidee; Eingangsszene; Introspektions-Trugschluss)","status":"entwurf","scenario":"Lena erklärt in einer hitzigen Diskussion: „Mein Kollege Tom sieht nur die Quellen, die zu seiner Meinung passen, und ignoriert alles andere. Der ist komplett voreingenommen. Ich dagegen suche einfach die Wahrheit.“ Wenn man sich ihren Schreibtisch anschaut, stellt man fest: Auch sie hat fast nur Artikel gesammelt, die ihre eigene Position stützen. Auf Nachfrage sagt sie: „Ich habe nachgedacht und bei mir keine Voreingenommenheit gefunden.“","kurz":"Lena misst Tom an seinem Verhalten, sich selbst aber an ihren Absichten. Beim Nach-innen-Schauen zeigen sich viele Verzerrungen nicht, denn aus „nichts gefunden“ folgt nicht „nichts da“, und ihr Schreibtisch zeigt dasselbe Muster wie bei Tom.","prueffrage":"Was liegt auf Lenas Schreibtisch, und wie passt das zu ihrem Urteil über sich selbst?","rueckmeldung":[{"option":0,"text":"Die einseitige Sammlung am Schreibtisch ist tatsächlich auffällig. Sie erklärt aber nicht, warum Lena sich für objektiv hält: Sie beruft sich auf ihre Innenschau, und dabei bleiben viele Verzerrungen unbemerkt."},{"option":1,"text":"„Komplett voreingenommen“ ist tatsächlich eine Abwertung von Tom als Person. Hier geht es aber um Lenas Selbstbild: Sie prüft sich nur von innen und kommt zu einem anderen Ergebnis als bei Tom, den sie am Verhalten misst."},{"option":3,"text":"Lena erklärt Toms Verhalten tatsächlich mit seiner Haltung und sieht keine Umstände. Der Kern liegt aber bei ihr selbst: Sie misst sich an ihren Absichten und Tom an seinem Verhalten, und ihre Innenschau übersieht, was unbewusst wirkt."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Pronin, E.; Kugler, M. B. (2007): Valuing thoughts, ignoring behavior: The introspection illusion as a source of the bias blind spot. Journal of Experimental Social Psychology 43(4), 565–578","oeffentlich":false,"doi":"10.1016/j.jesp.2006.05.011"},{"typ":"url","kurz":"Pronin, E. (2007): Perception and misperception of bias in human judgment. Trends in Cognitive Sciences 11(1), 37–43 (Zusammenfassung frei auf PubMed)","oeffentlich":true,"doi":"10.1016/j.tics.2006.11.001","url":"https://pubmed.ncbi.nlm.nih.gov/17129749/","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"99c9c444e91528e6"}},{"id":"qx-b2-053","clusterId":"B","werkstueckRef":"B.30","stufe":1,"question":"Warum ist Rot im nächsten Spiel nicht wahrscheinlicher als im ersten Spiel des Abends?","scenario":"Ein Freund erzählt dir: „Im Kasino ist die Roulettekugel gestern zwanzigmal hintereinander auf Schwarz gefallen. Ich setze jetzt alles auf Rot, nach so einer Serie muss Rot einfach kommen.“ Der Tisch ist unauffällig und funktioniert einwandfrei.","options":["Der Tisch hat eine Neigung: Wer zwanzigmal Schwarz erlebt, hat es vermutlich mit einem ungleichen Tisch zu tun, der Schwarz bevorzugt.","Die Serie hat eine Eigendynamik: Eine Glückssträhne für Schwarz hält erfahrungsgemäß an, deshalb steigt die Chance auf Rot nicht.","Der Ausgleich braucht Zeit: Das Gesetz der großen Zahlen gleicht die Serie erst über sehr viele Spiele aus, nicht schon im nächsten Spiel.","Die Kugel hat kein Gedächtnis: Bei unabhängigen Zufallsereignissen ist die Chance in jedem Spiel dieselbe, was zuvor auch fiel."],"correctIndex":3,"explanation":"Jedes Spiel ist ein neuer, unabhängiger Wurf. Die Kugel weiß nicht, was vorher gefallen ist, also bleibt die Chance auf Rot unverändert. Auch das Gesetz der großen Zahlen gleicht nichts aus, es verdünnt frühe Abweichungen nur: Über Tausende Spiele fällt eine frühe Serie immer weniger ins Gewicht, ohne dass der Zufall etwas nachholen müsste. Wer nach einer Serie auf die Gegenseite setzt, begeht den Spielerfehlschluss. Die Frage, die ihn entlarvt: Weiß das Ding, das hier „würfelt“, was vorher passiert ist? Wenn nicht, ist der nächste Wurf ein erster Wurf. Ein ungleicher Tisch klingt nach einer natürlichen Erklärung, scheitert aber daran, dass der Tisch laut Szenario einwandfrei funktioniert. Eine Glückssträhne mit Eigendynamik gibt es bei unabhängigen Würfen nicht, die Kugel „läuft“ nicht. Und einen Ausgleich, auch einen langsamen, gibt es nicht: Das Gesetz der großen Zahlen verdünnt die Serie nur.","coreRule":"⚡ Zufall gleicht nichts aus: Münze, Kugel und Würfel haben kein Gedächtnis.","beleg":"Werkstück B.30 (Eingangsszene; Kernidee; Analyse); Fn. gl-b-montecarlo (Huff 1959; Zahl nicht durch Kasinoprotokolle belegt); Fn. gl-b-tversky (Tversky/Kahneman 1971, S. 105–106)","status":"entwurf","kurz":"Jedes Spiel ist ein neuer, unabhängiger Wurf, und die Kugel weiß nicht, was zuvor fiel. Der Denkfehler: Eine Serie erzeugt Druck zum Ausgleich, doch das Gesetz der großen Zahlen verdünnt frühe Abweichungen nur.","prueffrage":"Wie viele rote und wie viele schwarze Fächer hat der Kessel vor dem ersten Spiel des Abends, und wie viele nach der Serie?","rueckmeldung":[{"option":0,"text":"Ein ungleicher Tisch wäre bei so einer Serie tatsächlich eine denkbare Erklärung. Das Szenario nennt den Tisch aber ausdrücklich unauffällig und einwandfrei, deshalb bleibt die Chance auf Rot bei jedem Spiel gleich."},{"option":1,"text":"Dass Rot nicht wahrscheinlicher wird, stimmt, die Begründung aber nicht: Eine Strähne mit Eigendynamik gibt es bei unabhängigen Würfen nicht. Schwarz ist genauso wenig „heiß“ wie Rot „fällig“, jeder Wurf beginnt neu."},{"option":2,"text":"Dass sich nichts schon im nächsten Spiel ausgleicht, stimmt. Die Annahme dahinter trägt jedoch nicht: Das Gesetz der großen Zahlen holt nichts nach, es verdünnt die frühe Serie nur, je mehr Spiele dazukommen."}],"familie":"zufall-ohne-gedaechtnis","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „Gambler’s“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1971): Belief in the law of small numbers. Psychological Bulletin 76(2), 105–110","oeffentlich":false,"doi":"10.1037/h0031322"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"ceb82f64376af640"}},{"id":"qx-b2-054","clusterId":"B","werkstueckRef":"B.30","stufe":2,"question":"Was ist an ihrem Vorgehen fehlerhaft?","scenario":"Eine Kreditprüferin hat drei Anträge hintereinander bewilligt. Beim vierten Antrag, der den anderen vom Risiko her gleicht, will sie ablehnen – „nur um nicht immer dasselbe zu entscheiden“.","options":["Sie behandelt die Reihe der Entscheidungen so, als müsse sie sich ausgleichen, obwohl jeder Antrag für sich zu beurteilen ist.","Sie schließt aus drei bewilligten Anträgen auf die Qualität künftiger Antragsteller, obwohl drei Fälle eine zu kleine Stichprobe sind.","Sie lässt sich von persönlichen Merkmalen der Antragsteller leiten, obwohl allein das Ausfallrisiko über die Bewilligung entscheiden sollte.","Sie verlässt sich beim vierten Antrag auf ihr Gefühl statt auf die Kennzahlen, obwohl Kredite nach berechnetem Risiko zu beurteilen sind."],"correctIndex":0,"explanation":"Jeder Antrag ist für sich zu bewerten; die vorherigen Entscheidungen sagen nichts über den nächsten Fall. Wer nach einer Serie das Gegenteil wählt, damit sich die Reihe „ausgleicht“, unterliegt dem Spielerfehlschluss: Er unterstellt einem Ablauf ohne Gedächtnis einen Ausgleichsdrang. Das ist kein Randphänomen: Chen, Moskowitz und Shue (2016) werteten über 150.000 Asylentscheidungen, rund 1,5 Millionen Schiedsrichter-Entscheidungen und gut 9.000 Kreditprüfungen aus einem Feldexperiment aus. Asylrichter, Kreditprüfer und Baseball-Schiedsrichter schwenkten nach einer oder mehreren gleichartigen Entscheidungen um einige Prozentpunkte häufiger „um“, und zwar umso öfter, je länger die Serie war. Ein Antrag verdient eine eigene Prüfung. Die Entscheidungen davor sind kein Argument. Die anderen Gedanken sind für sich bedenkenswert, treffen hier aber nicht zu: Die Prüferin schließt nichts über künftige Antragsteller, sie will nur die Reihe auflockern. Von persönlichen Merkmalen ist nicht die Rede, der Antrag gleicht den anderen vom Risiko her. Und ein Bauchgefühl gegen die Kennzahlen wird nicht erwähnt, ihr genannter Grund ist die Reihe selbst.","coreRule":"⚡ Jeder Fall beginnt neu: Die Entscheidung davor darf die Entscheidung jetzt nicht färben.","beleg":"Werkstück B.30 (Anwendung: Urteile unter Serien; Zahlen und Befund laut Buchtext); Fn. gl-b-chen (Chen/Moskowitz/Shue 2016, QJE 131(3), S. 1181–1242)","status":"entwurf","kurz":"Jeder Antrag ist für sich zu bewerten, denn die früheren Entscheidungen sagen nichts über den nächsten Fall. Wer nach einer Serie das Gegenteil wählt, damit sich die Reihe „ausgleicht“, unterstellt einem Ablauf ohne Gedächtnis einen Ausgleichsdrang.","prueffrage":"Worin unterscheidet sich der vierte Antrag vom Risiko her von den drei bereits bewilligten?","rueckmeldung":[{"option":1,"text":"Drei Fälle sind tatsächlich wenig, und mit kleinen Stichproben ist Vorsicht angebracht. Die Prüferin schließt aber gar nichts über künftige Antragsteller, sie will nur die Reihe auflockern."},{"option":2,"text":"Entscheiden sollte tatsächlich allein das Ausfallrisiko. Im Szenario ist aber von persönlichen Merkmalen nicht die Rede, der Antrag gleicht den anderen vom Risiko her. Ihr Grund liegt in der Reihe der Entscheidungen."},{"option":3,"text":"Kredite sollten nach berechnetem Risiko beurteilt werden. Von einem Bauchgefühl gegen die Kennzahlen steht hier aber nichts, ihr genannter Grund ist die Reihe selbst. Der Fehler liegt darin, was sie aus dieser Reihe macht."}],"familie":"zufall-ohne-gedaechtnis","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Chen, D. L.; Moskowitz, T. J.; Shue, K. (2016): Decision-Making under the Gambler's Fallacy: Evidence from Asylum Judges, Loan Officers, and Baseball Umpires. NBER Working Paper 22026","oeffentlich":true,"url":"https://www.nber.org/papers/w22026","seite":"14, 27","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"f188224742ccf90c"}},{"id":"qx-b2-055","clusterId":"B","werkstueckRef":"B.30","stufe":3,"question":"Wie beurteilst du den Einwand des Kollegen?","options":["Der Einwand trifft zu: Jonas’ Würfe sind so unabhängig wie die Läufe einer Roulettekugel, seine drei Treffer sagen also nichts über seinen nächsten Wurf.","Der Einwand greift zu kurz: Anders als eine Roulettekugel hat Jonas ein Gedächtnis, Form und Konzentration schwanken, die Serie kann also etwas aussagen.","Der Einwand trifft zu: Über ein ganzes Spiel gleichen sich Trefferserien wieder aus, nach drei Treffern ist bei Jonas also eher ein Fehlwurf zu erwarten.","Der Einwand greift zu kurz: Drei Treffer kündigen bei Spielern weitere Treffer an, während fünfmal Rot beim Roulette ein baldiges Ende der Serie ankündigt."],"correctIndex":1,"explanation":"Der Spielerfehlschluss gilt für unabhängige Zufallsereignisse: Eine Roulettekugel weiß nicht, was vorher geschah, also ist jeder Lauf ein erster Lauf. Jonas ist dagegen kein Zufallsgenerator, denn Menschen haben ein Gedächtnis, Kugeln nicht. Form und Konzentration können schwanken, sodass seine Serie etwas über den nächsten Wurf aussagen kann, aber nicht muss. Der Glaube an die „heiße Hand“ (eine Serie setzt sich fort) galt nach Gilovich, Vallone und Tversky (1985) lange als reiner Denkfehler. Neuere Analysen zeigen allerdings, dass es bei Menschen echte, messbare Formschwankungen geben kann; Miller und Sanjurjo (2018) korrigierten einen statistischen Verzerrungseffekt der älteren Analyse. Jonas’ Würfe mit den Läufen einer Kugel gleichzusetzen, klingt nüchtern, übersieht aber die entscheidende Frage: Hat das, was hier „würfelt“, ein Gedächtnis? Dass sich Serien über ein Spiel ausgleichen, trifft nicht zu, denn das Gesetz der großen Zahlen verdünnt Abweichungen nur, es gleicht sie nicht aus. Und dass Serien bei Spielern weitergehen und beim Roulette enden müssten, folgt weder für Kugeln noch für Spieler.","coreRule":"⚡ Prüfe zuerst, ob das, was die Serie erzeugt, ein Gedächtnis hat: Bei Roulettekugeln nie, bei Menschen kann eine Serie eine Ursache haben.","beleg":"Werkstück B.30 (Analyse); Fn. gl-b-hothand (Gilovich/Vallone/Tversky 1985, S. 295–314; Miller/Sanjurjo 2018, Econometrica 86(6), S. 2019–2047)","status":"entwurf","scenario":"Beim Spiel deiner Basketballmannschaft hat Jonas seine letzten drei Würfe getroffen. Trainerin Kaya sagt: „Gebt Jonas im nächsten Angriff den Ball. Wer gerade dreimal getroffen hat, trifft mit höherer Wahrscheinlichkeit auch den vierten.“ Ihr Kollege widerspricht: „Das ist derselbe Fehler wie im Casino, wo nach fünfmal Rot angeblich Schwarz fällig ist.“","kurz":"Eine Roulettekugel weiß nicht, was vorher geschah, ein Spieler schon: Form und Konzentration schwanken. Darum ist es ein Fehler, Jonas mit einer Kugel gleichzusetzen, denn seine Serie kann etwas über den nächsten Wurf aussagen, muss aber nicht.","prueffrage":"Hängt das, was hier „würfelt“, davon ab, was vorher passiert ist, oder fängt jeder Versuch von vorn an?","rueckmeldung":[{"option":0,"text":"Beim Roulette stimmt das, jeder Lauf beginnt von vorn. Jonas ist aber keine Kugel: Form und Konzentration schwanken, und seine Serie kann etwas aussagen, auch wenn sie es nicht muss."},{"option":2,"text":"Dass sich Abweichungen später „ausgleichen“, wirkt plausibel. Das Gesetz der großen Zahlen verdünnt sie aber nur, es gleicht sie nicht aus. Ein Fehlwurf ist deshalb nicht „fällig“; das wäre selbst der Spielerfehlschluss."},{"option":3,"text":"Dass der Einwand zu kurz greift, stimmt. Die Begründung trägt aber nicht: Weder endet beim Roulette eine Serie „fällig“, noch muss sie bei Spielern weitergehen. Bei Spielern kann sie etwas aussagen, bei Kugeln nichts."}],"familie":"zufall-ohne-gedaechtnis","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Miller, J. B.; Sanjurjo, A.: Surprised by the Hot Hand Fallacy? A Truth in the Law of Small Numbers. arXiv:1902.01265 (Autorenfassung; Econometrica 86(6), 2018, 2019–2047)","oeffentlich":true,"url":"https://arxiv.org/abs/1902.01265","abruf":"2026-10-12"},{"typ":"doi","kurz":"Gilovich, T.; Vallone, R.; Tversky, A. (1985): The hot hand in basketball: On the misperception of random sequences. Cognitive Psychology 17(3), 295–314","oeffentlich":false,"doi":"10.1016/0010-0285(85)90010-6"},{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „Gambler’s“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"ec536927e200f36a"}},{"id":"qx-b2-056","clusterId":"B","werkstueckRef":"B.30","stufe":4,"question":"Wie lässt sich die Beobachtung am besten erklären, ohne in den Spielerfehlschluss zu geraten?","scenario":"Nach einer ungewöhnlich schlechten Woche hat dein Fitnessarmband für die Folgewoche wieder normalere Werte gezeigt. Ein Bekannter sagt: „Das hat sich eben ausgeglichen. Die schlechte Woche musste durch eine bessere wettgemacht werden.“","options":["Extreme Werte sind selten, deshalb folgt auf einen Ausreißer meist ein normalerer Wert. Dafür muss nichts „ausgeglichen“ werden.","Auf eine Phase der Schwäche folgt meist eine Erholung des Körpers. Die schlechte Woche hat die normale Folgewoche also vorbereitet.","Wer seine Werte im Blick hat, verhält sich anders. Der schlechte Wert hat dich vermutlich in der Folgewoche zu mehr Bewegung angespornt.","Das Armband hat in der schlechten Woche vermutlich ungenau gemessen. Die Folgewoche zeigt deshalb wieder die tatsächlichen Werte."],"correctIndex":0,"explanation":"Die Beobachtung selbst stimmt: Extreme Werte werden tatsächlich oft von normaleren gefolgt. Aber nicht, weil der Zufall etwas ausgleicht, sondern weil Extremwerte selten sind. Der Spielerfehlschluss dagegen unterstellt, dass eine Abweichung aktiv „ausgeglichen“ werden müsse. Das Gesetz der großen Zahlen gleicht aber nichts aus, es verdünnt Abweichungen nur: Frühe Ausreißer fallen immer weniger ins Gewicht, je mehr normale Werte dazukommen. Eine bessere Folgewoche ist also nicht „fällig“, sie ist einfach der wahrscheinlichere Normalfall.","coreRule":"⚡ Auf Extremes folgt oft Normales, aber nicht, weil der Zufall etwas schuldig wäre.","beleg":"Werkstück B.30 (Verbindungen: Nicht zu verwechseln mit Regression zur Mitte; Analyse)","status":"entwurf","kurz":"Extreme Werte sind selten, darum folgt auf einen Ausreißer meist ein normalerer Wert. Der Denkfehler liegt darin, aus „wahrscheinlicher Normalfall“ ein „fälliger Ausgleich“ zu machen. Nichts muss wettgemacht werden.","prueffrage":"Wie oft hat das Armband in früheren Wochen so schlechte Werte gezeigt, und wie oft normale?","rueckmeldung":[{"option":1,"text":"Erholung nach Schwäche kommt vor und klingt vernünftig. Hier steht aber nichts davon, dass die schlechte Woche eine Erholungsphase war. Und „vorbereitet“ klingt wie ein Ausgleich, genau die Vorstellung, die den Spielerfehlschluss ausmacht."},{"option":2,"text":"Dass der Blick aufs Armband das Verhalten ändert, ist im Einzelfall denkbar. Das Szenario erwähnt davon aber nichts, die Erklärung stützt sich auf eine bloße Vermutung. Normalere Werte nach einem Ausreißer ergeben sich auch ohne eine solche Annahme."},{"option":3,"text":"Ein ungenaues Gerät ist möglich, doch es gibt hier keinen Hinweis darauf. Ungewöhnliche Werte allein beweisen keinen Messfehler. Die Annahme erklärt den Ausreißer weg, statt zu zeigen, warum auf Extremwerte meist normalere folgen."}],"familie":"was-waere-ohne","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Regression“, „Gambler’s“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Barnett, A. G.; van der Pols, J. C.; Dobson, A. J. (2005): Regression to the mean: what it is and how to deal with it. International Journal of Epidemiology 34(1), 215–220","oeffentlich":false,"doi":"10.1093/ije/dyh299"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1971): Belief in the law of small numbers. Psychological Bulletin 76(2), 105–110","oeffentlich":false,"doi":"10.1037/h0031322"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"8b6385bb55ff2a20"}},{"id":"qx-b2-057","clusterId":"B","werkstueckRef":"B.31","stufe":1,"question":"Welche Beobachtung würde die Behauptung der Kollegin am stärksten widerlegen?","options":["Die Jugendlichen bevorzugen beim Verteilen die eigene Gruppe, obwohl es weder Wettkampf noch Streit gab und die Einteilung zufällig war.","Die Jugendlichen bevorzugen beim Verteilen die eigene Gruppe stärker, nachdem sie in einem Wettkampf um einen Preis gegeneinander angetreten sind.","Die Jugendlichen verteilen mehr an Mitschüler, die sie persönlich mögen, ganz gleich in welcher Gruppe diese sind, obwohl die Einteilung zufällig war.","Die Jugendlichen verteilen das Geld gleichmäßig auf beide Gruppen, wenn die Einteilung per Münzwurf erfolgt und es weder Wettkampf noch Streit gab."],"correctIndex":0,"explanation":"Die Behauptung sagt: Ohne Konkurrenz und ohne Streitgeschichte entsteht keine Gruppenbevorzugung. Am stärksten widerlegt sie ein Fall, in dem beides fehlt, die Einteilung rein zufällig ist und die eigene Gruppe trotzdem bevorzugt wird; ähnlich war der Versuch von Tajfel mit britischen Schuljungen angelegt (Einteilung angeblich nach Bildgeschmack, tatsächlich zufällig), und in einem Folgeversuch blieb die Bevorzugung auch bei offen per Münzwurf gebildeten Gruppen bestehen, wenn auch schwächer. Wer mehr an Mitschüler gibt, die er persönlich mag, kann damit einer Beziehung folgen statt der Gruppe; über Konkurrenz und Streit sagt das nichts.","coreRule":"⚡ Wer behauptet, eine Ursache sei nötig, wird widerlegt durch einen Fall, in dem sie fehlt und die Wirkung trotzdem eintritt. Schon ein bloßes Etikett kann „wir“ gegen „die“ erzeugen.","beleg":"Werkstück B.31 (Eingangsszene); Fn. gl-b-tajfel (Tajfel 1970; Tajfel u. a. 1971; Billig/Tajfel 1973, S. 28 f.); Anmerkung zu gl-b-tajfel (Münzwurf-Bedingung im Folgeversuch)","status":"entwurf","scenario":"Eine Kollegin sagt: „Gruppenbevorzugung entsteht erst, wenn Gruppen um knappe Ressourcen konkurrieren und es eine Vorgeschichte von Streit gibt.“ In einem Versuch werden Jugendliche, die sich aus der Schule kennen, zufällig in zwei Gruppen eingeteilt, etwa per Münzwurf. Sie wissen nicht, wer sonst zu ihrer Gruppe gehört, und verteilen Geld an anonyme Empfänger beider Gruppen.","quote":"","quoteLabel":"","kurz":"Widerlegt wird die Behauptung nur durch einen Fall, in dem Konkurrenz und Streitgeschichte fehlen und die eigene Gruppe trotzdem bevorzugt wird. Beobachtungen mit Wettkampf, Sympathie oder Gleichverteilung betreffen diese Bedingung nicht oder bestätigen sie sogar.","prueffrage":"Unter welchen Umständen würde die Kollegin selbst gar keine Bevorzugung der eigenen Gruppe erwarten?","rueckmeldung":[{"option":1,"text":"Dass Wettkampf die Bevorzugung verstärkt, wirkt wie ein starkes Ergebnis. Es passt aber zur Behauptung: Konkurrenz soll ja Gruppenbevorzugung hervorbringen. Ob sie auch ohne Konkurrenz entsteht, sagt diese Beobachtung nicht."},{"option":2,"text":"Wer Gemochten mehr gibt, zeigt etwas Reales: Beziehungen zählen. Das folgt aber der Sympathie, nicht der Gruppe, und sagt nichts darüber, ob ohne Konkurrenz und Streit Gruppenbevorzugung entsteht."},{"option":3,"text":"Gleichmäßiges Verteilen ohne Wettkampf und Streit wirkt wie ein sauberer Test. Es entspricht aber genau dem, was die Kollegin vorhersagt: ohne Konkurrenz und Streitgeschichte keine Bevorzugung. Das bestätigt ihre Behauptung, statt sie zu widerlegen."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Tajfel, H.; Turner, J. C. (1979): An Integrative Theory of Intergroup Conflict. In: Austin, W. G.; Worchel, S. (Hg.): The Social Psychology of Intergroup Relations (Kopie bei ALNAP)","oeffentlich":true,"url":"https://alnap.org/documents/8612/tajfel-turner-1979-compressed.pdf","seite":"38–39","abruf":"2026-10-12"},{"typ":"doi","kurz":"Billig, M.; Tajfel, H. (1973): Social categorization and similarity in intergroup behaviour. European Journal of Social Psychology 3(1)","oeffentlich":false,"doi":"10.1002/ejsp.2420030103","seite":"27–29, 34, 39"},{"typ":"literatur","kurz":"Tajfel, H. (1970): Experiments in Intergroup Discrimination. Scientific American 223(5)","oeffentlich":false,"seite":"99–102"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"108571012ff3ec6e"}},{"id":"qx-b2-058","clusterId":"B","werkstueckRef":"B.31","stufe":3,"question":"Ein Kommentator behauptet: „Das Experiment beweist es: Sobald Menschen in ‚wir‘ und ‚die‘ eingeteilt werden, ist der Weg zur Entmenschlichung vorgezeichnet. Wer Gruppen bildet, bekommt am Ende Feindbilder.“ Was ist an diesem Schluss am ehesten fehlerhaft?","options":["Er springt von der milden Bevorzugung der eigenen Gruppe auf eine extreme Folge, ohne zu zeigen, dass die bloße Einteilung diesen Weg allein zurücklegt.","Er verallgemeinert von Jugendlichen in einem einzelnen Versuch auf Menschen überhaupt, obwohl Erwachsene in derselben Lage anders entscheiden könnten.","Er überschätzt den Befund, denn bei kleinen Geldbeträgen geht es um wenig, sodass die Bevorzugung eher ein Spiel als eine echte Haltung zeigen dürfte.","Er übersieht, dass es sich um eine künstliche Laborsituation handelt, aus der sich über echte Gruppen im Alltag nur wenig ablesen lässt."],"correctIndex":0,"explanation":"Das Experiment zeigt eine milde, messbare Bevorzugung der eigenen Gruppe bei bloßer, sogar zufälliger Einteilung. Zwischen diesem Befund und der Entmenschlichung, bei der der Fremdgruppe die Menschlichkeit selbst abgesprochen wird, liegt ein weiter Weg, den die bloße Einteilung allein nicht zurücklegt. Den Weg dorthin treibt dieselbe Gruppenbindung unter wachsendem Druck: Bedrohung, Konkurrenz um knappe Ressourcen und eine Führung, die die Distanz zwischen „wir“ und „die“ vergrößert. Zudem lässt sich der Ursprung der Gruppenbindung auch ohne Feindschaft erklären: Eine mögliche Erklärung sieht in ihr eine Gemeinschaft gegenseitigen Vertrauens, die Verbündeten Schutz und geteilte Nahrung brachte – eine Hypothese, kein Messergebnis. Und auch Entmenschlichung ist kein Entweder-oder, sondern hat Stufen von subtil bis offen. Der Kommentator schließt also von einem Anfangsbefund auf ein Endergebnis, ohne die Zwischenstrecke zu belegen.","coreRule":"⚡ Wer von einem milden Befund auf eine extreme Folge schließt, muss den Weg dazwischen belegen: Wir-Gefühl ist noch keine Feindschaft.","beleg":"Werkstück B.31 (Kontext & Tiefe; Kipppunkt); Fn. gl-b-brewer (Brewer 1999, S. 432–434); Fn. gl-b-kteily (Kteily u. a. 2015)","status":"entwurf","scenario":"In einem Experiment werden Jugendliche per Zufall in zwei Gruppen eingeteilt, angeblich nach ihrem Bildgeschmack. Sie verteilen anschließend kleine Geldbeträge an anonyme Mitglieder beider Gruppen und bevorzugen dabei systematisch die eigene Gruppe, teils sogar auf Kosten des absoluten Gewinns der eigenen Gruppe, solange der Abstand zur anderen Gruppe wächst.","kurz":"Der Versuch zeigt nur eine milde Bevorzugung der eigenen Gruppe. Bis zur Entmenschlichung ist es ein weiter Weg, und den legt die bloße Einteilung nicht allein zurück. Der Fehler: Von einem Anfangsbefund wird auf ein Endergebnis geschlossen, ohne die Zwischenstrecke zu belegen.","prueffrage":"Was taten die Jugendlichen im Experiment gegenüber der anderen Gruppe, und was davon wurde gemessen?","rueckmeldung":[{"option":1,"text":"Dass sich Erwachsene anders verhalten könnten, ist möglich, aber nicht der Kern. Selbst bei gleichem Ergebnis bliebe die Lücke zwischen milder Bevorzugung und Entmenschlichung bestehen."},{"option":2,"text":"Kleine Beträge klingen nach wenig Einsatz. Die Jugendlichen bevorzugten die eigene Gruppe aber systematisch, sogar auf Kosten ihres absoluten Gewinns, das ist ein messbares Verhalten. Fehlerhaft ist nicht der Befund, sondern die Übertreibung seiner Folgen."},{"option":3,"text":"Ein Laborversuch ist tatsächlich künstlich, und das begrenzt die Übertragbarkeit. Der Schluss scheitert aber schon früher: Selbst bei voller Übertragbarkeit folgte aus milder Bevorzugung noch keine Entmenschlichung."}],"familie":"dammbruch-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Brewer, M. B. (1999): The Psychology of Prejudice: Ingroup Love or Outgroup Hate? Journal of Social Issues 55(3) (inoffizielle Kopie auf Server des Bard College)","oeffentlich":true,"url":"https://bcsh.bard.edu/files/2019/06/Brewer-ingroup-love-or-outgroup-hate.pdf","seite":"431–437","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kteily, N.; Bruneau, E.; Waytz, A.; Cotterill, S. (2015): The Ascent of Man: Theoretical and Empirical Evidence for Blatant Dehumanization. JPSP 109(5)","oeffentlich":false,"doi":"10.1037/pspp0000048"},{"typ":"url","kurz":"Tajfel, H.; Turner, J. C. (1979): An Integrative Theory of Intergroup Conflict (Kopie bei ALNAP)","oeffentlich":true,"url":"https://alnap.org/documents/8612/tajfel-turner-1979-compressed.pdf","seite":"38–39","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"d6a17f1f36d72a4d"}},{"id":"qx-b2-059","clusterId":"B","werkstueckRef":"B.31","stufe":4,"question":"Was zeigt diese Beobachtung am ehesten über den Charakter der Debatte?","scenario":"In einer Debatte über eine Klimamaßnahme werden Abweichler in der eigenen Gruppe heftiger angegriffen als die eigentliche Gegenseite. Die Gegenseite wird nur noch als einheitliche Masse beschrieben.","options":["Die Gruppe nimmt Widerspruch auch im Inneren ernst, und die Debatte ist dadurch sachlicher geworden.","Die Gruppe prüft Abweichler strenger als externe Gegner, weil ihr die Sache besonders wichtig ist.","Die Gruppengrenze ist wichtiger geworden als die Sache selbst, und die Gegenseite gilt nur noch als Masse.","Die Gegenseite hat in der Sache recht, weil Gruppen auf unbequeme Wahrheiten besonders heftig reagieren."],"correctIndex":2,"explanation":"Wenn Abweichler in der eigenen Gruppe härter angegriffen werden als die eigentliche Gegenseite, geht es erkennbar nicht mehr um die Klimamaßnahme, sondern um Loyalität: Wer abweicht, stellt die Zugehörigkeit infrage. Dazu passt, dass die Gegenseite nur noch als einheitliche Masse ohne eigene Stimmen beschrieben wird. Das ist ein typisches Zeichen dafür, dass die Gruppenzugehörigkeit die Sachfrage überlagert: Wichtiger als die Argumente wird, was die Zugehörigkeit zur eigenen Gruppe signalisiert. Eine einfache Prüffrage: Würdest du dasselbe Argument genauso bewerten, wenn es aus der eigenen Gruppe käme, und ihm genauso widersprechen, wenn ein Mitglied deiner Gruppe es verträte?","coreRule":"⚡ Wo Zustimmung vor allem Zugehörigkeit signalisiert, verliert das Argument sein Gewicht.","quote":"","quoteLabel":"","beleg":"Werkstück B.31 (Red Flags; Anwendung: Politische Polarisierung; Anti-Denkmuster)","status":"entwurf","kurz":"Wer Abweichler härter angreift als die Gegenseite und diese nur noch als Masse beschreibt, kämpft erkennbar um Zugehörigkeit statt um die Klimamaßnahme. Der naheliegende Fehler ist, Härte für besondere Sachstrenge zu halten.","prueffrage":"Wen trifft die schärfste Kritik: Menschen mit anderen Argumenten oder Menschen aus den eigenen Reihen?","rueckmeldung":[{"option":0,"text":"Kritik von innen kann ein Zeichen offener Debatte sein. Hier werden Abweichler aber heftig angegriffen statt angehört, und die Gegenseite kommt nur als Masse vor. Das spricht nicht für mehr Sachlichkeit."},{"option":1,"text":"Wem eine Sache wichtig ist, der prüft genau, das wirkt plausibel. Doch wer wirklich die Sache prüft, nimmt sich die Gegenseite mindestens so genau vor wie Abweichler und beschreibt sie nicht nur als einheitliche Masse."},{"option":3,"text":"Heftige Reaktionen sagen etwas über die Gruppe, nicht darüber, wer in der Sache recht hat. Zudem treffen sie hier vor allem Abweichler aus den eigenen Reihen und nicht die Gegenseite."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Ditto, P. H. u. a. (2019): At Least Bias Is Bipartisan: A Meta-Analytic Comparison of Partisan Bias in Liberals and Conservatives. Perspectives on Psychological Science 14(2) (Kopie auf der Seite des Ditto-Labors, UC Irvine)","oeffentlich":true,"url":"https://sites.uci.edu/peterdittolab/files/2018/06/Ditto-et-al.-2018-At-Least-Bias-is-Bipartisan-A-Meta-Analytic-Comparison-of-Partisan-Bias-in-Liberals-Conservatives.pdf","abruf":"2026-10-12"},{"typ":"url","kurz":"Castano, E.; Yzerbyt, V. Y. (1998): The highs and lows of group homogeneity. Behavioural Processes 42 (Kopie auf der Seite von V. Yzerbyt, UCLouvain)","oeffentlich":true,"url":"https://perso.uclouvain.be/vincent.yzerbyt/Castano%20&%20Yzerbyt%20BP%201998.pdf","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"3b5b3cae3558bba0"}},{"id":"qx-b2-060","clusterId":"B","werkstueckRef":"B.31","stufe":2,"question":"Welche Erklärung für diese Wahl ist am sparsamsten und erklärt zugleich, warum die Verteilung mit weniger Punkten für die eigene Gruppe gewählt wird?","scenario":"Zwei Gruppen von Schülern wurden eben erst zufällig eingeteilt, ohne Wettkampf und ohne vorherigen Streit; niemand weiß, wer sonst zur eigenen Gruppe gehört. Nun dürfen sie Punkte an anonyme Empfänger beider Gruppen verteilen, die später in echtes Geld umgetauscht werden. Viele wählen eine Verteilung, bei der die eigene Gruppe 7 Punkte und die andere 1 Punkt bekommt, statt einer Verteilung mit 10 Punkten für die eigene und 12 für die andere Gruppe. Dabei verteilen sie nie an sich selbst.","options":["Die Gruppe ist ihnen schon so wichtig, dass sie vor allem den Abstand zur anderen Gruppe vergrößern wollen, auch wenn die eigene Gruppe dabei absolut weniger erhält.","Sie wollen den Gewinn der eigenen Gruppe so groß wie möglich machen, weil mehr Punkte später auch mehr Geld bedeuten (Gewinnmaximierung).","Sie sehen in der anderen Gruppe einen Konkurrenten um knappe Mittel und wollen ihr zuvorkommen, bevor sie selbst benachteiligt werden (Gruppenkonflikt).","Sie folgen einer Reziprozitätsnorm: Wer der eigenen Gruppe viel gibt, erhält später eine Gegenleistung von deren Mitgliedern."],"correctIndex":0,"explanation":"Wenn jemand die Verteilung mit weniger Punkten für die eigene Gruppe wählt, nur weil der Abstand größer ist, geht es nicht ums Gewinnen, sondern ums Besser-Dastehen. Das passt dazu, dass ein Teil des Selbstwerts an die Gruppe gekoppelt ist: Es genügt nicht, dass es „uns“ gut geht, „wir“ sollen mehr haben als „die“. Dass schon eine zufällige Einteilung ausreicht, ist der Kern des Befunds: Das Gruppenetikett allein genügt, damit der Vergleich mit der anderen Gruppe wichtig wird. Die anderen Erklärungen klingen vernünftig, passen aber nicht zur Wahl: Wer den Gewinn der eigenen Gruppe maximieren wollte, hätte 10 statt 7 Punkte gewählt. Ein Konkurrenzdenken um knappe Mittel setzt einen Wettkampf voraus, den es hier nicht gab. Und Gegenleistung zu erwarten ergibt keinen Sinn, wenn niemand weiß, wer außer ihm selbst zur Gruppe gehört.","coreRule":"⚡ Wenn jemand lieber weniger für alle will, solange „wir“ mehr haben als „die“, geht es nicht um Gewinn, sondern um den Vergleich.","beleg":"Werkstück B.31 (Kernidee; Kontext & Tiefe: Sozialer Vergleich & positive Distinktheit)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Wer 7 zu 1 statt 10 zu 12 wählt, will nicht möglichst viel gewinnen, sondern besser dastehen als die andere Gruppe. Naheliegend wäre Eigennutz, doch der hätte die 10 Punkte gewählt; hier zählt der Abstand.","prueffrage":"Was haben die Schüler in der Verteilung für ihre eigene Gruppe verloren, und was haben sie dafür bekommen?","rueckmeldung":[{"option":1,"text":"Dass aus den Punkten später echtes Geld wird, spricht auf den ersten Blick für Eigennutz. Wer aber den Ertrag der eigenen Gruppe maximieren wollte, hätte die 10 Punkte gewählt statt der 7, und die Gruppe geht hier sogar mit weniger aus der Verteilung."},{"option":2,"text":"Konkurrenz um knappe Mittel erklärt oft Streit zwischen Gruppen. Hier gab es aber weder Wettkampf noch Vorgeschichte, die Gruppen wurden eben erst zufällig gebildet, und niemand muss sich Mittel gegen die andere Seite sichern."},{"option":3,"text":"Gegenseitigkeit kann Verhalten sonst tatsächlich steuern. Eine Gegenleistung setzt aber voraus, dass man weiß, wer sie erbringen soll; hier kennt niemand die anderen Gruppenmitglieder. Und sie würde nicht erklären, warum die eigene Gruppe mit 7 statt 10 Punkten weniger bekommt."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Tajfel, H.; Turner, J. C. (1979): An Integrative Theory of Intergroup Conflict (Kopie bei ALNAP)","oeffentlich":true,"url":"https://alnap.org/documents/8612/tajfel-turner-1979-compressed.pdf","seite":"38–42","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Tajfel, H. (1970): Experiments in Intergroup Discrimination. Scientific American 223(5)","oeffentlich":false,"seite":"101–102"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"51005926453848ad"}},{"id":"qx-b2-061","clusterId":"B","werkstueckRef":"B.32","stufe":1,"question":"Welche Annahme steckt hinter dieser Einschätzung, und warum ist sie riskant?","options":["Er unterstellt, die Regierung dort sehe ihre Lage so wie er, und riskant ist das, weil er so fehlendes Wissen über sie durch sein eigenes Bild ersetzt.","Er unterstellt, das Land habe sicher keinen Feind, und riskant ist das, weil sich die Feindlage ändern und seine Einschätzung dann überholen könnte.","Er unterstellt, Regierungen wögen nüchtern Nutzen und Kosten ab, und riskant ist das, weil auch andere Gründe als Berechnung den Ausschlag geben können.","Er unterstellt, ohne Feind fehle jeder Grund für eine Atomwaffe, und riskant ist das, weil auch Ansehen oder Verhandlungsmacht ein Motiv sein könnten."],"correctIndex":0,"explanation":"Die Einschätzung beantwortet nicht die Frage, wie die fremde Regierung ihre Lage sieht, sondern eine andere: Was würde ich an ihrer Stelle wollen? Sie stützt sich auf nichts, was von der anderen Seite stammt, weder Äußerungen noch Kenntnis ihrer Lage. Wo Wissen fehlt, setzt man unbemerkt das einzige Modell eines Geistes ein, das man von innen kennt: sich selbst. Das nennt man Spiegelbild-Denken (Mirror-Imaging). So wurde 1977 ein mutmaßliches Atomtestgelände in Südafrika von vielen Analysten abgetan, mit genau diesem Argument. Als Notbehelf lässt sich der Blick in den Spiegel manchmal nicht vermeiden, aber ein solches Urteil verdient wenig Vertrauen. Besser prüft man, ob die andere Seite ihre Lage selbst beschrieben hat, und zieht Menschen hinzu, die sie aus eigener Anschauung kennen.","coreRule":"⚡ Wo Wissen über den anderen fehlt, setzt man sich selbst ein, ohne es zu merken. Frag daher: Weiß ich, wie die andere Seite ihre Lage sieht, oder setze ich nur ein, was ich an ihrer Stelle täte?","beleg":"Werkstück B.32 (Kernidee; Analyse); Fn. gl-b-heuer (Heuer 1999, Psychology of Intelligence Analysis, S. 70)","status":"entwurf","scenario":"Ein Analyst soll einschätzen, ob ein ihm kaum bekannter Staat Atomwaffen anstrebt. Er schreibt: „Das Land hat keinen Feind, gegen den sich eine Atomwaffe wirksam einsetzen ließe. Also will es keine. An seiner Stelle würde ich auch darauf verzichten.“ Niemand im Team kennt das Land aus eigener Anschauung, und es liegen keine Äußerungen der dortigen Regierung vor.","kurz":"Der Analyst fragt nicht, wie die fremde Regierung ihre Lage sieht, sondern was er an ihrer Stelle wollte. Weil nichts von dort vorliegt, ersetzt sein eigenes Bild das fehlende Wissen, und darauf lässt sich kaum bauen.","prueffrage":"Was von dem, worauf sich die Einschätzung stützt, stammt tatsächlich von der Regierung des Landes selbst?","rueckmeldung":[{"option":1,"text":"Dass sich Feindlagen ändern können, stimmt, und eine Einschätzung kann so veralten. Der Fehler liegt aber schon im jetzigen Urteil, das die Lage aus der Sicht des Analysten statt aus der des Landes beurteilt."},{"option":2,"text":"Dass Entscheidungen oft nicht nur auf Berechnung beruhen, stimmt. Der Kern liegt aber früher: Der Analyst nimmt sein eigenes Abwägen als das der fremden Regierung und kennt weder ihre Lage noch ihre Gründe."},{"option":3,"text":"Ansehen oder Verhandlungsmacht können tatsächlich Motive sein. Damit wäre aber nur ein weiterer Grund genannt, den der Analyst übersehen hat. Der Denkfehler bleibt bestehen, solange er die Sicht des Landes durch seine eigene ersetzt."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Heuer, R. J. (1999): Psychology of Intelligence Analysis. CIA, Center for the Study of Intelligence","oeffentlich":true,"url":"https://www.cia.gov/resources/csi/static/Pyschology-of-Intelligence-Analysis.pdf","seite":"70–71, 181","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"24ead15d916713a4"}},{"id":"qx-b2-062","clusterId":"B","werkstueckRef":"B.32","stufe":3,"question":"Was ist der entscheidende Fehler an diesem Vorgehen?","options":["Die vorläufige Annahme des Beraters wurde zur gesicherten Ausgangslage der Sanktionsentscheidung, obwohl sie nur eine Wissenslücke überbrücken sollte.","Die Besprechung legte sich auf eine einzige Annahme über die Nachbarregierung fest, obwohl man bei so wenig Wissen mehrere Möglichkeiten durchspielen sollte.","Der Entwurf übernimmt die Annahme des Beraters ohne Herkunftsangabe, sodass niemand mehr nachvollziehen kann, woher die Einschätzung zum Truppenabzug stammt.","Der Entwurf baut die Sanktionsentscheidung auf einen einzigen erwarteten Ausgang, sodass sie nicht trägt, falls die Nachbarregierung ihre Truppen nicht abzieht."],"correctIndex":0,"explanation":"Die eigene Sicht ist das einzige Modell eines Geistes, das wir von innen kennen. Als vorläufiger Notbehelf bei fehlendem Wissen ist sie kaum zu vermeiden, solange allen klar bleibt, dass es nur eine Vermutung ist. Der Fehler liegt im Wechsel von der Vermutung zur Gewissheit: Aus „So würden wir handeln“ wurde „So wird sie handeln, alles andere wäre unvernünftig“, und das Wort „unvernünftig“ misst das Gegenüber an den eigenen Maßstäben. Wo niemand die andere Seite kennt, trägt diese Annahme allein keine folgenreiche Entscheidung. Dann hilft es, Fachleute hinzuzuziehen, die das Land kennen, oder die andere Seite mit ihren eigenen Worten zu Wort kommen zu lassen.","coreRule":"⚡ Ein Spiegel ist als Notbehelf erlaubt, solange du weißt, dass du in einen Spiegel blickst.","beleg":"Werkstück B.32 (Adaptives Talent; Kipppunkt; Anwendung & Relevanz: Fachleute von außen); Fn. gl-b-heuer (Heuer 1999, S. 70 f. und 181)","status":"entwurf","scenario":"In einer Lagebesprechung sagt ein Berater: „Über die Absichten der Nachbarregierung wissen wir wenig. Also nehmen wir vorläufig an, sie handelt so, wie wir es an ihrer Stelle täten.“ Drei Wochen später steht im Entwurf einer Sanktionsentscheidung als Ausgangslage: „Die Nachbarregierung wird ihre Truppen abziehen, denn alles andere wäre unvernünftig.“ Niemand im Raum kennt das Land aus eigener Anschauung.","kurz":"Aus einer Notannahme bei fehlendem Wissen wurde in drei Wochen eine Gewissheit: „So würden wir handeln“ wurde zu „So wird sie handeln“. Das Wort „unvernünftig“ misst die andere Seite an den eigenen Maßstäben, und das trägt keine folgenreiche Entscheidung.","prueffrage":"Welche neuen Erkenntnisse über das Nachbarland liegen zwischen der Lagebesprechung und dem Entwurf drei Wochen später?","rueckmeldung":[{"option":1,"text":"Mehrere Möglichkeiten durchzuspielen ist bei dünner Wissenslage klug. Hier war die Annahme in der Besprechung aber ausdrücklich nur vorläufig. Schiefgegangen ist später etwas anderes: Sie wurde ungeprüft zur Gewissheit."},{"option":2,"text":"Herkunftsangaben machen Einschätzungen nachvollziehbar, und das ist nützlich. Selbst mit sauberem Nachweis bliebe die Annahme aber eine bloße Vermutung vom eigenen Standpunkt aus, die im Entwurf als sicher auftritt."},{"option":3,"text":"Wer eine Entscheidung auf einen einzigen Ausgang baut, geht ein echtes Risiko ein. Das ist jedoch die Folge, nicht die Ursache. Auch mehrere Szenarien blieben fragwürdig, solange jedes nur aus der eigenen Sicht abgeleitet ist."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Heuer, R. J. (1999): Psychology of Intelligence Analysis. CIA, Center for the Study of Intelligence","oeffentlich":true,"url":"https://www.cia.gov/resources/csi/static/Pyschology-of-Intelligence-Analysis.pdf","seite":"70–71, 181","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"e317b4e705d0754e"}},{"id":"qx-b2-063","clusterId":"B","werkstueckRef":"B.32","stufe":4,"question":"Was ist die klügste Reaktion auf diesen Satz in einer Lageanalyse?","scenario":"In einer Lageanalyse zu einem fremden Land steht: „Das Vorgehen dieser Regierung ist völlig irrational und gegen ihre eigenen Interessen.“ Keiner der Autoren hat das Land je besucht, und die Regierung selbst kommt in der Analyse nicht zu Wort.","options":["Den Satz als Hinweis nehmen, dass die Regierung unberechenbar handelt, und in der Analyse vorsorglich von ihrem ungünstigsten Verhalten ausgehen.","Den Satz als Frage des Tons nehmen und „völlig irrational“ durch „schwer nachvollziehbar“ ersetzen, ohne die Einschätzung selbst zu ändern.","Den Satz als Behauptung nehmen, die man durch weitere Beispiele für das Verhalten der Regierung stützt, bis die Analyse belastbar ist.","Den Satz als Warnzeichen nehmen, dass womöglich eigene Werte und Denkrahmen übertragen wurden, und prüfen, wie die Regierung ihre Lage selbst sieht."],"correctIndex":3,"explanation":"Wenn das Verhalten einer fremden Regierung „irrational“ oder „gegen ihre eigenen Interessen“ wirkt, liegt der Fehler oft beim Beobachter: Er hat die eigenen Werte und Denkrahmen auf sie übertragen, statt die Logik der Lage so zu verstehen, wie sie sich ihr selbst darstellt. Wer nicht weiß, wie das Gegenüber denkt, setzt meist unbemerkt das einzige Modell eines Geistes ein, das er von innen kennt: sich selbst. Dass die Analyse keine Selbstauskunft der Regierung enthält und niemand das Land kennt, verstärkt den Verdacht. Das Etikett „irrational“ beendet die Erklärung, wo sie beginnen sollte. Die bessere Frage lautet: Weiß ich, wie die andere Seite ihre Lage sieht, oder setze ich nur ein, was ich an ihrer Stelle täte? Reden, Interviews und Programme der Regierung selbst sowie Fachleute, die das Land aus eigener Anschauung kennen, prüfen das. Ein neutraleres Wort ändert nur den Ton, nicht den Denkfehler dahinter. Und weitere Beispiele für das Verhalten zeigen nur, was die Regierung tut, nicht, warum sie es aus ihrer Sicht tut.","coreRule":"⚡ „Irrational“ sagt oft mehr über den Beobachter als über den Beobachteten.","quote":"","quoteLabel":"","beleg":"Werkstück B.32 (Analyse; Red Flags; Anti-Denkmuster); Fn. gl-b-heuer (Heuer 1999, S. 33)","status":"freigegeben","freigabe":{"datum":"2026-10-15","pruefsumme":"e9968cf897868b83","vermerk":"Prüfpult (Sturm, erste Charge nach den neuen falschen Optionen)"},"kurz":"Wenn ein fremdes Vorgehen „irrational“ wirkt, liegt der Fehler oft beim Beobachter: Er überträgt eigene Werte und Denkrahmen, statt zu klären, wie die Regierung ihre Lage selbst sieht. Das Etikett beendet die Erklärung, wo sie beginnen sollte.","prueffrage":"Auf welchen Quellen beruht das Urteil „irrational“, und wer von den Autoren war je in diesem Land?","rueckmeldung":[{"option":0,"text":"Vorsicht ist in einer Lageanalyse grundsätzlich sinnvoll. Hier übernimmt sie aber das Etikett „unberechenbar“ als Befund, obwohl es nur die Außensicht spiegelt, und prüft nicht, wie die Regierung ihre Lage selbst sieht."},{"option":1,"text":"Ein vorsichtigeres Wort klingt nach Sorgfalt, ändert aber nur den Ton. Die Einschätzung bleibt dieselbe, und der mögliche Denkfehler dahinter, die Übertragung eigener Maßstäbe, wird nicht angetastet."},{"option":2,"text":"Weitere Beispiele zeigen, was die Regierung tut, aber nicht, warum sie es aus ihrer Sicht tut. Mehr Material aus derselben Außenperspektive macht die Einschätzung nicht belastbarer, nur breiter belegt."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Heuer, R. J. (1999): Psychology of Intelligence Analysis. CIA, Center for the Study of Intelligence","oeffentlich":true,"url":"https://www.cia.gov/resources/csi/static/Pyschology-of-Intelligence-Analysis.pdf","seite":"33, 70, 181","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"e9968cf897868b83"}},{"id":"qx-b2-064","clusterId":"B","werkstueckRef":"B.32","stufe":2,"question":"Was ist an dieser Schlussfolgerung fehlerhaft, und was wäre der nächste sinnvolle Schritt?","scenario":"In einer Verhandlung stellt der andere Verband plötzlich eine Forderung, die deinem Team völlig unverständlich vorkommt. Eine Kollegin sagt: „Ich hätte an seiner Stelle nie so etwas verlangt. Er muss also bluffen und will uns nur unter Druck setzen.“ Ihr habt nie mit jemandem aus seinem Verband gesprochen, und in euren Unterlagen steht nichts darüber, wie er die eigene Lage beschreibt.","options":["Sie setzt das eigene Denken an die Stelle seines Denkens; sinnvoll wäre, zuerst herauszufinden, wie er seine Lage und seine Ziele selbst beschreibt.","Sie legt sich vorschnell auf einen Bluff fest; sinnvoll wäre, die Vermutung als Hypothese festzuhalten und gezielt nach Belegen für sie zu suchen.","Sie unterstellt der Gegenseite eine böse Absicht; sinnvoll wäre, ihr zunächst guten Willen zuzugestehen und die Forderung als ernst gemeint zu behandeln.","Sie urteilt nur aus dem Bauch; sinnvoll wäre, im Team zu besprechen, ob die anderen die Forderung ebenso unverständlich finden wie sie selbst."],"correctIndex":0,"explanation":"Die Kollegin beantwortet nicht die Frage, wie der andere seine Lage sieht, sondern eine andere: was sie selbst an seiner Stelle wollen würde. Das ist Spiegelbild-Denken. Die Frage „Warum würde ich so etwas tun?“ liefert eine Antwort über einen selbst, nicht über den anderen. Sie füllt eine Wissenslücke mit dem einzigen Modell eines Geistes, das sie von innen kennt: ihrem eigenen. Gerade weil niemand im Team die andere Seite aus eigener Anschauung kennt und ihre Sicht in den Unterlagen nirgends mit eigenen Worten vorkommt, ist die Schlussfolgerung „Bluff“ nur eine Vermutung und sollte nicht als Tatsache in die Verhandlung eingehen. Der nächste Schritt ist, die Sicht des anderen zu klären: über seine eigenen Worte, etwa eine Rede, ein Interview oder eine Beschreibung seiner Lage, und über Menschen, die seine Seite aus eigener Anschauung kennen.","coreRule":"⚡ „Was würde ich tun?“ ist eine Frage über dich, nicht über den anderen.","beleg":"Werkstück B.32 (Anwendung: Verhandlung & Alltag; Anti-Denkmuster)","status":"entwurf","kurz":"Die Kollegin beantwortet, was sie selbst an seiner Stelle wollen würde, nicht, wie er seine Lage sieht. „Bluff“ ist daher nur eine Vermutung; sinnvoll ist, seine Sicht über seine eigenen Worte und Kenner seiner Seite zu klären.","prueffrage":"Was hat der andere Verband selbst über seine Forderung gesagt, und wer im Team hat je mit jemandem von dort gesprochen?","rueckmeldung":[{"option":1,"text":"Die Vermutung als Hypothese zu führen ist vernünftig. Wer aber gezielt nach Belegen für „Bluff“ sucht, bleibt in der eigenen Sicht und findet vor allem, was sie bestätigt, statt zu klären, wie er seine Lage sieht."},{"option":2,"text":"Eine Absicht zu unterstellen ist tatsächlich unbelegt. Doch die Forderung automatisch als ernst gemeint zu behandeln wäre ebenso eine bloße Annahme. Das Problem liegt in der fehlenden Kenntnis seiner Sicht, nicht im Ton des Urteils."},{"option":3,"text":"Eine Teamrunde kann Blickwinkel ergänzen. Hier kennt aber niemand seine Seite aus eigener Anschauung, alle würden von sich auf ihn schließen. Dass alle die Forderung unverständlich finden, verrät nichts über seine Gründe."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Heuer, R. J. (1999): Psychology of Intelligence Analysis. CIA, Center for the Study of Intelligence","oeffentlich":true,"url":"https://www.cia.gov/resources/csi/static/Pyschology-of-Intelligence-Analysis.pdf","seite":"70, 181","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v7","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"e83041a9d1b546e7"}}]`);export{e as default};